window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_039"]={"n":"黄衷","dyn":"明","poems":[{"t":"春思和峰湖","f":"七言律诗","c":["为战酣春止酒难，云林悬愧竹皮冠。","鸠缘报雨动相聒，风欲开花淡不寒。","月俸赢钱炊桂了，夜堂烧烛借梅看。","枕屏莫卜劳劳梦，我是空门古懒残。"]},{"t":"送曹本忠出守临江","f":"五言古诗","c":["何幸际明扬，英年绾郡章。","人誇神女赋，自扫盖公堂。","列骑摇新幰，蟠鹇换旧裳。","山河分职贡，羔雁接班行。","白璧知无玷，朱弦待改张。","控强方剪韭，理剧类鞭羊。","倚剑吴天碧，吹铙楚水长。","春风翻弱絮，无奈御离觞。"]},{"t":"乌江雨中","f":"七言律诗","c":["一片阴云广莫连，行衣初卷楚江边。","马辞南豫鸡声少，风转西原雨脚偏。","残戍半樊分野火，斜流百折下芜田。","寒灯暂对山斋夜，不学萧条叹独贤。"]},{"t":"送王户书南征","f":"七言律诗","c":["保釐持轴素称任，暂见专征命节临。","国赖兼才全重势，虏观长技折强心。","态旂队罢皆成列，犀甲围闲总若林。","张说莫誇和九姓，明公威德胜淮阴。"]},{"t":"药日","f":"七言律诗","c":["谩检谁家海药馀，更收离气向房虚。","燃膏池馆参先尽，引沥邻园竹渐疏。","俗吏劳形缘簿领，神巫占祟应诗书。","何人授我真仙诀，也学含光守六居。"]},{"t":"题朱升之琴鹤遗音卷","f":"七言古诗","c":["断纹掩抑浮云轻，临霞繊吭十二鸣。","青皇振蛰水龙泣，雕虎啸壑回飙生。","高山峨峨带寒日，广陵妙散谱不出。","崆峒仙骨沦金精，烟交雾净疑毛质。","世徂神物亦乘化，划然惊耳千风下。","谁令清绪播人寰，考亭壮岁功名大。"]},{"t":"赠顾全州二首 其一","f":"五言律诗","c":["远道君于迈，幽期我所从。","江平潮款款，烟黯树重重。","宿寺分寒炬，扬帆背晓钟。","三湘风日美，应不负奇踪。"]},{"t":"赠顾全州二首 其二","f":"五言律诗","c":["山水诗情在，乾坤道味深。","谁堪今日别，君见古人心。","到郡徵新化，因风忆嗣音。","羽仪应自惜，上国有乔林。"]},{"t":"和施彦器宪副","f":"五言古诗","c":["君从何方来，奇胸讵多得。","但指龟在涂，或诵蝇止棘。","岂无国士风，所虚理人职。","岂无蓄盖私，所见鸣仗斥。","采苓困首阳，宰社拜曲逆。","缅怀天步遥，只觉周道直。","归欤雁荡山，千峰抱云黑。","灼灼东篱英，聊以试酒力。","宁烦藉二桃，谁能顾双璧。","于此有玄思，众人固不识。","君情我所钦，晤语附深臆。"]},{"t":"决池篇","f":"七言古诗","c":["汉家防事习水战，今朝忽报开昆明。","片纸朱批下乡里，官票频催调健丁。","健丁二十堪差调，中男十四仍嫌少。","强将笠子撮短发，宁忍欺官免追召。","公家作役敢告劳，难平夫长恣侵嗷。","付钱监吏须笔墨，终日未保无鞭敲。","去岁五侯建第时，我为上户已倾赀。","而今又报是殷实，会令鬻子官岂知。","昨日何人起赤城，我锄正似尔杵声。","只道决池藏战舰，那知耀德不观兵。"]},{"t":"奉见素先生二首 其一","f":"七言律诗","c":["手持漫刺向谁门，宪府风流众所尊。","犯色排奸那避险，倾心推士不言恩。","共知高步云霄远，尚忆乔林水石存。","欲拟襟期何处所，东溟无际吐还吞。"]},{"t":"奉见素先生二首 其二","f":"七言律诗","c":["万夫众里望堂堂，道气词华两擅场。","名下欧韩堪并世，海边邹鲁是先乡。","临池摇笔光风洒，闭閤焚香静昼长。","浅薄敢承师说迹，愧随同舍到门墙。"]},{"t":"寿淮安王正郎父母","f":"七言律诗","c":["门通驷马庆犹繁，萱秩椿龄喜并尊。","红玉驻颜如稚子，黄眉盖目戏曾孙。","龙纹护诰双衔命，凤历题年六改元。","遥想淮南开寿域，蜡梅花下倒琼樽。"]},{"t":"冬夜同田曹长月下对菊各赋一首","f":"七言律诗","c":["日精开遍月光扬，此夜寒堂引兴长。","灵艳只缘矜晚节，浓香偏自过重阳。","谁知旧圃先含雨，天为新妆旋著霜。","忽忆南中三径上，数枝深浅满烟黄。"]},{"t":"闻雁","f":"七言律诗","c":["胡儿雪后试弓初，寒雁惊飞绕碧虚。","傍月悲鸣过海曲，断风残韵彻庭除。","长门可奈孤灯影，远戍谁收一字书。","何事年年来复去，江南春渚足攸居。"]},{"t":"次韵赠耕隐","f":"七言律诗","c":["闲逐农谈度岁华，古风应似晋元嘉。","山鸡可狎凫将子，郭索初肥稻有花。","秋秒徵桑为井税，春来插槿别邻家。","凭君莫问市朝事，沙上萧萧蓬倚麻。"]},{"t":"送张太仆报绩","f":"七言律诗","c":["石桥行色属车分，晓入明光奏上勋。","柱下直言传旧疏，卷中小雅变时文。","爱才每辍周南食，考牧常空冀北群。","瘦骨未应愁伏枥，愿将千里试浮云。"]},{"t":"次韵太仆留别","f":"七言律诗","c":["光辉重拜楚江东，道论知心与貌同。","千仞翩翩韶舞凤，九霄款款易爻鸿。","燕歌静夜听行苇，身遇明时笑累蓬。","雪履朝来方拥彗，严旌应不避居穷。"]},{"t":"南浦驿赠升之","f":"七言律诗","c":["白下才名方盛时，仙曹谁不避英姿。","一挥黄石桥边屐，平麈朱湾卷上诗。","爱我信能生羽翰，逢君恨未罄肝脾。","翻嫌韩语矜豪幻，何得云龙上下随。"]},{"t":"杂兴","f":"五言古诗","c":["我家南山下，种豆觊逢年。","沉冥亦晏坐，长咏南山篇。","郁郁两佳木，广樾阴已便。","飞鸟出其下，中有静者天。","驱鸡护蔬甲，促婢饭西田。","壶浆聊自劳，濯发蒲涧泉。","手把竹如意，高话羲皇前。","千古亦旦夕，传者皆英贤。"]},{"t":"秋夜宿乌江山寺","f":"五言律诗","c":["倦徒趋古刹，偃盖息云萝。","败饵罝残鼠，明膏毙赴蛾。","戍营砧互发，山郭漏偏讹。","蟋蟀昧行旅，吟依缱绻窝。"]},{"t":"题于石图","f":"五言律诗","c":["倚屏蕉扇冷，拂黛竹茎疏。","浩气蒸云遍，寒声战雨初。","贞含幽士抱，静惬野人居。","不是池台品，无劳甲乙书。"]},{"t":"葵扇","f":"五言律诗","c":["动以风化成，形将月与侔。","欲清天下暑，长带岭南秋。","编羽宁论巧，裁纨只障羞。","千年一变态，开箧璧光浮。"]},{"t":"挽庄定山和见素子二首 其一","f":"七言律诗","c":["择君敷衽奉先皇，謇謇曾囊极谏章。","众稚口中成市虎，九夫肱下有坟羊。","虚车不见同人迹，古镜深含照魅光。","磬室萧条唯四壁，伤心初服芰荷香。"]},{"t":"挽庄定山和见素子二首 其二","f":"七言律诗","c":["修篁袅袅锁旋岚，圣草犹悬燕子龛。","世上宦情同柳下，山中诗体逼周南。","独藏秘器松将拱，难制颓龄菊自甘。","野客正惭归彀晚，素风空想二毛毵。"]},{"t":"煎茶和赵侍御二首 其一","f":"七言律诗","c":["缕烟何处烛清虚，知是乌台退食初。","青咮出笼分乳雀，絮花浮鼎噀游鱼。","竟陵录后名方远，顾渚春前叶已疏。","渴梦十年消未得，寒泉谁致惠山馀。"]},{"t":"煎茶和赵侍御二首 其二","f":"七言律诗","c":["桃花初乞楚山春，歌罢新辞已动人。","双井密云香讵歇，八公甘露迹空陈。","湘瓷闻色宁同格，卢碗浇烦觉有神。","岁晏因君方赏味，小斋擎盏忆相亲。"]},{"t":"和王大参四首 其一","f":"七言律诗","c":["小住迢遥王汉槎，怀中短刺适谁家。","偶依书带庭前草，难应金围会里花。","字雁秋风声递远，甘棠春野绿交加。","期君系肘征西印，肯避王阳石栈斜。"]},{"t":"和王大参四首 其二","f":"七言律诗","c":["通才端似老操舟，急濑旋涡少滞留。","暂御五弦当小暇，凭将孤剑共先忧。","滕王高閤题诗过，孺子澄湖建节游。","更与西山添爽气，炎烟初散庾尘收。"]},{"t":"和王大参四首 其三","f":"七言律诗","c":["旧业斋州岱岳东，湖西持檄远宣风。","肯因鼯鼠将机发，曾见全牛落刃空。","感激每凭青史信，委蛇方退紫薇公。","乔林莫遽思高尚，混迹渔樵世不同。"]},{"t":"和王大参四首 其四","f":"七言律诗","c":["喜笑终难老一乡，太平今是日重光。","年华疾隼投繁荫，世味游蜂绕艳香。","豪侈近嫌南郡马，风流遥忆颍川黄。","吏休小放东林骑，拚与山僧半日忙。"]},{"t":"上新河送时雍少参兄","f":"七言律诗","c":["都门终日望旌旗，忽到都门又别离。","未慰亲情惭唤弟，每承高谊喜兼师。","旧谈积水灯悬久，宦舍濒江棹发迟。","唯有北风堪送客，楚天何处附遐思。"]},{"t":"送杨奉常","f":"七言律诗","c":["玄文奇字动时英，合继平章海内名。","吏部权衡考功氏，容台礼乐奉常卿。","蒹葭渺渺秋风传，榕叶阴阴昼锦城。","喜近北堂谖草色，黄金小带膝边横。"]},{"t":"题杨梅卷","f":"七言律诗","c":["紫腴青润茧光流，尚忆包山是故丘。","日暖砂腾勾漏晓，月华珠弄甓湖秋。","文园病渴功堪录，泽国苞芳实已收。","从道荔枝恩尔许，当时空上翠钗头。"]},{"t":"西台壮丹和储柴墟二首 其一","f":"七言律诗","c":["白版红楼总未过，雨中赢得对阴何。","一枝自占西台胜，百卉从教下土多。","辟冻可曾依煖棘，护芳应与荫云萝。","始知韩令功名薄，不为秾华惜旧柯。"]},{"t":"西台壮丹和储柴墟二首 其二","f":"七言律诗","c":["朱轮冲雨尚频过，春色晴华更几何。","南国风流聊复尔，东都名胜已无多。","评香不独齐芳杜，附艳无因学女萝。","若使相君长献御，黄缯先系向阳柯。"]},{"t":"和州道中","f":"古风","c":["折阪沿秋水，邮亭傍晚原。","桔槔横浅壑，屈戌闭衡门。","霸庙青芜合，渔洲翠蓧繁。","荒城思范迹，衰草吊虞魂。","序气兼朱素，征衣间爽煴。","云屯胡堞隐，犊下楚山昏。","桑柘影弥翳，蟪蛄声亦喧。","词人感张藉，地主问何蕃。","涨潦稽前骑，微?阻后村。","只能劳候吏，何德副乘轩。"]},{"t":"和陈台州田园杂兴四首 其一","f":"五言律诗","c":["旨酒答芳辰，幽花即可人。","逢山寻委羽，喻海托潜鳞。","茅笔雠书遍，柴车出郭频。","谁知扪虱者，豪气盖三秦。"]},{"t":"和陈台州田园杂兴四首 其二","f":"五言律诗","c":["钓泽应星辰，东园果若人。","亨还履虎尾，危是犯龙鳞。","自得观鱼乐，谁来问字频。","更将诗喻战，卷甲避强秦。"]},{"t":"和陈台州田园杂兴四首 其三","f":"五言律诗","c":["白草带坰墟，閒堂是隐居。","饮醇无所事，读易到斑如。","山色高秋后，鸦声落照馀。","南中开石室，他日有藏书。"]},{"t":"和陈台州田园杂兴四首 其四","f":"五言律诗","c":["唤艇趁沙墟，还归杜曲居。","花边谁得似，世上近何如。","芳思孤烟外，高谈万古馀。","正嫌西蜀客，迢递献权书。"]},{"t":"出湖","f":"七言律诗","c":["为爱南来五两轻，长年屈指记兼程。","入湖飞鸟悬天影，撼岸惊涛近枕声。","江汉谩传多委会，庐山瞥见未□明。","船头滴酒人人喜，谁道风波不可行。"]},{"t":"入京寄子章弟","f":"七言律诗","c":["王河堤畔觅驴骑，王述形容果似谁。","食断桂烟蚨母尽，书过梅雨雁奴迟。","缁尘荏苒迷翔鹭，缃帙凋零负铸龟。","欲向铨衡乞閒散，南曹衙退有幽期。"]},{"t":"江晚","f":"七言律诗","c":["呼风唱棹逐前艖，自觉江程晚更赊。","极浦雁行连螮蝀，夹洲渔火入蒹葭。","浪痕到石潮还信，人影移湾客未家。","莫向三山冲晦望，海天明日正晴华。"]},{"t":"经故侯第","f":"七言律诗","c":["河水涟漪漾柳丝，主人何处海天涯。","语低社日雌雄燕，泣断春风子母狮。","乐本旋侵闲路径，花游还剩旧台池。","邻西老妪惟贫病，借问传呼今是谁。"]},{"t":"放鳖行","f":"古风","c":["苍头沙市笑以呼，双鳖止费六青蚨。","北人到死不知味，枉教枵腹如悬壶。","庖丁拂刀古水白，腥涎染锷□苔滑。","壳间闭眼立香脂，藏头疑怖持权客。","君不见烹鼋召诸子，鼎前怏怏强臣指。","国君嗜味且复然，况我平生佩兰士。","卫河秋水昏朝雾，纵渠棹尾泥中去。","顽形岂解识恩私，不似神龟能左顾。"]},{"t":"寄赵叔鸣","f":"五言古诗","c":["因君驻遐想，渺渺五云峰。","秋兰适盈把，言赠无由从。","况闻一苇杭，往来亦憧憧。","所稀同心人，恐迷寄前踪。","于时白露繁，幽姿照芙蓉。"]},{"t":"平蛮奏凯为王户书赋","f":"五言古诗","c":["帝曰咨元老，蛮方有沴氛。","中权为总帅，外阃制诸军。","金舄承龙节，铔鍜列虎贲。","投壶神略静，约矢檄书纷。","传令山皆应，扬戈日不曛。","汗挥亭午雨，袂障肆天云。","设伏扬那隘，游兵者卜濆。","前车初转战，后骑竟收勋。","衅鼓歼渠首，降旗款虏群。","爇原仍辩玉，刈泽复滋薰。","敛象天狼晦，褫魂夜鼠焚。","共危当弩缟，还哂负岗蚊。","事繁华夷望，人依父母君。","红箱饶积聚，绿野遍锄耘。","凯入千官庆，俘回九庙闻。","稚歌弥宇宙，喜气洽氤氲。","造化丹青妙，功名鼎鼐芬。","登坛凭用武，开閤待敷文。","异数弓裘嗣，淫威鼓吹分。","司徒拜稽首，明主继周殷。"]},{"t":"咏绳","f":"七言律诗","c":["穿帷入袂日纷腾，欧九词名谩得称。","不落奸雄准端梦，却生文士眼前憎。","清谈精舍频挥麈，绮食豪家尽护缯。","安得金风吹四野，毛诗吟罢思难胜。"]},{"t":"宿杨给舍宅","f":"七言律诗","c":["禁城西畔子云窝，穷客驱羸过玉河。","书閤暂来催扫榻，里门曾见号鸣珂。","嬉谈不离文词外，抚事其如岁月何。","肯为病容方却饮，南曹风味本无他。"]},{"t":"寄述古翁","f":"七言律诗","c":["身在江湖道自尊，登堂长见古风存。","王通著论全经世，徐孺明农祇闭门。","踪迹暂时逢郡守，姓名何处号轩辕。","从前检校醇儒行，清苦无劳并日餐。"]},{"t":"出京","f":"七言律诗","c":["结束征车趁晓晴，客心长儗剧悬旌。","攀杨意气交游远，倚马寒暄感慨生。","鬓发十年行路影，秋风千里过江声。","蓬窗醉枕雌雄剑，怪得无端一梦惊。"]},{"t":"赠乡翁","f":"七言律诗","c":["江上归来白发新，征衣犹自带缁尘。","鹁鸪唤雨闲林晓，舴艋回风小岸春。","榕叶阴中谈上国，槿花丛里过东邻。","年来减却催科令，应是康衢一老人。"]},{"t":"杨汉中画菊歌","f":"古风","c":["今世画工信如市，下笔纷纷桃与李。","何人却负高秋姿，毫端萧瑟金飙起。","金飙起时百草乾，西园丛菊露漙漙。","苦心只答天地肃，劲气宁知霜霰寒。","万铃浅间邓州白，闲堂粲粲悬佳色。","异种还闻是日精，孤根祇见依崖石。","蝶怨蜂愁殿众芳，繁枝肯为覆银床。","坐令几案并五美，休誇粉绘空文章。","自古高人非寂寞，陶家不是闲篱落。","未见南山一片心，谩道元公品题错。","君不见落英之效秘以神，年华冉冉悲灵均。","凭将妙用寿区宇，何但南阳百岁人。"]},{"t":"挽杨质夫学宪","f":"五言古诗","c":["素望弥区宇，英灵出甬东。","两魁皆士选，再命亦儒宗。","绛帐春风外，乌台夏日中。","虞渊窥学富，武库避词雄。","后进哀前哲，明时惜钜公。","祥鳣虚鼎位，大鸟泣堂封。","胡氏承清白，刘家起异同。","千年闻化鹤，众口叹犹龙。","画省标人品，仙郎有父风。","定馀垂翅恨，附此渐逵鸿。"]},{"t":"和坡山晚望 其一","f":"五言律诗","c":["平野白茫茫，应知秋气强。","闲行近古水，款语洽春阳。","竹静莎鸡泣，山寒石蜜香。","客心殊未极，讵为入城忙。"]},{"t":"和坡山晚望 其二","f":"五言律诗","c":["树色递微茫，登临晚较强。","月轮浮海曲，斗柄背山阳。","化腐流萤火，烧荒走麝香。","此时休极目，云鸟正奔忙。"]},{"t":"戏和贫女叹","f":"七言律诗","c":["少小曾登乞巧楼，缣衣断碎怕逢秋。","翠蛾谩约山相似，素腕谁知玉可犹。","北里归期春信近，东家绩火夜光收。","邻姬解道无盐事，斜倚屏风自障羞。"]},{"t":"赠汤鍊师","f":"七言律诗","c":["不因寒暑换行衣，百里山程顷刻归。","遣日只调双鹤舞，问年惟记九龙飞。","林中植杖为芳树，市上留辞寓道机。","我欲从师何处所，白云长恐与心违。"]},{"t":"题乔正郎贞节卷","f":"七言律诗","c":["四十馀年锁镜尘，剪鬟长誓结缡人。","岂无小鸟填波恨，信有寒崖化石身。","寿域柸分霞帔煖，家园花放板舆春。","贤郎同省多豪俊，谁似当时末座宾。"]},{"t":"送郑立之少参闽藩","f":"七言律诗","c":["三山南去入烟霞，傍马春光岂觉赊。","黄鸟声中饶别思，鹧鸪词后艳才华。","六曹选望须参省，十载怀亲恰过家。","谁遣疏慵继芳躅，祇应惭愧夏官衙。"]},{"t":"春官旧寅见期牛首之游不果赴","f":"七言律诗","c":["紫骝嘶断杏花烟，佳丽无如二月天。","谩爱东曹兼吏隐，不堪南郭负仙缘。","流尘定锁题诗处，老衲应论借榻年。","遥指聚星空怅望，芙蓉高閤化城边。"]},{"t":"挽太虚上人","f":"七言律诗","c":["菩提无树着灵葩，弟子谁当绍法华。","七宝浮屠藏舍利，五花香供礼袈裟。","住时却悟前生妄，去日应知后果赊。","从此空山人不到，止交莲社忆兰奢。"]},{"t":"梅正郎荣寿卷","f":"七言律诗","c":["晴风彩袖引鱼轩，庆似江流信有源。","潘苑日长珠翟丽，谢庭春煖玉枝繁。","东曹食鼎纷中馈，南国歌钟接上元。","谁记蓬山瑶海事，人间此乐不同论。"]},{"t":"送梅惠州","f":"七言律诗","c":["都官文藻信犹龙，道是云仍复亢宗。","捧檄晚来还对署，把麾南去却邻封。","雾中烟火黄湾路，梦里莺花白下踪。","五马本荣忧转切，岐亭惟有思重重。"]},{"t":"浦口城南晚望","f":"七言律诗","c":["浦城南畔万峰层，出郭全消百感兴。","长笑呼风杨子客，伛偻携钵定山僧。","清秋自爱乘游兴，暇日谁能坐曲肱。","极目已窥吴楚遍，故乡云树最无凭。"]},{"t":"大椿歌","f":"七言古诗","c":["画堂清昼光如水，古椿秀色盘烟紫。","吐灵纳妙动千年，曾见琼花几回徙。","堂前寿母朱颜酡，板舆霞帔弄婆娑。","麻姑白鹿时复到，西海青禽岁一过。","芳桂分丛截青玉，花露馨风飞宝粟。","帝令移向广寒殿，渐看圆影扶疏绿。","娇鸾小凤亚枝鸣，香兰瑶草绕根生。","谁言呵护非神物，天东老人为应星。","长记年年六月八，歌□酬宴长生国。","笑倚青苍计海筹，嫦娥双黛将相白。"]},{"t":"和张太仆对菊感怀","f":"五言古诗","c":["琅琊秋兴早，吏功复休沐。","骑曹大雅资，芳玩信所独。","嘉树隐逸丛，清尘洒微霂。","床敷共语默，幽诺良已宿。","两曜逆旅期，宾赏须继烛。","高花方德人，整整巾履肃。","低枝敌兰荃，初服佩芬馥。","碎琐黄金钿，亦掩红踯躅。","湘累泛英客，薪桂不炊粟。","闻制短世龄，惠贶勤一掬。","犹得对何充，瓮蚁泼新醁。","鄙人社前栎，当就閤上束。","迩来或天幸，数面亲海陆。","况谢枉见临，徽音嗣空谷。","何日东篱边，跫然听马足。"]},{"t":"送汪南宁","f":"七言律诗","c":["遐方选牧必贤豪，慰远宁辞五马劳。","何用黄金为土产，从来红腐是民膏。","滩声转急龙州近，山势遥攒象郡高。","风雨未迷君去路，客心空自绕旌旄。"]},{"t":"题李水部月殿秋香卷","f":"七言律诗","c":["万里桐风吹素天，清虚楼閤澹娟娟。","人间谩爱凉如水，枕上空疑夜是年。","兔影斜涵丹桂陌，鸾声细落白榆烟。","晚来斗帐寒香透，只恐萧郎骨已仙。"]},{"t":"题李源书院","f":"七言律诗","c":["引涧栽花逐路新，东风篱落逗酣春。","天鸡惯狎谈玄客，山犬长迎问字人。","绛帐生徒闲爵里，紫阳灯火旧比邻。","故家三万牙签轴，莫等悠悠纸上尘。"]},{"t":"寿胡司谏父母","f":"七言律诗","c":["花下溪边一事无，年来家庆足欢娱。","渐如餐蔗当佳境，正儗临萱对寿图。","鸠杖每深桑梓敬，鱼轩还爱子孙扶。","鹿门山下烟霞路，却近閒人击壤途。"]},{"t":"移家长安西街五年前是予旧居","f":"七言律诗","c":["长安门外石桥西，穷客奚囊带雨携。","生事偶同鸠借垒，尘踪巧似燕归栖。","闲庭依约槐风细，浅岸伤心柳浪低。","僮仆何知犹感叹，经过不是旧轮蹄。"]},{"t":"寿厚斋先生二首 其一","f":"七言律诗","c":["五岭勋名二相前，百官仪羽一身全。","昌期将启元丰运，间气先钟丙午年。","化洽金瓯分画壤，心如宝带合通天。","寻常何必求瑶海，长傍炉烟即列仙。"]},{"t":"寿厚斋先生二首 其二","f":"七言律诗","c":["寿域光阴六十馀，麒麟新锦照金鱼。","清班上列还端揆，信史前名是特书。","直道只期匡帝范，遗才尝赖到公车。","霖收日丽乾坤泰，惟有南山殿玉除。"]},{"t":"寿胡封君","f":"七言律诗","c":["身际隆平向百年，谢公隐处接苍烟。","静来见事闲差胜，老去蒙恩乐更便。","世上贤良文定后，山中宾客□光前。","期君且款秋风棹，家庆何如志养全。"]},{"t":"閒居杂兴和丁选部四首 其一","f":"七言律诗","c":["野柽鸣飙秋满庭，䫿颾不似故园听。","尘埃是处苍鹰击，气色谁家瑞鹊灵。","心验五穷知匪席，口经三噤信如瓶。","欲携白木长镵去，自斸松根千岁苓。"]},{"t":"閒居杂兴和丁选部四首 其二","f":"七言律诗","c":["晨麾阁吏散公庭，缓步微吟与鹤听。","儗托风云期道泰，耻将虫鼠试丹灵。","有功归赵仍完璧，何意誇秦类建瓶。","今日膏肓维一息，神医谁为减狶苓。"]},{"t":"閒居杂兴和丁选部四首 其三","f":"七言律诗","c":["城上乌号彻夜庭，遥星断角带愁听。","风霜犯骨髭先改，山水违心卜未灵。","书爱守玄还覆瓿，贫怜炊玉有悬瓶。","美芹自昔閒人事，谁向王羞进茹苓。"]},{"t":"閒居杂兴和丁选部四首 其四","f":"七言律诗","c":["衙冂尽日闭闲庭，坐对谈天力倦听。","七步谩誇逢洛女，数峰终解咏湘灵。","慵须报客方脩刺，智不如人可挈瓶。","小苑春来成晚计，却移红槿种参苓。"]},{"t":"书李主事传","f":"五言古诗","c":["伊人郎署资，矫矫乃遗直。","读书乱山中，讵肯徇甔石。","圣明允神断，血狱岂冤抑。","所具棘下臣，疑情固当白。","南裔佩赐环，山水含古色。","嗟哉秘英灵，使我永叹惜。"]},{"t":"慕萱卷","f":"七言律诗","c":["春风转蕙萱草生，秋霜欲陨鶗鴂鸣。","北堂无人月流影，坐此摇落伤人情。","独抱悁悁向萱草，白杨根断□壤杳。","儿泪无因到窈冥，儿心但忆春风早。"]},{"t":"送丁胄监","f":"七言律诗","c":["多才谁不带清光，君尚儒衣返旧乡。","山水业成尘梦少，江湖道在客心长。","诗声侯喜新鸣世，文体镏几后擅场。","别思经秋更摇落，蒹葭凉露晓苍苍。"]},{"t":"挽陈封君","f":"七言律诗","c":["平生缨冕等流尘，湖海曾闻遁俗身。","幕下恨无唐处士，冢前惊见宋诗人。","书斋直闭黄鹂晓，茶灶空馀白芷春。","谁貌梅花行乐影，豸冠方换紫纶巾。"]},{"t":"和计封君","f":"七言律诗","c":["芙蓉江上正宜霜，千里秋容逗末光。","儗向家山长作主，懒分星座谩为郎。","醉偿花事鸬鹚杓，闲赴鸥盟薜荔裳。","闻道凤毛霄汉迥，祇应高枕敌侯王。"]},{"t":"寿薛封君","f":"七言律诗","c":["旧隐门前五柳风，新恩诰上锦花丛。","崆峒有道屯蒙秘，禹穴多奇表传雄。","寿域歌钟应速客，年家分义合称翁。","欲知庆泽无穷处，令子名高□省中。"]},{"t":"发都城","f":"七言律诗","c":["云霁钟陵晓冻轻，桥门飞鞚上初程。","油车分御嫌家累，绮席留欢念友生。","沿涧或逢晴鹊浴，入村才及午鸡鸣。","兹行犹是星摇夜，悄悄徒深慰物情。"]},{"t":"云阳晓行","f":"七言律诗","c":["衡门犹闭晓钟疏，马首回瞻月影馀。","石窦煖时藏促织，冰澌融处立舂锄。","田家久歉晨炊晏，山县恒阴日晷徐。","我仆莫辞驱策倦，江湖何地足宁居。"]},{"t":"丹阳登舟","f":"七言律诗","c":["山城返照上楼台，迤洒遥从北固回。","委巷人归沙市散，邮亭吏报夜冰开。","暂分江火鸣铙去，讵忆风霜振策来。","客思不缘贪浩渺，王程宁为岁华催。"]},{"t":"初至霅上斋阁对雪","f":"七言律诗","c":["阴浓晴淡积旬馀，电晦雷潜雪意舒。","瑞气共占为霰后，神功谁道作霖初。","煖回玉树晨犹合，风入苍筠夜渐疏。","更向水晶宫里见，寒光知与月何如。"]},{"t":"送何继善出守湖州分韵得渭字","f":"五言古诗","c":["何君湖海豪，风格素简贵。","时名动京国，万乘亲赏味。","阅世嗟瑕瑜，虚心洞泾渭。","初持大行节，再典司农饩。","竹符作诸侯，花封趋县尉。","出都日次鹑，至郡斗建未。","三勤民劝劳，五教俗移气。","夹溪拣芽人，比屋浴蚕媦。","□见□鞭蒲，坐使歌蔽芾。","伟哉财赋邦，得君天子慰。"]},{"t":"杂叙寄坡山","f":"五言古诗","c":["东园有奇士，无乃希夷子。","才堪起词头，名懒署纸尾。","怀古几惘然，阅世一莞尔。","岂无虎插翼，信有骥垂耳。","家泉破山碧，石蕨逗云紫。","小出命柴车，大隐呼锦里。","本不见清浑，谁能测涯涘。","剧谈恕我往，频来当公意。","双鸟鸣未穷，孤鹤梦难恃。","展转徒所思，裁诗附江鲤。"]},{"t":"高千兵歌","f":"七言古诗","c":["苍梧将军豪且清，司马府中新策名。","寿翁矍跞秘韬略，将军耳后雄风生。","太丘堂上初识君，夺槊调弓冠羽林。","龙鳞锁甲欺青镜，马首樊缨络紫金。","南中密堠方传箭，幕下兵机少奇变。","土官突骑驾浮云，山徭毒砮藏深堑。","安得快剑如清冰，宝精耀日光棱棱。","控此强黠纵横行，将军为我为先登。"]},{"t":"用韵答俞四府咏雪","f":"七言律诗","c":["陂陀疑是陆沉馀，整整斜斜卷以舒。","兔迹已迷三窟远，鸡声偏咽五更初。","梁园授简才何健，剡曲回舟兴亦疏。","茶鼎晚来谁赏味，寒堂思杀渴相如。"]},{"t":"迎春和俞四府","f":"七言律诗","c":["□□呈岁错时羞，戢戢芹芽胜玉钩。","此日有花迎曙色，谁家无力控春愁。","东郊鼓角青皇令，上国楼台綵树头。","邑里总祈宽大诏，物华浓处是宸游。"]},{"t":"俞四府宅赏牡丹","f":"七言律诗","c":["香腴粉腻压烟攲，尘里相看敢怨迟。","富贵不缘天所授，秾华得与地相宜。","薰风院落酣春晚，舒日帘栊正午时。","只道戎葵堪比并，柳侯何必旧能诗。"]},{"t":"登道场山","f":"七言律诗","c":["木杪垂虹石径横，葱青隐约见飞甍。","苍烟近带罗山秀，紫气遥含震泽晴。","何代高禅闻伏虎，有时清梵接啼莺。","暂来不为乘幽兴，道是春畬蚤已耕。"]},{"t":"坡山寄示喜予得郡之作次韵春答","f":"七言律诗","c":["共戴重离照万方，误恩何意录清狂。","家山不到嫌逋客，曹局违期信慢郎。","得郡敢争如斗大，怀君转觉与天长。","他年欲了东园约，莫怪无金可罄囊。"]},{"t":"答子章弟","f":"七言律诗","c":["纵迹初逢墨妙堂，残碑曾识旧文章。","湖光亦似投书浦，诗格何如奉礼郎。","广院槐芬蝉语寂，满江秋色鹤程长。","谁能更学东方朔，折桂门前奉一囊。"]},{"t":"答孙太初夜访二首 其一","f":"七言律诗","c":["太华山人夜泛湖，西风吹过藕花居。","扣门已值梵钟定，呼酒不来村店疏。","自振初衣闻杜若，偶寻奇迹问樵渔。","回船倒压星河影，绝胜浮槎上碧虚。"]},{"t":"答孙太初夜访二首 其二","f":"七言律诗","c":["吴越高人道姓名，何年饮露得身轻。","暂从雷硐留诗品，未到苕溪闻笛声。","转树猿吟秋兴早，横江鹤梦月华清。","悬知世故浮云外，正儗辞家问广成。"]},{"t":"赠施新斋","f":"七言律诗","c":["手上兵权弃若违，閒林休讶见人稀。","世间尘网鸥盟在，天际樵歌鸟道微。","白露满庭时读易，青松绕舍昼扃扉。","山姿最是秋深好，可爱流云向晚归。"]},{"t":"书陆子渊水喻","f":"五言古诗","c":["陆才果如海，喻水海若泣。","东曹助洪澜，潮头浴暾日。","千年水晶宫，紫雾金铺湿。","持此照妖祟，正昼蛟龙立。","鱼虾信琐碎，跳梁但策策。","愿言蓄馀彩，勿为鬼神得。"]},{"t":"游灵谷寺分韵得门字","f":"五言古诗","c":["黄埃辞鞅掌，净域迩丘樊。","劫换僧前树，烟虚鸟外村。","松高微见塔，峰峭郁当轩。","画壁菩提秀，缭垣薜荔昏。","循幽频徙履，选胜辄临尊。","轻帻窥泉镜，长裾拂槿原。","夕阳衔远堞，瑞霭带高园。","归马将残醉，依依东郭门。"]},{"t":"援开化","f":"七言律诗","c":["映柳穿花于重旌，辕门订日合专城。","千山旧雨弓刀恨，一道长风鼓角声。","才子时来焚玉草，诗人老去洗兵行。","凭谁早定收功策，尚及西畴带煖耕。"]},{"t":"马金镇","f":"七言律诗","c":["赤鸠声急曙光斜，久客逢山梦亦赊。","雉纛亭亭清道雨，熊车款款浅溪花。","僧依白社还芟麦，人逐红巾未奠家。","幕下更咨深入计，不妨云鸟驻前沙。"]},{"t":"送顾开封谪全州次刘西安韵二首 其一","f":"七言律诗","c":["湘流清浅晓飔平，舟发东方尚未明。","万里若为伤此别，几人能不负平生。","江湖白鸟愁君处，风雨青山逐客情。","惟有汩罗传赋咏，遐荒犹得儗贤声。"]},{"t":"送顾开封谪全州次刘西安韵二首 其二","f":"七言律诗","c":["路与潮阳去几何，过家踪迹故婆娑。","江亭红雨春姿澹，烟郭青枫秋兴多。","改服止应收物论，投荒仍得带恩波。","中原岂不须才俊，环赐将从五岭过。"]},{"t":"宴浮碧亭","f":"七言律诗","c":["亭前古柳断烟疏，亭后长松委径馀。","花近雕楹春掩映，月临珠浦夜清虚。","东山旧望题诗在，南郭幽期放吏初。","却见高城分井邑，几家灯火遂攸居。"]},{"t":"清河晨望","f":"七言律诗","c":["漠漠重阴蔽晓暾，偶随风羽瞩高原。","鹅黄潋滟韶年换，狐白蒙茸野气昏。","战火连冈馀胜社，炊烟带雨起颓垣。","伤心鸿雁哀鸣地，惟有长林冻雀喧。"]},{"t":"京口渡同刘婺州望金山寺","f":"七言律诗","c":["静阅流尘万劫过，玲玲钟磬隔沧波。","中天气色金陵外，上界光灵铁瓮多。","有客解形遗水石，老僧施食到鼋鼍。","未登比岸缘风信，徒倚膺舟羡薜萝。"]},{"t":"同胡方伯游虎丘寺","f":"七言律诗","c":["从来幽兴竞山长，况复山塘七里强。","秪树排云全古色，画船冲雨为新凉。","寒泉尚挹高人抱，霸气终收故剑光。","惟爱同游贤岳长，暝钟犹访讲经堂。"]},{"t":"送邃庵公赴陕西用原韵二首 其一","f":"七言古诗","c":["王道如弦宦海遥，英年矫矫即登朝。","诗城兔颖当春健，史案兰膏照夜烧。","学彻古今三策浅，力回骚雅百家消。","上公问义金貂候，中座生风玉麈摇。","秦地河山饶胜迹，陆庄桃李荫长条。","青阳尚带霜威冷，行色先含淑气调。","国势可凭人望重，天工有托主忧销。","三千騋牝风堪咏，百二雄图业已彫。","居易何才承顾奖，之罘无分负韩招。","旬宣多暇劳咨访，壮士从来伏钓樵。"]},{"t":"送邃庵公赴陕西用原韵二首 其二","f":"七言古诗","c":["咸阳隩区何遥遥，旧称天府群雄朝。","重关百崄为敌守，沃野千里缘耕烧。","横桥南渡银汉渺，高屋上建瓴水消。","河流呼吸撼地轴，岳撑峍屼干招摇。","东制连衡一百万，西来约法唯三条。","吴贤曾叹国风美，赵伯亲承锦瑟调。","钟山王气不可厌，十二金人同日销。","遂令昭德蓄威地，一价夜到如摧彫。","明公出镇复考牧，权因望重元非招。","坐知春草长城窟，不见胡儿猎与樵。"]},{"t":"次韵送见素先生巡视江西","f":"七言古诗","c":["鹏路怜公九万遥，名高前后圣人朝。","求衣每答经生谒，退食尝将谏草烧。","古调渐闻流水远，冲襟全逼叠冰消。","巡行暂代璇玑转，斟酌悬看斗柄摇。","雷挟威声多振落，风敷和气不鸣条。","金章持宪诸司肃，玉节临戎四牡调。","百巧先藏机并伏，千邪未触魄应销。","穷人倖免膏腴尽，疲郡何愁户口彫。","乌合剽民传檄定，鸥群遗老待诗招。","日长燕息专城退，铅椠无妨著问樵。"]},{"t":"顾考功母宜人哀词","f":"五言古诗","c":["凉风起天末，游子在万里。","遥遥圭组怀，岂不眷衰齿。","昨梦拜北堂，念子曷归止。","手把白玉玦，感之泪盈眦。","今朝黄耳来，家书相报示。","初日惨不晖，仓惶见天圯。","百年抱长恸，哀怨从兹始。"]},{"t":"雪儿歌","f":"七言古诗","c":["北地佳人首燕赵，秪解慵歌复娇笑。","菱花自许雪儿殊，聪慧天然动轻妙。","十四青丝覆远山，十五城中象雾鬟。","十六妆成看不足，芙蓉初绽碧塘湾。","英年矫矫江南子，词价偏翔洛阳纸。","明珠传意梦方谐，誓尽婵娟护衣被。","细步纤纤宴曲房，细君含笑赠添妆。","亲教乐府诗千韵，貌得宫袍鹭一双。","不堪团扇迎秋早，素馨花发芳魂渺。","罗襦惨淡葳蕤光，香囊零落交州草。","昭阳鬼影立象床，五枝灯燄摇荒凉。","徒令汉史称神武，犹抱西风角枕伤。"]},{"t":"和宫怨二首 其一","f":"七言绝句","c":["凤吹声微别院深，碧桃花下倚沉吟。","鸳鸯浴罢龙池煖，一派轻波带涌金。"]},{"t":"和宫怨二首 其二","f":"七言绝句","c":["怨绿愁红覆井深，监宫休讽白头吟。","阿娇丰貌胡为尔，消得涂椒四壁金。"]},{"t":"和宫人望幸四首 其一","f":"七言绝句","c":["行宫宴罢起更衣，绛烛舒光似晓晖。","侍女一时传辇过，紫檀清道暗香飞。"]},{"t":"和宫人望幸四首 其二","f":"七言绝句","c":["梦逐苍龙绕锁闱，寻思到了是邪非。","午间忽报鸣銮近，百子池头看射飞。"]},{"t":"和宫人望幸四首 其三","f":"七言绝句","c":["望断红云笑语赊，殿头催唤七香车。","圣情不管韶光换，促制新年綵胜花。"]},{"t":"和宫人望幸四首 其四","f":"七言绝句","c":["宫籍排年妾最深，玉箫曾度凤凰吟。","镜中独立青鸾影，不遇传宣不肯临。"]},{"t":"和昭君词二首 其一","f":"七言绝句","c":["下马穷庐拂领巾，伤心无复故宫尘。","可怜却似闲花草，才到开时不是春。"]},{"t":"和昭君词二首 其二","f":"七言绝句","c":["金河南望树森森，挏酒那堪带恨斟。","本是天王最神圣，未应全信画工心。"]},{"t":"晓发横石","f":"七言律诗","c":["江际春寒动北风，扁舟牵浅过芦丛。","剧知远道如天上，顾有长怀在域中。","野练共飞孤屿白，木绵争试小枝红。","眼前笑认韶阳里，岩岫高低日正东。"]},{"t":"元夕清溪泛舟","f":"七言律诗","c":["北风才歇棹歌长，独泛清溪夜渺茫。","数酌自堪当月色，孤舟谁信有韶光。","总谙灯火狂游地，不道儿童戏剧场。","忽忆去年还此夕，枕屏鼙鼓过江乡。"]},{"t":"南华寺","f":"七言律诗","c":["两袖缁尘四十年，曹溪暂尔放春船。","南朝只有松间寺，西祖亲传劫后禅。","乐业畦人租茗圃，随缘老衲饷粳田。","片时闲自浮生得，莫讶无衣与大颠。"]},{"t":"乐昌泷","f":"五言古诗","c":["晨发乐昌道，阴厓簸寒风。","泷流驶击箭，驱石如旋蓬。","轻舟苇叶末，命夺毫芒中。","垂堂昔示戒，岂不镂孤悰。","往读泷吏篇，静怀慨韩踪。","兹行恪新命，所际情匪同。","洒酒韩祠土，圣神迈重瞳。","王尊道云古，讵能息微躬。"]},{"t":"宿郑家驿用壁上韵","f":"五言律诗","c":["炊烟茅店隐，草色驿庭深。","到处惊鸿迹，逢山立马吟。","溪回疑末路，客久见初心。","槠树炎风起，征衣夏欲临。"]},{"t":"七盘坡","f":"五言律诗","c":["寒晓驱荒驿，山盘野气昏。","毳衣孤客雨，枫树几家村。","风日春相惜，烟花他自繁。","劳歌听不得，何处更号猿。"]},{"t":"洞庭春望","f":"七言律诗","c":["眼际流云渺浩平，曜灵吞吐看天行。","楼前吹角晚风急，汉上回槎春水生。","舜野有人培泪竹，刘家何地驻游旌。","一声鸣鹤君山紫，恐有飞仙过岳城。"]},{"t":"桃川宫和淩溪子","f":"七言律诗","c":["红雨迢迢锦汎川，客从何许系渔船。","情深不道云峰浅，业远惟留石磴偏。","只有山林称小隐，幸教文墨托高贤。","乘轺又是桃花节，重为秦人一惘然。"]},{"t":"新店驿和竹溪","f":"七言律诗","c":["滇水南天亦尽头，偶从汗漫续兹游。","马谙驿近蹄方疾，山到春酣翠欲流。","竹叶掌中聊引满，桃花洞口暂淹留。","杜陵镜里韶华在，荣路无劳羡八州。"]},{"t":"界亭咏马","f":"七言律诗","c":["刍原风日稍同群，楸里长嘶陇上闻。","老去霜蹄无一缺，瘦来龙骨尚三分。","銮声不度黄泥坂，鞭影将挥玉塞云。","只道品流非果下，天房谁信是星文。"]},{"t":"马鞍岭雨中和张合溪","f":"七言律诗","c":["盘空还壮楚关赊，罗立诸峰似建牙。","元气荡浮神却寂，悬流奔注势容遮。","望迷去马厓根转，寒薄行幨雨脚斜。","山鸟莫啼泥滑滑，远游人惯动长嗟。"]},{"t":"盈口驿","f":"七言律诗","c":["溪桥往往逐溪斜，茅屋仍分燕子家。","竹净残金犹琐碎，柳寒芳荫未交加。","盘餐雾紫山厨蕨，井税春青石垄茶。","小队轻轺何所事，有怀曾不为芳华。"]},{"t":"清浪馆和竹溪左辖淩溪参伯","f":"七言律诗","c":["孤城归鸟号复集，楼上数星明未华。","岭海形容吾欲老，乾坤怀思子何赊。","迹如司马终为客，句类阴铿亦当家。","幽兴可期还信否，虚舟将泛海东涯。"]},{"t":"望岳和杜","f":"五言古诗","c":["五岳在天下，雄据如侯王。","衡山剧盘薄，朱鸟维南方。","灏气浮九疑，帝子留天香。","阴阳割楚粤，静阅曾兴亡。","林隙窥洞庭，控扼连三湘。","旭日转东趾，轸灵栖其旁。","予宿尚幽览，过之情激昂。","微疴犯尘骨，潸然引长望。","初疑万马下，忽若群龙翔。","晴岚捲高嶂，绝壑迷春霜。","祝融青冥外，近接桐木冈。","将寻科斗石，因葺茅茨堂。","侃侃昌黎子，直疏遗世皇。","环珓误一掷，吾道无禨祥。"]},{"t":"清平馆和竹溪二首 其一","f":"五言律诗","c":["里舍荒邮谬，晨驱每及晡。","掷金饶馆地，炊玉少行厨。","蛮语难相解，禽名或自呼。","缥囊芳思减，无句答奚奴。"]},{"t":"清平馆和竹溪二首 其二","f":"五言律诗","c":["上岭复下岭，重霾昼似晡。","衰颜依药裹，何意混天厨。","鹿豕终堪交，枭卢不解呼。","西洲风日好，残梦绕青奴。"]},{"t":"将至贵阳喜竹溪再会凭轼有赋","f":"七言律诗","c":["漓江为别贵阳逢，将遇还同未别悰。","书剑偶来方远驾，宫墙曾许扣洪钟。","共知世仰昌黎斗，安得云从东野龙。","肯为穷荒阻幽逸，碧山诗思更重重。"]},{"t":"?獠","f":"七言律诗","c":["刀镰到处只随身，夫妇同耕上垄春。","宁野岂非缘习俗，痴愚应未丧真淳。","鸡翰插鬓山经略，鸟道为家木客亲。","干羽两阶曾不见，吾皇神圣古无伦。"]},{"t":"关索岭","f":"七言律诗","c":["真疑陆海驾涛来，宿瘴全经冷节开。","石径春光馀委曲，灌林人语隔崔嵬。","西临僰道孤鸢过，东向查城万马回。","心折杜陵应此际，乾坤何处更登台。"]},{"t":"白水道中书事","f":"七言律诗","c":["野店鸣鸡促曙光，练衣淩乱敝春霜。","泉声瘴后回龙井，夷聚山晴趁马场。","戍垒人稀军吏逸，驿庭花淡鹜妖藏。","独怜归燕无机事，两两低飞掠艳阳。"]},{"t":"盘江","f":"七言律诗","c":["盘江春水绿如苔，欲渡先擎辟瘴杯。","花界已无渔父到，名场惟有宦人来。","蛟龙日射寒湫隐，燕雀风融綵帜开。","我亦下车歌鼓枻，野航曾是济川才。"]},{"t":"普安馆月中闻琴","f":"七言律诗","c":["春台寂寂坐昏黄，谁拂龙唇对夜光。","一壑松风惊改调，百年冰炭减回肠。","遥峰自隔孤鸿影，小閤时飘睡鸭香。","长使闻琴兼玩月，定知何处是边乡。"]},{"t":"促程","f":"五言古诗","c":["晨渡晃州月，暮宿清浪馆。","迢递岂不劳，王程讵能缓。","学道三十年，小技惭搦管。","忝窃藩一方，微躬百忧满。","惟饥常梦餐，孰寒不念煖。","矧兹饱煖情，如系屈伸腕。","牧事贵不扰，此理良可忖。","勿以小何伤，剪爪惧肤损。","先民此明训，行哉善用短。"]},{"t":"兴隆馆独夜闻钟","f":"五言律诗","c":["灯影照岑寂，疏钟带雨闻。","关河双短鬓，今古几浮云。","久客看蝉翼，寒山护豹文。","芳华随处换，梅柳越春分。"]},{"t":"入宣威关","f":"古风","c":["猿声犹是贵山闻，约略莺花管割分。","旧垒已荒馀细柳，微?晴后尚流云。","扬旌稍领蛮夷长，学道真惭父母君。","谩儗当时康济事，一篇初就省方文。"]},{"t":"行次曲阳遇高吾左辖之官山东赋赠","f":"七言律诗","c":["偶同雄甲惭差长，榜附贤良分更深。","万里相逢还逆旅，十年为别各惊心。","东藩海岳声何迈，南彻风烟鬓易侵。","客里不堪惟送远，却看旗鼓隔青岑。"]},{"t":"憩易龙喜雨","f":"七言律诗","c":["马首先收四野尘，千峰浓润上嶙峋。","乍听声在庭前树，不觉欢腾陌上人。","滇海亭台应有记，雷塘山水定无神。","从来风雨缘时令，谁道阴晴总未真。"]},{"t":"杨林书感","f":"七言律诗","c":["杨林山色使车前，尽日西风吹午天。","水浅石湖闲斗鸭，春残桑柘转闻鹃。","碧鸡谩走催程马，黄木真抛弄月船。","神化不教违宿尚，秾芳无限远游篇。"]},{"t":"送陶少参入贺","f":"七言律诗","c":["黔中四月犹佳丽，满路莺花傍马鞭。","睿圣可歌惟万寿，升平同际自元年。","老成久副三曹望，缱绻能消几树烟。","唐镜耿光谁继事，孤臣心切紫云边。"]},{"t":"送王宪副入贺","f":"七言律诗","c":["广陌晴高不动尘，邮旗东郭引征轮。","两行秦树风声在，万里滇山物色新。","禹玉殿头承涣泽，尧樽天上献长春。","江花欲语江乡近，深坐无妨敬里人。"]},{"t":"送方鉴湖入觐","f":"七言律诗","c":["天际千峰紫映楼，渐鸿逵上思悠悠。","文章旧驾中书省，琴剑遥登上计舟。","杨叶暗分岐路晓，薇花光泛邃堂秋。","孤怀不寐看晴野，认得三台过蓟州。"]},{"t":"送陈宪副入觐","f":"五言律诗","c":["晴鹊迎初日，旌斿照野雄。","宦情滇海曲，乡思浙江东。","上计宜新化，升明仰至公。","悬知骑马路，强半五云中。"]},{"t":"再别鉴湖","f":"五言古诗","c":["金风吹远扬，拂此北游驾。","帝阍十二重，初日照华夏。","忧时亦乞言，披章达清夜。","君抱瑞世图，素望寰宇大。","朝正固常典，所际在更化。","保釐旧业尊，一食仍尽下。","台端岂迂途，论课谅非亚。","曷慰励精怀，宣室有燕暇。","小邮双赤旗，江山俨罨画。","不信别时苦，悲鸣恋群马。"]},{"t":"寿刘九峰封君","f":"七言古诗","c":["九峰山翁常在山，一岁不一窥尘寰。","卯金苗裔旧隆准，著书满屋麾迁班。","行雁联翩刺霄汉，翁乎隐几烟霞关。","教儿肯落无双后，济物仍施不报间。","修龄馀六已望七，晨星两眼仙童颜。","掌中丹诰凤交彩，胸盘绣雀披云鹇。","焚香直北三顿首，万年睿圣貤高闲。","九峰巍哉几千尺，南山东瞩摇青鬟。","便引南山作宾主，安得从之渝水湾。"]},{"t":"戏题便面二首 其一","f":"五言绝句","c":["野渡去还泊，山姿树色同。","老予看不足，只道是闽中。"]},{"t":"戏题便面二首 其二","f":"五言绝句","c":["云水深且广，云山高复然。","孤舟村店外，好似弄潮天。"]},{"t":"登明远楼和罗侍御","f":"七言律诗","c":["超代文章还绝域，百年唫鬓此高楼。","席移云影澹秋色，帘卷池光净客愁。","偶对遥岑闻鸟语，即看灵囿报麟游。","江湖漫有平生思，极日风帆何处舟。"]},{"t":"鹿鸣倡和二首 其一","f":"七言律诗","c":["清时词赋总悬科，五色真看剪胜罗。","才是西周升里选，道从南纪戢民讹。","歌回俎上韶薰远，秋满人间桂月多。","笑认当年鲲化处，海风吹浪拍天河。"]},{"t":"鹿鸣倡和二首 其二","f":"七言律诗","c":["谩以荣途羡特科，圣朝贤俊各蒐罗。","文章嘉祐今还变，名价司空旧不讹。","苍棘盘云秋夜杳，皓珠呈月霁烟多。","登明况是澄清手，吾道端凭挽注河。"]},{"t":"次卷中韵赠张愈光","f":"七言律诗","c":["綵服新辞绿野堂，浓烟晴树共苍苍。","三苏意气空西蜀，二陆风流满洛阳。","关岭云横骑马客，曲江春竞探花郎。","从前文赋如君少，漫得都门纸价翔。"]},{"t":"周佥司母寿八十","f":"七言律诗","c":["大家贤范女中师，为爱恩华照寿眉。","灯火承欢宜令妇，风云腾跃问佳儿。","日回南沚蘋花丽，喜入东堂燕子知。","欲报春晖岂无处，儗翻震泽作瑶池。"]},{"t":"题风木卷","f":"七言律诗","c":["芳华长奉板舆同，宛宛音容尚眼中。","义范不违闻礼训，令仪真有听鸡风。","漆灯夜闭玄堂寂，餗鼎时思燕寝丰。","世上郎君仍将印，羽林誇是丈夫雄。"]},{"t":"双寿为叶主政赋","f":"七言律诗","c":["春满扶桑花满楼，神仙家在甬东头。","如宾相对两鹤发，济世曾烦几麦舟。","锦轴联函天语近，綵衣当席日光浮。","不妨山水陪强健，岁岁长酣泛菊秋。"]},{"t":"奉和见素翁早朝志喜","f":"七言律诗","c":["瑞色从龙晓渐升，朝衣秋老气棱棱。","殊方有诏蠲珍献，远疏无劳论市灯。","天地此时逢既泰，冈陵如寿祝还增。","忽听棘下琼琚咏，万里孤怀谩欲腾。"]},{"t":"南坦至京见怀次韵奉答","f":"七言律诗","c":["古梅清瘦作花迟，背立闲堂咏竹枝。","绝域关河黄耳隔，旧园风露白鹇知。","几从妙月追谈韵，敢向横参儗见期。","爱士不妨如考牧，满郊云锦画中诗。"]},{"t":"采葛谣辰阳道中作","f":"古风","c":["采葛荒山中，泥深葛根短。","茅茨四子母，我腹讵得满。","罢丞摄令印，窥我肉可脔。","似闻府公慈，欲诉宁尽款。","采葛采葛春不雨，去年不雨食葛苦。","食葛苦，命敢辞，只怕丞来葛了时。"]},{"t":"书故庆符令周君遗事","f":"七言绝句","c":["归来伴鹤一琴存，道是元公几叶孙。","千载断碑无泪洒，庆符人解颂遗恩。"]},{"t":"遇仙桥和南坦淩溪","f":"七言绝句","c":["溟溟春雾午山迷，野雉低飞柳浪西。","尘网密时仙亦远，石桥疑杀武陵溪。"]},{"t":"书韩守清梁园年会图","f":"七言绝句","c":["春花傍马尽荣途，湖海尘踪我亦孤。","二十七年怀旧梦，辰阳初见汴州图。"]},{"t":"吊青林","f":"五言古诗","c":["嘉山有荣木，良帑多重宝。","如何青林子，不向人间老。","遗编落我手，天骥骋驰道。","幽玄庄列班，高雅闽洛到。","方驾古词英，居实乃舆皂。","芙蓉一夜风，却让苍艾好。","忌名造化差，颜卜亦枯槁。","吾闻达士灵，千年茹瑶草。","将依雁宕云，下视蓬莱岛。"]},{"t":"再游太华寺","f":"五言律诗","c":["风日太华好，重来是隔年。","池光浮六诏，树色接诸天。","翠霭莺花路，黄云燕麦田。","老怀非暇豫，农事正春先。"]},{"t":"赠壶山","f":"七言古诗","c":["迢迢陆海多才贤，大夫茂绩垂南滇。","手中黄纸丽圣藻，玉龙三尺开夷天。","贵山蛮落数十种，家家盗劫如春田。","椎牛击鼓夜祭鬼，誓死不犯都匀边。","大夫风力有如许，贵竹之人至今语。"]},{"t":"壬午岁除前二日同诸藩长登圆通寺閤和青厓","f":"七言律诗","c":["笑拂高冠赋远游，梅花岁晚共蠲忧。","吏情偶问青莲社，客梦时横白鹭洲。","凿海更谁纡汉策，登楼何作后荆州。","春光如锦明朝路，握手寒晖暂尔留。"]},{"t":"春日宴黔国山亭","f":"七言律诗","c":["令转青阳气已浓，上公台榭许从容。","花光熳射银塘丽，霞彩回联石巘重。","兴掩歌钟誇算马，笑分篇什记登龙。","执规谁更司春事，好借晴和遍四封。"]},{"t":"金马关别青厓","f":"七言律诗","c":["晴和风日正酣春，柳色那堪送远频。","道古不辞青眼别，路岐谁遣白头新。","昨宵良晤曾占梦，同省高怀类饮醇。","旧里莫寻鱼鸟约，升平难负致君身。"]},{"t":"送陈少参入贺","f":"七言律诗","c":["斋中高榻曾谁下，郭外征辕许暂攀。","嵩岳天声欢北极，戎州家庆对南山。","笑看行李清风际，苦忆心期皎月间。","春事正深诗转丽，邮筒能为度孱颜。"]},{"t":"送邵佥司","f":"七言绝句","c":["短亭行色一囊琴，传食仍挥卖马金。","芳思便应轻万里，梅花满路打乖吟。"]},{"t":"蝴蝶花","f":"七言绝句","c":["寒露盈盈满道傍，只看浮艳更无香。","情知不带飞扬性，谩逐东风上下狂。"]},{"t":"次韵山亭论别二首 其一","f":"七言绝句","c":["引满休辞金屈卮，漫漫天路马鸣时。","千崖万壑随车雨，涓滴犹堪系去思。"]},{"t":"次韵山亭论别二首 其二","f":"七言绝句","c":["几日高堂捧寿卮，野花绣地小春时。","关山月白豺狼遁，只有巡功副睿思。"]},{"t":"早衙即事次韵","f":"七言律诗","c":["薇花三对诏南秋，江閤归心付四休。","明世也知能用短，至人曾道欲行柔。","青藜旧杖孤窗雨，黄木澄湾独橹舟。","眼底拥旌何所事，且看晴鹊屋山头。"]},{"t":"赠王教授归隐","f":"七言律诗","c":["莫寻幽草赋无媒，曾播苏湖化雨来。","尘外簪裾还逸客，眼前罗网有遗才。","苍茫秋色孤舟发，婉转春光一径开。","老我欲从渝水曲，柳花何处读书台。"]},{"t":"送萧兵宪还万安","f":"七言律诗","c":["铁肝旧建台中议，豸角还清诏外疆。","湖海宦情惟晚节，河桥行色有新霜。","轻纶弄艇凫鸥狎，浊酒持螯橘柚香。","高隐从前多古思，五云东下见柴桑。"]},{"t":"次韵送张愈光落第还永昌","f":"七言律诗","c":["南山衣屦晓寒新，归燕词华早动人。","共道金台须骏骨，未应盐坂有龙身。","两回那许花凝泪，九炼曾闻药奏神。","先达如今尽知己，肯教韩愈献书频。"]},{"t":"送李白夫赴南户部","f":"七言律诗","c":["曾于湘水泛秋澄，为爱风流识李膺。","云际棠阴披剑阁，雨馀山色见钟陵。","宦情南国今如许，清论东曹素可凭。","最是仙缘消不尽，春明天阙兴堪乘。"]},{"t":"九日城北寺登高","f":"七言律诗","c":["遐荒九日多幽悰，禅台隐隐临高墉。","徘徊暂抚莓苔石，突屼已见芙蓉峰。","兴孤南菊客不饮，心满西庄天未从。","曲栏矫首动馀感，归鸟尽背黄昏钟。"]},{"t":"南中忆弟","f":"七言律诗","c":["三载相违一见难，止凭归仆话平安。","西林近日如何遣，南国浮云不耐看。","抛印未能怜野客，买船谁与赴春官。","早衰我自寻常在，虾菜无烦念几餐。"]},{"t":"送关给舍赴召","f":"七言律诗","c":["滇池三月瘴烟轻，手上归环万里情。","与世不妨文作业，复官仍得谏为名。","南烹韩愈初宜味，西赋安仁旧纪行。","前席倘询幽远俗，一篇王会几时成。"]},{"t":"寄贺永斋卜居","f":"七言律诗","c":["芳草街东数十椽，永斋新构小壶天。","竹间剥琢开枰日，檐外絪缊试茗烟。","候火稍闻珠似黍，制荷应见藕如船。","少师绿野长邻近，二疏徒誇汉史前。"]},{"t":"悠然亭","f":"五言古诗","c":["秋花色云佳，金吾足芳苑。","南山突然来，此兴予不浅。","渊明千古豪，固节官可免。","如何青林下，见者一己鲜。","低首临兹亭，敢谓高道远。"]},{"t":"陈邓二藩长见投谩尔和答","f":"五言古诗","c":["君子不耻独，恒情多尚同。","忽忽百年内，强半埃尘中。","鄙儒伏海曲，谈笑谐群公。","如弦把遗直，要日明愚忠。","久闻蒉桴响，众乐忽已终。","所爱社栎枝，不谢追琢攻。","皓齿渐云豁，苍颐凋故红。","此志向未渝，此乐浑融融。","愈老识愈晦，虚心承貌恭。","低颜就绳检，何以程勤功。","同列两夫子，肮脏称长雄。","才方截玉剑，又似吞涧虹。","款款引固陋，将忘公望崇。","仰叹不能即，有如失侣鸿。","赵张协济业，千载随蒿蓬。","斯道讵能昧，钦矣皤皤翁。"]},{"t":"东嵎文学惠围棋口号当谢","f":"七言绝句","c":["浓青润白列星文，谢向康成小阁分。","尽以斜飞看局面，不知闲着可张军。"]},{"t":"次韵答东嵎云巢二宪伯七首 其一","f":"七言绝句","c":["森罗只道是天文，幽意曾于奕旨分。","老我静来寻谱帖，几行淩乱散鸦军。"]},{"t":"次韵答东嵎云巢二宪伯七首 其二","f":"七言绝句","c":["月上衙回岸惠文，灯花闲落夜将分。","王郎野性休翻覆，末着真同背水军。"]},{"t":"次韵答东嵎云巢二宪伯七首 其三","f":"七言绝句","c":["翠烟横竹坐休文，带孔频移减臂分。","有客肯来开玉局，傍谈犹足当参军。"]},{"t":"次韵答东嵎云巢二宪伯七首 其四","f":"七言绝句","c":["原奕皮生也著文，谁家朱墨谩支分。","方来温玉还珍重，逸气寻常走魏军。"]},{"t":"次韵答东嵎云巢二宪伯七首 其五","f":"七言绝句","c":["狂爱童儿画纸文，离离关眼暗相分。","双奁若许当长日，合筑棋坛拜冠军。"]},{"t":"次韵答东嵎云巢二宪伯七首 其六","f":"七言绝句","c":["山人初试御前文，夺角冲关小队分。","可是边烽无事日，谩将楸局儗行军。"]},{"t":"次韵答东嵎云巢二宪伯七首 其七","f":"七言绝句","c":["莫以论棋比较文，人间豪素敢铢分。","若为不解欣然意，请看河湟奏凯军。"]},{"t":"闻报有述","f":"七言律诗","c":["由来那解务崇深，万里谁传阙下音。","岂有涓埃裨海岳，止应泉石怨商参。","关山处处豺狼窟，蓬蔀家家燕雀林。","经略总看双鬓在，拥旄宁是老予心。"]},{"t":"抚台谢恩书感","f":"七言律诗","c":["万马喧喧踏晓霜，群星随月送恩光。","书生遭际真多幸，圣主抡收亦片长。","执法旧雄专席选，提封应尽百蛮乡。","从前细检名贤迹，匡济无如六事章。"]},{"t":"南中初雪","f":"七言律诗","c":["窗影珍珑乱晓灯，北风初劲正飞腾。","愁还远戍无衣赋，喜为殊方有岁徵。","澹彩欲晴犹点缀，寒威渐老更严凝。","东亭依约梅花发，何必山阴兴可乘。"]},{"t":"院后牡丹和江侍御","f":"七言律诗","c":["旋为秾华小筑台，东皇与谢北山莱。","芳阴转日还当席，幽味迎薰稍近杯。","世上品流元有谱，眼前根裔岂知才。","总教难敌阳春咏，文藻翩翩柱史裁。"]},{"t":"和南园少司徒","f":"七言律诗","c":["几见文章多逸气，欲从赤帜委降心。","季鹰在日情偏放，若水还家岁未侵。","月下酒杯长吊古，花边衣屦稍宜今。","永昌山色南中别，谁为沧浪想嗣音。"]},{"t":"移镇","f":"七言律诗","c":["遐方裘带照双蓬，已窃华途累至公。","三楚去天还近远，孤臣惟命亦西东。","时名若个登楼后，地望偏多赐履中。","虚浅岂能承沛渥，眼前江汉寸心同。"]},{"t":"院后紫薇四月即花","f":"七言律诗","c":["堂后薇花一两丛，晓来迎旭见新红。","调和岂足三春雨，绰约先誇四月风。","喜气谩传清似水，衰颜谁信过于翁。","枝头树底空相惜，送我扬旌几片东。"]},{"t":"病起言怀","f":"七言律诗","c":["夏气南中寒复暄，客心无计控归猿。","扁舟欲买鲈鱼港，孤月正照梅花村。","放鹤未期过下里，对人先拟号东园。","著书卖卜终多事，何限悠悠可具言。"]},{"t":"六月之夕梦素翁过予郭西之居觉识以诗","f":"七言律诗","c":["炯炯精神照郭西，海天风露满花溪。","壶山灵异英贤出，世路承平逸老归。","谩忆星辰通剑履，却看山月晃荷衣。","玄机不道无人解，便拟从公赋式微。"]},{"t":"江风山月閤和双溪宪长淩溪参伯","f":"五言律诗","c":["久客足尘鞅，宜闻郭外期。","野航纷进楫，江路巧环规。","幽鸟融春语，长松换劫枝。","偶然清赏惬，不道但心知。"]},{"t":"苦雨","f":"五言律诗","c":["霖雨秋方积，我行殊未休。","缁衣明客况，黄潦带边愁。","鸡骨占难定，龙街市欲收。","化工翻覆手，何处可销忧。"]},{"t":"马龙馆夜坐","f":"五言律诗","c":["吏休重院静，万马宿孤城。","树古风声远，山高夜气清。","修程看月晕，久坐继松明。","乡思悠悠地，当关报转更。"]},{"t":"病足初愈散步小院命洗竹五首 其一","f":"五言绝句","c":["稍过花砖界，愁侵妙月痕。","呼僮将我斧，吾意在除繁。"]},{"t":"病足初愈散步小院命洗竹五首 其二","f":"五言绝句","c":["应手孤烟落，芳榴露数花。","小池他夜雨，幸减一枝斜。"]},{"t":"病足初愈散步小院命洗竹五首 其三","f":"五言绝句","c":["虚劲钦孤操，狂丛浪自多。","讵忧风露损，方寸有萦萝。"]},{"t":"病足初愈散步小院命洗竹五首 其四","f":"五言绝句","c":["老爱风霜饱，将裁紫玉轻。","江南秋色远，龙笛有新声。"]},{"t":"病足初愈散步小院命洗竹五首 其五","f":"五言绝句","c":["绿谩芭蕉薄，红嫌月桂新。","龙材不自惜，何物况孤臣。"]},{"t":"柏台秋月图","f":"七言绝句","c":["秋满千山璧月光，柏台清比玉壶强。","南乡莫谩看灵彩，行奉重轮照万方。"]},{"t":"发金马关","f":"七言律诗","c":["七月边风促晓寒，河桥新霁快征鞍。","满堤柳色溪蛮语，何处棠阴野老看。","总谓开诚能化俗，可堪持节更之官。","山邮供张将箫鼓，为谢南中业已安。"]},{"t":"出宣威关","f":"七言律诗","c":["秋声先报出关期，小驻荒亭看旧诗。","只有鬓毛非往日，不妨行李似来时。","山攒下上群蛮宅，路析东西独客悲。","茅屋一间诸葛庙，千年禁戒未曾衰。"]},{"t":"软桥坡","f":"七言律诗","c":["万曲千盘始渡河，仆人云是软桥坡。","芬林百卉浓将瘴，饮涧双猱狎且歌。","听雨却思孤馆静，看山真幸此生多。","天边亦有王阳道，雾栈云梯奈若何。"]},{"t":"鸦关","f":"七言律诗","c":["峻极青冥鸟迹疏，征舆动处碧云扶。","敢言老大孤怀减，曾记英雄百战馀。","永叔庐山堪小赋，谪仙蜀道谩长吁。","千年圣化浑无外，傍崄何劳仗一夫。"]},{"t":"安普道读淩溪子述咎十绝句","f":"五言古诗","c":["至宝无横弃，泥涂有良规。","泥涂不可即，至宝忽在兹。","别子逾十稔，万里见子词。","皎皎照我室，微子谁复为。","念子不能见，涕泪双涟洏。","关山多鬼蜮，子行仲春时。","下岂有坎坷，上岂有崄巇。","卉木已蔚荟，子岂履其危。","长风羽翎健，朝举夕九维。","久闻息淮海，何以谢暌离。","愿言崇令德，岁晏以为期。"]},{"t":"山雾","f":"五言律诗","c":["广野晨方合，征帷午尚垂。","千峰愁隐障，万亩快潜滋。","歊紫占应叶，蒸黄道或衰。","劳歌增太息，不是瘴乡宜。"]},{"t":"观稼","f":"五言律诗","c":["七月贵阳道，畇畇我稼宜。","脉潜华始秀，气早穗先垂。","灭裂行堪戒，污邪旧有辞。","理人如种树，何处访农师。"]},{"t":"普安馆夜喜雨","f":"五言律诗","c":["秋襟荡烦热，夜足普城雨。","溪黄沛新流，石翠净回乳。","苗田稗子垂，鹊垒鸠妇处。","平明有长途，卧听号笛举。"]},{"t":"龙里馆牡丹未开戏咏","f":"七言绝句","c":["芳苞戢戢日迟迟，绝徼谁移富贵姿。","倚遍曲栏心自语，看花须看未开时。"]},{"t":"关索庙","f":"七言绝句","c":["南征猿鹤草青青，满眼陵丘识所经。","偶向庙巫询往事，不知时代语英灵。"]},{"t":"题东田竹冈先陇","f":"七言绝句","c":["十里风烟岁欲侵，万家城邑昼阴阴。","青鸟卜世宁非验，闻道龙材已满林。"]},{"t":"戏题葵丹向日卷","f":"七言绝句","c":["芳根只托冠军家，不信还同草木华。","最是一枝红似血，有人曾见日中花。"]},{"t":"山翁四首 其一","f":"七言绝句","c":["采药归来月满溪，家儿能唱白铜鞮。","山翁有乐无人道，木槿明朝花又齐。"]},{"t":"山翁四首 其二","f":"七言绝句","c":["白发萧萧覆领头，瓦瓶无酒几曾愁。","人间一醉寻常醒，懒学先生向妇谋。"]},{"t":"山翁四首 其三","f":"七言绝句","c":["山上常珍紫蕨生，山中幽意白云行。","等閒孺子休相聒，无那桥边去住情。"]},{"t":"山翁四首 其四","f":"七言绝句","c":["镇日閒谈遂古初，郡中来问养生书。","紫芝亦是商山草，此曲高歌我不如。"]},{"t":"山雨","f":"七言绝句","c":["黑云肤寸眼前生，万壑松涛送雨声。","蛮语数年刚一见，山中恐是有龙行。"]},{"t":"山家","f":"七言绝句","c":["袅袅孤烟出远林，更无人语昼阴阴。","数声缥缈闻难定，莫是仙庞吠白云。"]},{"t":"赠胡方伯","f":"五言古诗","c":["鸿渐徵仪羽，龙飞纪甲辰。","西曹抡法笔，东市少冤民。","彭蠡冲襟静，匡庐爽气新。","王风馀制作，卿月近精神。","素业康侯裕，丛祠叔子伦。","梅花迎按节，棠树怅移春。","冬日诚堪负，冰壶讵可亲。","八闽分控带，左辖盛弥纶。","只儗开延阁，何须问要津。","独惭王述老，奔走属车尘。"]},{"t":"奉送蒲川龚先生赴湖南左辖和姚维宁","f":"五言古诗","c":["履素频居顺，登良遂陟明。","直方堪地负，廉约即天成。","气老元操简，怀虚更敛英。","魏公真相器，君实足时名。","京邑因河润，春皋谢木荣。","人间冬日色，蛮裔古风声。","乡井连吴会，山川控邓城。","化行时伪戢，吏散道心清。","白板馀生聚，红箱减算征。","崇阶将义报，殊礼以贤旌。","信节年于迈，勤功夜自程。","国香迷畹亩，阳鸟渡湘衡。","璧彩归仍丽，金声扣始铮。","寓言齐物理，降色察民情。","剖剧并刀发，摅贞汉水倾。","总无私可恤，岂有宠能惊。","鉴彻天潢派，词森武库兵。","栖迟彭泽令，经济洛阳生。","菱角新池实，莼丝晚社羹。","四时如有序，桂棹五湖轻。"]},{"t":"鸠巢醝台乳白雏二驯扰可玩作瑞鸠歌","f":"七言古诗","c":["闽中醝台昼如水，台畔荔丛光薿薿。","七子巢昏雨脚斜，两片天山雪花起。","耿耿西沦太白精，寒林弄日试春鸣。","素鸾且莫妒颜色，舂锄琐细鱼梁横。","江南书客弁伊骐，晨风吹鬓数茎丝。","临淮孝子鹄头诏，勿逐金钩变化为。"]},{"t":"蒲川歌","f":"七言古诗","c":["谁截银河一派秋，方诸灏气抱云流。","粼粼臞石压空碧，蒲芽十丈骞龙虬。","世人那解窥幽秘，但看珠露凝深翠。","乾坤澒洞割根荄，日月精华养神异。","新裔夭夭淮水光，香须寒荚饱灵芳。","泰山谷口百万户，寸匕入骨捐痍伤。","川上悠悠十二年，一年一节青铜坚。","天交鬼物递呵护，金光之草羞廉纤。","生色盈盈照紫薇，我今亲见开花时。","症瘕九土向流涕，愿乞刀圭付尔为。"]},{"t":"限韵送姚使君守琼管二首 其一","f":"七言律诗","c":["十月南天尚未寒，木兰潮满渐移滩。","遐心注水将鞭赠，逸气横江借剑看。","夜閤承颜惊客久，炎州改命答才难。","我家近在黄湾口，只验鲸波记底安。"]},{"t":"限韵送姚使君守琼管二首 其二","f":"七言律诗","c":["赤马嘤嘤美使君，才声好似华州闻。","花封几路迎山节，卉服千家住水云。","位逐晓星还旧次，势如晴准□前群。","遐方不作多时别，延閤于今本右文。"]},{"t":"南中乡饮和周莱轩宪长","f":"七言律诗","c":["关河神禹旧南州，王度真成向野求。","天地位分方左海，衣冠道在欲东周。","宾阶古意寻常见，儒化全功取次收。","不道越巂江上水，却从清泗溯源流。"]},{"t":"竹田歌","f":"七言古诗","c":["西溪宛转南山绿，山下溪边相君屋。","曾无卉木动韶芳，万竹森森迸寒玉。","攒根只认梁州铁，亭亭青紫乔林叶。","晓旭徒怜琐碎金，凝霜敢犯贞修节。","此地何年足风雨，陆海波涛遽如许。","才出池园发异声，苍虬蜿蜿孙将子。","苏老菟裘兴复长，洞庭帝子遗文章。","直从气味辩甘苦，宁知性体齐圆方。","漫儗侯封渭曲资，七贤称达亦风卑。","主人头白杀青在，谩倚秋天唱竹枝。"]},{"t":"鼓山限韵一首","f":"七言律诗","c":["立马长松傍午原，仍看青霭逗云根。","钟声细认林端梵，草色平连石上樽。","泉迸灵源萦古涧，茗酣春味破新园。","兹游况是初晴后，徙倚天风瞰海门。"]},{"t":"环溪钓处为陈侍御赋","f":"五言古诗","c":["只道腊溪派，安知霄汉通。","巽功居习坎，理脉法包蒙。","汇似山阴曲，磻如渭上潨。","循流方宛转，入海即浺瀜。","荫树窥天镜，垂纶挹道风。","矶因冈腹便，台借石唇隆。","始泛溪翁棹，期回地主骢。","鱼凫疑物色，荷柳艳遭逢。","恩到波光动，名荣里望崇。","向来孤往兴，犹自水西东。"]},{"t":"送京尹胡竹亭","f":"七言古诗","c":["烟霄浩渺见堂堂，三十年前遂显扬。","清白自多胡质业，风流先化子陵乡。","骥辞粤徼看前步，雁度衡峰厌后行。","草木润辉天子召，琴书轻捷舍人装。","山河历历包幽蓟，器略沉沉掩赵张。","三辅权兼藩臬重，百城命在股肱良。","狐封弹压收雄狡，驴背敲推恕小狂。","化理由来逢日泰，沙堤此去切云长。","疏筵倚柳春犹浅，禁藉闻鸡夜未央。","欲借晴潮三月信，好将兰楫过鄱阳。"]},{"t":"与相者","f":"七言绝句","c":["两眼晨星阅世来，自言曾见济时才。","老予一片山林骨，四百峰头绿萼开。"]},{"t":"毖斋为查佥司赋","f":"五言古诗","c":["憩迹荫佳树，照影清泠渊。","岂必媚影迹，慎履德乃□。","幽晨辟斋牖，梧竹净娟娟。","结构能几许，睿词日中天。","端居奉明义，于焉荷生全。","礼节固烦密，敬则如持筌。","四诗正而丽，无邪贯其篇。","吾生谅荏苒，何由等□坚。","所思在茫渺，虎骛云与泉。","黄斋昔称勉，颜氏心终传。","君子问毖理，强歌备韦弦。"]},{"t":"清虚亭","f":"五言律诗","c":["结构切红云，闽山未觉深。","中天分气色，下界割晴阴。","看竹溪流影，鸣琴谷借音。","崇高方有地，犹自爱乔林。"]},{"t":"控海楼","f":"五言律诗","c":["飞宇冠崔嵬，东南罨画开。","鹤程冲雾上，鳌背带风回。","野港分航渡，晴峰卷幔来。","百蛮趋剑履，稽首赞雄才。"]},{"t":"锡山张元之初为闽运长缘簿书诖误近一到闽予方有剑川之役元之晨命僮奴手缄云以四果饷发之乃荔枝杨梅枇杷樱桃歌也戏和答之荔枝","f":"七言律诗","c":["灵根只种神仙国，误落飞邮溷灵液。","南山紫雾澹方晴，百匝高阴觑新色。","铁桥道人一亩宫，珊瑚十丈鸡冠红。","鹾台小树味亦浅，可惜不比南山中。"]},{"t":"杨梅","f":"七言律诗","c":["弁山白种传山僧，初摘繁枝如轑羹。","可怜贡匦漏苞录，纂纂玉粒惊寒晴。","品光却厌辰砂赤，香橘霜橙总凡液。","江南此实君可尝，问君无乃江南客。"]},{"t":"枇杷","f":"七言律诗","c":["宫园夏熟冬花果，叶间照眼繁星朵。","风雨西来秦树愁，蕡实离离向南堕。","碎黄蒸日压纤柯，游人斗骋金丸多。","茂陵赋骨草色冷，露重烟稀若尔何。"]},{"t":"樱桃","f":"七言律诗","c":["麻衣校理寓紫极，芳兰族迸朱樱赤。","酣晓微禽噤不鸣，离宫四月传新食。","璎珞攒柯最屈盘，中书门下暂相看。","饕颐朵向醍醐侧，妒杀银笼透转丸。"]},{"t":"白石舟中震雨二首 其一","f":"七言绝句","c":["白雨满天鸣布谷，西山电射东山腹。","予正孤舟掠渺茫，前村忽见牛呼犊。"]},{"t":"白石舟中震雨二首 其二","f":"七言绝句","c":["西方虩虩惊百里，火龙决眦划波起。","石妖木魅损威神，老蚿只在人间市。"]},{"t":"送丁近斋赴阙","f":"七言古诗","c":["先生逸迹遍南服，先生逸气横梧竹。","来处春衫翔鸾高，去日鹇花照围玉。","一家儒术百家宗，洪音纤响悬如钟。","平生梦寐讵可即，石鼓冈前恰再逢。","盘薄冲襟百粤山，方壶古水临清颜。","秀词巨轴石鼎后，钟王笔势参差间。","檄书缗算下诸州，谁言司计非雄猷。","饩戎丰缩关数运，轺旌载许东南忧。","王事程期五月尾，潮风尚驾龙舟水。","荔子疏筵玛瑙光，莺声未尽骊歌起。","□□□起天一方，武夷控引栖霞苍。","君行无乃晋陵道，北望风蒲何渺茫。"]},{"t":"送白斋归隐","f":"七言古诗","c":["隐君卜隐何山深，四明刺天青竹林。","尊边纵客问同异，世上无人争古今。","日高未栉先开径，桃郎惯识平生性。","入手莼丝紫雾轻，不须更把长镵柄。","白首知君愿不违，苧衣如雪天风吹。","镜湖一曲太有限，柔纶千丈东溟垂。","闭关长在衡门里，休观邸报通朝市。","黄石毋要圯下桥，赤松尔待云端寺。","进衔才带紫薇台，花欲飘零烂熳开。","腰章不称笋皮笠，误领当时一鹤来。","陶令孤高五株柳，送君不及空挥手。","十月樵风未可期，予舟欲向扶胥口。"]},{"t":"二南静处为郑白湖赋","f":"七言古诗","c":["酣春南郭如瀼西，归凤早构临霞栖。","流云岂解去时意，长桥谩忆当年题。","方池曲槛果何以，柴桑有鬼应知此。","放马朝穿白鹭群，箨龙个个呼君子。","甘鞠丛萦古樾深，眼看昨日遽乔林。","璇玑不得宰寒暑，羲和六辔纡升沉。","瘦猿老作山中客，却守南山岁星易。","踏上肩舆趁市声，回心愧杀孤烟碧。"]},{"t":"苦热和姚东桥","f":"七言古诗","c":["蒲风倏有还忽无，冷泉渴吭方沃炉。","絺衫不脱酸儒拘，雪峰纡曲蛇虺途。","骨销积毁止皮肤，隐几兀兀云何吁。","百年荏苒道者癯，双瞳惝恍空悬珠。","六月羲和辔正纡，欲发未发先踟蹰。","蚨母无神百不沽，中夜挥泚凝清酥。","南山流云老鹤呼，流云朝出归复晡。","此中真境如天都，蔀屋尽役修灵涂。","古筇九节渐可扶，松贞樗散任良图。","炎蒸六合沸五湖，别有萧爽容狂迂。"]},{"t":"献虎和姚维宁","f":"五言古诗","c":["昔有山中人，七日化为虎。","开关啖而翁，隳牢抟其妇。","六街恶少年，丛薄窥步武。","悬旌尾不掉，列炬夜瞔吐。","厌饫玄豹脂，垂涎睨麟脯。","正昼近市行，闻者皆悲苦。","安知溪峒氓，庸騃谁比数。","挟砮往从之，机祸迅罗罟。","椎鼓献公所，诸司辟衙户。","貤缗谢彼氓，若岂有职伍。","得非裴将军，狞色貌亦古。","何不排九阍，诉天请雷斧。","壮夫重时运，若但归环堵。"]},{"t":"冬日谩成和郑希大八首 其一","f":"五言律诗","c":["旭日晞玄发，名山秘硕肤。","病鸱乘鬼气，凉月向人呼。","达命还当合，长城正背孤。","问予行住性，朝莫树头乌。"]},{"t":"冬日谩成和郑希大八首 其二","f":"五言律诗","c":["作客三山外，吟诗六叹馀。","乡书多往事，邸报有新除。","雨到鸠鸣歇，冬交楮叶疏。","旧游弥海岳，不似识君初。"]},{"t":"冬日谩成和郑希大八首 其三","f":"五言律诗","c":["云鸟向无迹，寒灯且复然。","奇人知骨瘦，稚子笑须偏。","已负还山约，无劳启阁延。","更谁盱远睫，看日过虞渊。"]},{"t":"冬日谩成和郑希大八首 其四","f":"五言律诗","c":["世情怜阿堵，野兴近参寥。","海内心先醉，琴边语亦调。","玄驹酣逐腐，青狖捷登乔。","岁晏梅花发，谁同渡铁桥。"]},{"t":"冬日谩成和郑希大八首 其五","f":"五言律诗","c":["独夜胡床冷，残书蠹叶翻。","论心从古见，问舌至今存。","藜藿疏天爵，茅茨对石门。","此中清净理，陶令与忘言。"]},{"t":"冬日谩成和郑希大八首 其六","f":"五言律诗","c":["蛙声阴正聒，鹤态病方清。","我自违吾性，谁能了物情。","风云长笑在，花鸟苦吟生。","一片南山石，还堪若砺盟。"]},{"t":"冬日谩成和郑希大八首 其七","f":"五言律诗","c":["盈盈花隐幔，款款蝶翻屏。","西陆寒先动，南薰梦未醒。","短辕何所适，陋室自堪铭。","人道袁安后，吾生亦杳冥。"]},{"t":"冬日谩成和郑希大八首 其八","f":"五言律诗","c":["南中殊气候，含冻草芽青。","剑忆神交赠，骖依逆旅停。","张罗寒雀散，倚槛古梅馨。","懒读胥翁传，吾方养性灵。"]},{"t":"立春和姚东桥二首 其一","f":"七言律诗","c":["朝衣湖上两鞭春，绵力初交谢百钧。","风雨试灯逢粤客，羔豚祈岁赛芒神。","渐知槐目将舒暖，却妒云姿解弄新。","庾信经年归未得，江南佳丽少诗人。"]},{"t":"立春和姚东桥二首 其二","f":"七言律诗","c":["折简频呼宴早春，病容擎盏似持钧。","鬓边梅柏嫌衰飒，世上旂常负圣神。","郡国歌钟官府乐，儿童台阁物情新。","夭桃秾李欣欣在，别是风光不属人。"]},{"t":"元夕和东桥二首 其一","f":"七言律诗","c":["暌月□□每彻宵，十年心迹向寥寥。","闭门只怕梅花冷，怀土方怜棣萼遥。","总有春醪期客至，已无灯疏背人烧。","丽谯南去官桥外，一道笙歌淡淡飘。"]},{"t":"元夕和东桥二首 其二","f":"七言律诗","c":["红纱珠络艳良宵，谁念穷檐锁阒寥。","自有将军传捷到，不妨朝士踏歌遥。","谁家笛谱因风得，何处炉烟傍月烧。","书客短檠堪独赏，玉壶长漏雪花飘。"]},{"t":"泰山送王方伯之官山东","f":"七言律诗","c":["盘道迢遥傍日行，直从肤寸见云生。","东溟自带春前色，北斗方齐世上名。","周室英灵馀阙里，秦家风雨满咸京。","愿随紫凤天门外，却听雍雍第一声。"]},{"t":"挽王封君","f":"七言律诗","c":["南国当时大隐名，容光道是少微精。","乾坤已尽衣冠望，山水惟留杖屦情。","春雨西原迷石笋，秋风楚泽泣金英。","郎君分义年家少，欲荐江蓠恨转生。"]},{"t":"入秋偶成和见素翁四首 其一","f":"五言律诗","c":["海气凉初敛，林姿澹欲曛。","馀生堪秀菊，大业与浮云。","月动孤蟾魄，山空万马群。","预愁萧瑟近，何处挹南薰。"]},{"t":"入秋偶成和见素翁四首 其二","f":"五言律诗","c":["报客嫌嘲热，分秋畅曙晴。","芳园迎白候，哀角送金声。","未怨莲衣冷，将怜桂露清。","端居歌七月，江上此时情。"]},{"t":"入秋偶成和见素翁四首 其三","f":"五言律诗","c":["已觉萧晨至，婆娑问旅乡。","琴书解馀润，灯火逗初凉。","勃窣儒衣敝，陆离兰佩香。","谁知湖海意，络纬近秋床。"]},{"t":"入秋偶成和见素翁四首 其四","f":"五言律诗","c":["潭净鱼还乐，林凋鸟却疑。","物情随所适，吾道倘因时。","霜降星回速，人閒日落迟。","自堪秋兴逸，争畏老如期。"]},{"t":"武夷山和姚维宁","f":"五言古诗","c":["弱冠尚奇远，谬意思登瀛。","孤吟过月午，肩瘦寒山撑。","无弦倚两膝，金石遗琤琤。","学道负俗累，矫首惭秋英。","待罪转运台，所怀异前盟。","空棂掩素卷，正昼如鸱盲。","把君武夷咏，因识兹山名。","隐几噤不语，以意摩峥嵘。","春丝带结绪，一一沿寒清。","潺湲九洑曲，野艇随蜗行。","山家昧晦朔，夜炬推阴晴。","儿孙见俗客，对屋报且惊。","弋凫具中饭，鱼稿羞神明。","有花不夕槁，有木非朝荣。","崩崖出鬼谷，紫茜缘龛生。","朅来寂无见，但挹霞裾轻。","弃置勿复道，世故煎人情。"]},{"t":"挽同年夏太守","f":"七言律诗","c":["杏花才试曲江春，最是优才出牧频。","别久独怜心骨在，愁多曾念鬓毛新。","讵堪宿草连高冢，只有晨星类故人。","老泪今朝收不得，凤雏相对粤溪滨。"]},{"t":"送叶贰府报政","f":"七言律诗","c":["东方千骑引征轺，澹澹晴风郭外桥。","吏道一时监郡最，乡心三月过家遥。","莺花入传催通籍，书剑同舟懒候潮。","凉影午亭移榻处，可堪清论少端寮。"]},{"t":"送张宪副归吴兴和姚东桥","f":"七言律诗","c":["南乡飞雾似轻埃，舟带残潮款款开。","松菊对临犹浩气，乾坤沦掷是雄材。","山中卦影初逢遁，市上仙风旧姓回。","一曲洞庭三万顷，白鸥波里几人来。"]},{"t":"武夷纪游和东桥二首 其一","f":"七言律诗","c":["闻名浪得号希夷，孤枕云林未有期。","缥缈暂看浮黛浅，棱层偏觉带秋奇。","灵岩桂老蟾蜍满，古濑风轻舴艋迟。","道士化将双白鹤，碧岑无路所从谁。"]},{"t":"武夷纪游和东桥二首 其二","f":"七言律诗","c":["偶寻方外惬天游，晓气凝阴翠不流。","毕竟江山非我土，祇将文字贺兹丘。","浮生自识龙蛇蛰，遗蜕空经草木秋。","便欲问君过几曲，紫阳门径可维舟。"]},{"t":"追和野亭八咏 野亭二首 其一","f":"七言律诗","c":["起家长是御炉边，清鉴人窥学士泉。","不见楼台先得地，已闻剑履罢朝天。","四时道在成功后，二室图开引兴年。","自昔关河无限事，午桥庄上有龙眠。"]},{"t":"追和野亭八咏 其二","f":"七言律诗","c":["人见骑驴出近郊，祇馀一亩待诛茅。","鲁墟自后无□渡，阿閤从前有凤巢。","满眼江河嗟世路，到门宾客□时交。","文章老去犹经济，谁羡杨雄著解嘲。"]},{"t":"追和野亭八咏 其三 野堂","f":"五言律诗","c":["日出半扉启，山空四壁光。","金縢馀训诰，缃帙是归藏。","客至蛛丝报，春回燕垒荒。","何人开绿野，异代即同芳。"]},{"t":"追和野亭八咏 其四 野阁","f":"五言律诗","c":["高还山作客，虚是竹为邻。","栋掠朝隮气，窗飞野马尘。","背城迷旧社，望洛吊残春。","阁老谁能见，空闻有凤麟。"]},{"t":"追和野亭八咏 其五 野山","f":"五言律诗","c":["一壑人何去，孤琴只自横。","桂丛岩更古，松老径初成。","浴鸟红泉动，回龙紫雾生。","澹姿看不足，谁见早归情。"]},{"t":"追和野亭八咏 其六 野泉","f":"五言律诗","c":["一派明河色，寒源静且涓。","风回闻玉磬，月到晃银川。","觱沸流何所，包蒙道固然。","讵能甘似醴，惟有止如渊。"]},{"t":"追和野亭八咏 其七 野篱","f":"五言律诗","c":["偶随春婉转，且爱柳萧疏。","莫隔幽人道，宁妨大隐居。","药阑天不限，花界蝶能逾。","好种芭蕉树，年来看卷舒。"]},{"t":"追和野亭八咏 其八 野圃","f":"五言律诗","c":["白木长镵柄，寒畦只自培。","竹分泉脉到，花待土腴开。","阅世寻蓂荚，吟诗入草莱。","桔槔机事尽，愁杀鹤书来。"]},{"t":"挽田太守母","f":"七言律诗","c":["泉南忽报歌钟罢，彤管尊荣次第收。","民社功名唐刺史，云霄志业汉诸侯。","虚疑海上三千岁，直过人间八十秋。","销得西风多少恨，芝兰全绕读书楼。"]},{"t":"秋兴和郑希大 其一","f":"七言律诗","c":["朔风吹地曙衣凉，六郡悲笳出塞长。","玉箸过期空有怨，锦衾遥夜欲销香。","霜姿变草千山白，日影笼沙万里黄。","马上雄光聊复尔，儒生休讶是轻狂。"]},{"t":"秋兴和郑希大 其二","f":"七言律诗","c":["空庭读易夜如年，秋潦仍荒种朮田。","海鹤临霞终野逸，山鸡照水自华鲜。","直修古道通延閤，欲趁回潮解钓船。","君若有期先讯问，好怀多是菊花边。"]},{"t":"秋兴和郑希大 其三","f":"七言律诗","c":["闲云流影似山移，湖海情深梦九疑。","怀古自从摇落后，报恩宁尽显融时。","生涯祇有寻愚谷，好事谁将入渼陂。","归雁一声江月小，不堪长负故园期。"]},{"t":"秋兴和郑希大 其四","f":"七言律诗","c":["阿云游洛岂知回，凉月酣歌影自陪。","江树到秋惊绿叶，野人岐路认苍苔。","闲情独坐吹萧步，古意曾登□马台。","对客不妨频命酒，稍堪真率醉边来。"]},{"t":"秋兴和郑希大 其五","f":"七言律诗","c":["世味频年得备尝，小山丛桂怨淮王。","鱼龙水冷神将秘，鹰隼天高气正昌。","心似晨星还伴月，曲终晴日欲飞霜。","萧条渐觉风流减，寄谢休登宋玉墙。"]},{"t":"秋兴和郑希大 其六","f":"七言律诗","c":["早收堂印似栖迟，壶里乾坤祇自奇。","孤愤岂同镏刺史，一生长愧远禅师。","何曾鼷鼠能知足，安得灵龟□□□。","试问拂衣从此逝，山中底事不相宜。"]},{"t":"秋兴和郑希大 其七","f":"七言律诗","c":["明河清浅火星移，门掩寒螀转自疑。","可是南中为客思，恰如西上献书时。","谩看紫燕腾沙苑，喜逐苍龙出葛陂。","谁念潘郎三十后，二毛先爽寸心期。"]},{"t":"秋兴和郑希大 其八","f":"七言律诗","c":["满城榕叶坐寒庭，却恨高贤叹独醒。","僻性未能随候改，回风谁遣带秋听。","英雄佐世须行役，魑魅依人亦效灵。","茅屋数椽南海曲，松阴开处粤山青。"]},{"t":"秋兴和郑希大 其九","f":"七言律诗","c":["庾公文誉满江关，每向清秋帐未还。","祇有衣冠逢运泰，更无书剑赴时艰。","青山隐约家方远，白鸟夷犹水与闲。","去住多岐终自定，龙门何必苦追攀。"]},{"t":"秋兴和郑希大 其十","f":"七言律诗","c":["仙掌秋高承露盘，人间此夕动悲欢。","金鱼照眼狨鞍杳，锦瑟伤心玉漏残。","鸂鶒沙头贪梦好，芙蓉江上怨盟寒。","定知归去成相笑，何处逢他臭若兰。"]},{"t":"题李都阃履历七首 其一 威宁堡","f":"七言绝句","c":["金牌手上晃龙沙，垂佩当轩付虎牙。","只有矢心如皦日，胡尘未灭不为家。"]},{"t":"题李都阃履历七首 其二 野狐庄","f":"七言绝句","c":["雕弧月满马如风，勇气争将贯日虹。","鸣镝一声传虏首，不须重道二师功。"]},{"t":"题李都阃履历七首 其三 马耳山","f":"七言绝句","c":["三时烽火近关秋，马耳山前小队游。","面缚胡儿称可汗，却教擎剑导鸣驺。"]},{"t":"题李都阃履历七首 其四 沙县","f":"七言绝句","c":["家家县磬逐红巾，杀气遥侵二月春。","一夜将军传□到，凯歌才散稻花新。"]},{"t":"题李都阃履历七首 其五 大帽山","f":"七言绝句","c":["飞崖绝嶂控群山，气尽南军不敢攀。","却笑溪蛮如□玃，岂知悬命彀黄间。"]},{"t":"题李都阃履历七首 其六 姚源洞","f":"七言绝句","c":["十里黄埃羽骑来，中宵飞逻栅门开。","鸣笳拥彻元戎帐，报是生擒浩八回。"]},{"t":"题李都阃履历七首 其七 武举","f":"七言绝句","c":["平原飞鞚截晴烟，杨叶纤纤百发全。","圯下何年闻计略，散关风日好扬鞭。"]},{"t":"题画松","f":"七言绝句","c":["竦壑盘云泰岳东，直披纤秒认青铜。","天河冻裂如飞练，却倚虬髯殿北风。"]},{"t":"挽竹坡封君四首 其一","f":"五言律诗","c":["长笑东皋下，何曾变姓名。","风花双鬓尽，天地一毛轻。","石室权书在，仙台化箓成。","从来多古思，无路哭先生。"]},{"t":"挽竹坡封君四首 其二","f":"五言律诗","c":["数凤堪家庆，犹龙与世休。","张纲行郡国，贾谊在诸侯。","天秘玄桥履，谁移夜壑舟。","万竿金琐碎，空阅镜湖秋。"]},{"t":"挽竹坡封君四首 其三","f":"五言律诗","c":["志养荣三釜，闲和际五朝。","典刑方物化，林薄欲魂销。","地古芙蓉冷，天寒薜荔凋。","越中无那老，谁构大夫桥。"]},{"t":"挽竹坡封君四首 其四","f":"五言律诗","c":["方竹栖鸠小，攒花织凤昏。","济人宁责报，缘子暂承恩。","玉树萦书带，琼英翳石根。","可堪耆旧社，无复见东园。"]},{"t":"松鹤图","f":"五言律诗","c":["孤标高处古，六翮化时全。","石髓沦初裔，金精老正玄。","仙回寒屿月，龙入草堂烟。","细认抟扶路，从前十八年。"]},{"t":"鬼叫滩和东桥","f":"五言律诗","c":["危石悬蜗角，融泥散鹭踪。","驶帆争骋骥，荒壁闭游龙。","白浪馀奔突，黄头尽折冲。","安流何处所，吾欲寄疏慵。"]},{"t":"画松","f":"五言绝句","c":["藻绘宁相解，池亭讵所遭。","主人休狎玩，倏忽是风涛。"]},{"t":"挽述古翁和陈坡山","f":"七言律诗","c":["返扃环堵玩同人，应悟天心别赋神。","不厌旧家黄卷老，可嗟荣路白头新。","湖边儗葬林和靖，谷口虚怀郑子真。","遗草一编经济业，河汾文誉未堪伦。"]},{"t":"白髭","f":"七言律诗","c":["新霜先上戟枝头，初讶苍苍渐未休。","何物谩疑缘苦思，有根元不是穷愁。","称庚广座嫌侵岁，顾影澄溪畏落秋。","清鉴莫须论拔摘，竟谁公望满澶州。"]},{"t":"怀西庄四首 其一","f":"七言律诗","c":["小径逶迤渐不迷，粗营仍是古城西。","晴潮漫窦□□岛，暖絮扶春上燕栖。","白酒河桥花日社，黄螺沙市蛋家儿。","慵疏未乏闲风致，只欠情章向御题。"]},{"t":"怀西庄四首 其二","f":"七言律诗","c":["一带环池演漾光，分明天影晃筠堂。","荷风自战□□暑，槐露平添紫砚香。","偶办蝇须疑遁尾，即看龟甲□含章。","馀生且愧隆中老，解种成都八百桑。"]},{"t":"怀西庄四首 其三","f":"七言律诗","c":["漠漠林姿澹不浓，日斜才见水南峰。","机声札札比邻夕，粳穗油油佃舍冬。","潦尽融□行郭索，天高沆瀣浴芙蓉。","商歌不发蓬扉掩，尘世谁知去住踪。"]},{"t":"怀西庄四首 其四","f":"七言律诗","c":["□□木落寂无喧，陶鼎烟微野气昏。","几个鱼凫还作侣，数家鸡犬自成村。","松披玉粒霜前饭，梅放琼英月下门。","闲据胡床读周易，乾坤何处不私恩。"]},{"t":"南峰小隐图为潘封君赋","f":"七言律诗","c":["白涧红桃旧隐堂，风流仍道自河阳。","草垂书带身先隐，花满诗筒鬓未苍。","龙性九渊神变化，凤毛千仞见文章。","南峰佳气年年别，合貌崔嵬映宠光。"]},{"t":"述梦","f":"七言律诗","c":["通天名笔梦中将，径管铦锋再尺强。","好挽南山符判断，肯驱风雨逐诗狂。","临邛自要相如草，笠泽先虚鲁望床。","消息未知谁识者，巫咸天上更茫茫。"]},{"t":"东禅寺席上次韵送张白斋","f":"七言律诗","c":["野寺逢僧问远征，彤幨摇动若为情。","蓼花秋老君何去，凤鸟时来道可行。","南郡图书当吏最，西山琴鹤况官清。","还知入郭迟迟思，惟爱寒蝉近晚声。"]},{"t":"严陵祠和姚维宁","f":"七言律诗","c":["一丝风力还多少，直与东京系末流。","野性岂堪银艾印，故人空自翠云裘。","千年鹤梦丛祠晓，十里江声古濑秋。","墓下不知高士去，已传清绪过南州。"]},{"t":"十二月菊","f":"七言律诗","c":["晓逗寒丛晚弄芳，天留佳色佐鹅黄。","仙家顷刻应无此，寿域光阴本不常。","风雨最嫌当九日，池园已觉透初阳。","悠然我有平生思，安得南山半亩庄。"]},{"t":"赏菊和坡山二首 其一","f":"七言律诗","c":["穗石仙城五岭南，诗情彷佛见湘潭。","定排白日期高会，直卷黄河对剧谈。","树里飞泉寒掩镜，屋边晴岫碧摇簪。","何人笑认柴桑里，松菊毵毵古径三。"]},{"t":"赏菊和坡山二首 其二","f":"七言律诗","c":["浮生今逐日行南，便拟移家住菊潭。","世事但逢曹相饮，风流当就阿戎谈。","云霄末路成初服，道德私心愧盍簪。","问我别来何所见，两狙相向泣朝三。"]},{"t":"奉和素翁平宁感事二首 其一","f":"七言律诗","c":["数至泉宫忽兆蛇，为刘何议出鼌家。","形如蜂目生还忍，命类鸿毛死亦差。","燬栋却悲巢日燕，游车谁式斗时蛙。","钟陵神在江涛怒，天上论功自降麻。"]},{"t":"奉和素翁平宁感事二首 其二","f":"七言律诗","c":["致师他日谩遗巾，榻外谁能更着人。","肯信刘安真敌国，定知许远是纯臣。","千家鬼录江山厄，列郡兵符草木神。","何处可消冠盖恨，南州吾欲恸先民。"]},{"t":"缓斋歌","f":"七言古诗","c":["人生快意苦不早，恰有高斋名得好。","翕辟长虚众妙门，碧阶春动元公草。","玄机不疾还自速，七十二候年年足。","邯郸道上枕边逢，到了功成黍先熟。","缓时终见鬼神情，世人未解徒相惊。","露花朝在夕照地，佳木排云阅代成。","汇如沧海泳九有，岂必奔流沙石走。","又如大旱望霖雨，渴壤徐滋甘沫透。","斋中有客手霹雳，驱江转岳无遗力。","高明直济佩韦风，张弦却笑安于棘。","古槐斋外黄沙路，数里逶迤接天去。","宫烟翠拂九关开，千骑火城看矩步。"]},{"t":"子昂画马行","f":"古风","c":["我吟杜甫画马诗，恍惚已识乘广姿。","中宵栩栩到梦寐，跃身飙电思天墀。","写生容有夺天巧，子昂此幅人嗟咨。","攒花且莫赏毛质，房星变幻俦能知。","驼经西寺徒善相，章台腾踏还狂驰。","帝闲十二岂无地，蒺藜健勒髯胡骑。","伏胡皂枥为胡老，楚材晋用良可悲。","乌乎，楚材晋用良可悲。"]},{"t":"落发","f":"七言律诗","c":["萦梳种种白兼青，恋顶毵毵知几茎。","杜曲自怜簪处短，东坡还感沐来轻。","悬钧谁试一丝力，晞日但惊千尺横。","搔首江湖聊莞尔，乾坤无限觉衰情。"]},{"t":"郑氏双节词","f":"楚辞体","c":["昼寂寂兮堂阴，乌毕哺兮蛩吟。","姑号兮少子，妇哭兮夫君。","天何道兮有此，地何神兮可凭。","念门祚兮未已，幸一息兮千金。","慨轻尘兮弱草，愿嗣姑兮徽音。","瞻既拱兮墓木，誓同穴兮孤岑。","宛修灵兮不昧，谅匪石兮我心。","骈白首兮受祉，裕潜德兮后昆。"]},{"t":"清洛营言怀","f":"五言古诗","c":["药裹无神功，客久梦亦恶。","中宵插羽来，倚枕候晨角。","平生猿鹄怀，六月尚清洛。","南山豆花白，报我岁云落。","僮仆忻荷锄，而我躬鞬櫜。","敢言重高勋，聊谢四郊怍。","鸿飞何冥冥，弋者仰寥廓。","环溪一亩宫，归欤勿耽错。"]},{"t":"韶音洞","f":"五言古诗","c":["北城馀半里，漓水赴青林。","㟏岈混沌窍，窈窕剧幽㞥。","仄闻帝虞氏，赤虬时幸临。","涕花暗苍竹，九疑悲更深。","我来值秋杪，风日淡以阴。","桐树向萧爽，龙唇寒不吟。","散步下侧径，庙貌倚凄霃。","门铺桂子落，凉云闭晴阴。","周王后骏迹，应在他山岑。","端委复再拜，悠悠江汉心。"]},{"t":"对月独酌和陈定斋三首 其一","f":"五言律诗","c":["空斋还独客，月妙兴焉孤。","豪至依桑落，衰加谢檿弧。","馔寒甘海错，林悄宿山呼。","残夜明楼迥，狂吟与吊苏。"]},{"t":"对月独酌和陈定斋三首 其二","f":"五言律诗","c":["杯纵宜樽满，琴轻爱剑孤。","岁华移斗柄，分野背天弧。","警露鹤嘹唳，悲风猿笑呼。","钟声当月午，疑是泊姑苏。"]},{"t":"对月独酌和陈定斋三首 其三","f":"五言律诗","c":["斗大山城古，烟残野栅孤。","旅遥馀綵笔，戍久敝彫弧。","水落回桡急，更严逻卒呼。","苍髯趋府思，端欲狎樵苏。"]},{"t":"月食用韵答定斋二首 其一","f":"五言律诗","c":["露幽怜桂寂，宫暝觉鸾孤。","厄太频严鼓，辉残殆罥弧。","轮圆千里际，欢动万人呼。","讵为微臣谪，愁深肺未苏。"]},{"t":"月食用韵答定斋二首 其二","f":"五言律诗","c":["只谓阴精减，宁知阳德孤。","虾蟆饶怪吻，后羿辑威弧。","云隙星芒动，山昏木魅呼。","复时天更好，悬影上流苏。"]},{"t":"西征上萧督府","f":"五言古诗","c":["位以当枢重，权应画阃分。","中坚蟠地轴，上将动天文。","藩臬资英略，河山静沴氛。","输红赢楚庾，贾勇尽狼群。","战舍戈回日，炎峰阵抱云。","金汤从所恃，玉石戒俱焚。","东市尸元憝，南陬慰圣慬。","忠襄邕管望，武穆贺州闻。","六月周师戢，三农汉诏云。","旗牌催讯捷，笳鼓犒精勤。","时雨沾烦槁，王风播德芬。","光于萧相国，庸是马将军。","礼乐行将作，乾坤化正欣。","韶弦堪一奏，黧首仰迎薰。"]},{"t":"西征赠屠巡察","f":"五言古诗","c":["殿俗钦文雅，观风赞老成。","贤流希品第，圣主寄聪明。","岳动神羊触，天空振鹭清。","识超时摘伏，权重即专征。","令肃貔貅队，威扬虎豹旌。","片言驱海立，独武蹴山平。","袖里长孺疏，胸中小范兵。","丹青储将相，裘冶旧公卿。","露檄频飞骑，京封尽戮鲸。","愿将吉甫颂，翻入凯歌声。"]},{"t":"竹溪六逸图歌","f":"七言古诗","c":["向来豪宕难指数，至今六子悬清绪。","黄埃寂寞晋风流，南朝乐地空狂雨。","任城酒楼高刺天，沧洲万里危甍前。","楼头歌吹掩白日，下视世界惟苍烟。","徂徕之岨阻且深，松风六月弦素琴。","驱岚捲霭出纤末，全齐大楚窥摇簪。","喷壁清泉带青玉，千周百匝银潢洑。","泛流已置山阴觞，沉璜谩说磻溪曲。","醉中六子谁最豪，李白狂歌宫锦袍。","巢父何须东入海，醨糟泊泊翻波涛。","眼花耳热山欲摧，仰天祼袒韩与裴。","叔明起舞坐陶沔，播弄玄化相喧豗。","惯来童冠习幽兴，琴书恰与尊罍并。","黑甜小啜各有适，娟娟倚竹殊深靓。","峰湖自搦写生管，灯前得意时引满。","分衙十日不登堂，落手良工思犹短。","酒有深趣予未知，侧巾游睇还绎思。","兹图无乃示颓靡，不然安戒沉酣为。","粤州廉访今孝肃，圆扉春草书堆屋。","钦风岂必个中人，寄怀端在溪边竹。"]},{"t":"寿张封君","f":"七言律诗","c":["手栽苍桂看参天，嬉戏光阴八十年。","健赏肯于春草后，细书仍是夜灯前。","诰身柱下初封李，道气人间旧姓篯。","寿域莫教红袖舞，太守先为唱如川。"]},{"t":"醉菊","f":"七言律诗","c":["莫儗陶家别种看，种花谁信对花难。","东篱衣屦忘吾坐，西陆头颅并日餐。","沆瀣天高疑梦到，芙蓉霜重逼神寒。","独怜栩栩金张子，谩倚春风为牡丹。"]},{"t":"至日和峰湖却寄子章弟","f":"七言律诗","c":["气候天南不似冬，鬓容临镜却飞蓬。","江山骨肉孤舟别，阊阖簪裾万国同。","莲漏渐辞长夜刻，兰丛儗觑小春红。","老予独有惊时感，缓带行吟款款风。"]},{"t":"罗池庙","f":"七言律诗","c":["殊方何意托精神，琼玉惟应绝世尘。","词赋自从江上恨，交游宁误死前身。","垂珠不见黄柑实，故事还闻碧柳春。","夕贬一封朝奏表，高名曾是并时人。"]},{"t":"寿春归兴和陈督府","f":"七言律诗","c":["光国宁嫌匹士稀，猎时熊虎入占非。","青麟绣蟒四朝遇，风鬓霜髭八座归。","河上莺花浑御气，眼前云鸟旧兵机。","潞公异数都门在，肯放闲情到翠微。"]},{"t":"追叙清溪翁","f":"七言古诗","c":["清溪之水清以深，飞湍千里赴云林。","溪居逸老雪垂领，誓指素石明贞心。","武惠仍闻涣中土，翁也古雅生乎今。","济人不叙眼前德，耀世宁论头上簪。","饥来饮向清溪水，乐处仍登溪上岑。","浮云苍狗但变态，肯与鱼鸟争浮沉。","忆昔翁未落世时，有问不语惟弹琴。","鹿门老庞足冲寂，鬼谷夫子遗幽音。","几年种树卜天运，苍槐千尺垂高阴。","粤中屹屹御史府，利润恍如溪共临。","岷山瓮口导江出，况复庆源无近浔。","吾闻汇会更百派，浩浩九有流沄沄。"]},{"t":"次韵送缓斋大贺四首 其一","f":"五言绝句","c":["桂岭看南尽，蒲帆向北开。","重兹临别意，不忍更登台。"]},{"t":"次韵送缓斋大贺四首 其二","f":"五言绝句","c":["止雨添新涨，晴山捲幔开。","照君去时面，黄气上兰台。"]},{"t":"次韵送缓斋大贺四首 其三","f":"五言绝句","c":["九天趣上寿，百粤辍维藩。","莫怪贤声远，殊方正感恩。"]},{"t":"次韵送缓斋大贺四首 其四","f":"五言绝句","c":["玉函通北极，金鉴出西藩。","细认台端路，何妨带涣恩。"]},{"t":"沙冈为徐伯川赋","f":"五言古诗","c":["窈窕纡新径，平虚散晚庵。","世情孤竹外，诗兴小梅南。","鸂鶒晴姿澹，鸳鸯暖梦酣。","未谙花溅泪，漫伫月从谈。","稷下才何忝，隆中老更堪。","屏居无俗客，遥放数峰参。"]},{"t":"夜坐次竹溪联句韵二首 其一","f":"五言律诗","c":["习简频休假，怀荣敢献姿。","物情为计早，僧味闭关迟。","敝甑投饥鼠，低樊护冻鸱。","月堂银烛减，趺坐有馀思。"]},{"t":"夜坐次竹溪联句韵二首 其二","f":"五言律诗","c":["倦力祛尘障，苍髯谢世姿。","道从迂处古，机讳巧中迟。","静榻闻喧蚁，清泥戒堕鸱。","薄云归故岫，予亦动乡思。"]},{"t":"芦田市和韵","f":"七言律诗","c":["物情颇逐蘧蘧梦，野意时闻浩浩歌。","天上自纡黄鹄路，江南无限白鸥波。","石滩放鹢春风急，沙市来牛莫雨多。","梅柳亦关兵火恨，苍烟回首奈愁何。"]},{"t":"南亭驿和韵","f":"七言律诗","c":["饥鹰得食飏不搏，老狖知风悲复啼。","江栖数口菜根尽，山樊二月桃花低。","画船急榜候吏走，白板返扃无客题。","揽衣中夜看弧矢，破镜已挂寒岩西。"]},{"t":"古祚驿和韵","f":"七言律诗","c":["荒城隐隐昼恒阴，野火依微瘴水浔。","浊酒不醺嫌兴浅，老予何以答春深。","静看木槿垂花态，欢动山蕉卷叶心。","愿放官家逋负令，江天随处有猿吟。"]},{"t":"昭潭驿和韵","f":"七言律诗","c":["郡城东下瘴江流，利涉今无贾客舟。","桐木归来津口渡，杨花飞过驿南楼。","空山赏籍徒封介，昭代侯功止号留。","潭畔醉渔呼不起，世情应到酒边休。"]},{"t":"宿昭潭馆","f":"七言律诗","c":["曙郭啼乌人未行，春江新草逐愁生。","谢公自济山中胜，王掾终收海内名。","弄野轻云仍有态，送花流水不胜情。","竹间一道茶烟动，知是闲堂赋喜晴。"]},{"t":"五世春官为彭大参赋","f":"七言律诗","c":["未上龙门识素风，年家荣论满南宫。","词头凤翼交云彩，马首春花数杏丛。","星社崔堂还伯仲，冰厅贺氏亦孙翁。","生绡为蓄扶舆气，不看丹青看化工。"]},{"t":"喜鹊","f":"七言绝句","c":["帘额飞花日正迟，选林晴鹊弄春姿。","主人金印累累地，曾见山中变化时。"]},{"t":"鸲鹄","f":"七言绝句","c":["两两低飞趁曙晴，闲庭娇唤竹风轻。","祇应惯见司空客，解语琵琶别调声。"]},{"t":"山呼","f":"七言绝句","c":["武帐鸣飙秋气高，元戎扶醉较龙韬。","谁家绿树朱门寂，不听山呼听百劳。"]},{"t":"寒鸦","f":"七言绝句","c":["栖遍秦家古树枝，曹瞒休咏月中诗。","较量江上寒深浅，不及昭阳晚噪时。"]},{"t":"藤江晚泊","f":"七言律诗","c":["小鸟林依山欲昏，冷烟犹动獞人村。","黄茅屋背登禾穗，白竹篱腰带潦痕。","武帐鸣刁江客悄，平沙争爨仆夫喧。","邛家云水真堪忆，月净梅花未掩门。"]},{"t":"宿鹭","f":"七言律诗","c":["婉颈双双戢振翰，暖沙长恋苇花滩。","身轻也学溪凫并，梦远应怜海鹤单。","夜定影浑欺月色，江空神更敌霜寒。","两年岁杪蛮乡路，剔尽银灯见汝难。"]},{"t":"浔阳除夜","f":"七言律诗","c":["设戟森森小队齐，然松挝鼓郭东西。","行藏笑向浔阳馆，功业嫌听子夜鸡。","金粟悬釭谙近信，银钩走笔动新题。","老予谩有难忘处，徙倚天街认聚奎。"]},{"t":"邕管立春日江行阻风","f":"七言律诗","c":["雄风似倚东皇势，吹我船头欲倒回。","大地渐敷江上草，浮云都付掌中杯。","明堂当御青阳左，旧业仍荒白涧隈。","自古兹辰颁恤政，遐方吾愧佐时才。"]},{"t":"伏波庙","f":"七言律诗","c":["古木巃嵷半亩宫，香江犹为祀英风。","楼船不载浮溟恨，铜柱方标殿粤功。","纵毁世从君子后，争雄人在女流中。","成周远略还无外，白雉千年到洛东。"]},{"t":"西征次韵屠巡察三首 其一","f":"七言律诗","c":["最是等威齐将相，更堪馀地走英雄。","惠分旭日千山晓，令肃高旻九月风。","神算坐筹铜柱外，妖氛迅扫扶桑东。","都狼岭上磨崖遍，不尽南巡疋马功。"]},{"t":"西征次韵屠巡察三首 其二","f":"七言律诗","c":["天上绣斧光煌煌，巡台笑靖古狼荒。","千山澒洞铁骑走，万窟瑟缩长蛇藏。","严霜乍飞日杲杲，时雨欲下云霙霙。","溪翁拥彗贺还祝，迟公洒扫同心堂。"]},{"t":"西征次韵屠巡察三首 其三","f":"七言律诗","c":["露檄宵驰北路长，探丸今日静江乡。","宋功谩录收邕管，汉将徒劳下桂阳。","借箸公还将绣斧，洗兵吾欲挽银潢。","何人更上平蛮雅，续得淮西墨几行。"]},{"t":"吊泾川公墓","f":"七言律诗","c":["湘流依旧国华凋，谩检生平附楚招。","位极上卿仍四部，望隆东观自三朝。","山笼花雾阴犹浅，泉彻椒浆恨岂消。","谢疏不堪挥泪读，夜堂奇气欲蒸歊。"]},{"t":"舟中和宗宪长五首 其一","f":"七言绝句","c":["野兴逢山苦欲生，即嫌新涨乱江声。","西岩未暝东岩白，棹过前溪弄月明。"]},{"t":"舟中和宗宪长五首 其二","f":"七言绝句","c":["十日黄埃上砚屏，谁堪秋月照花明。","素衣暂倚凉风坐，羡杀横江一鹤行。"]},{"t":"舟中和宗宪长五首 其三","f":"七言绝句","c":["最忆南山一翠屏，秋来晴霭转分明。","眼前数点疑相似，却唤回桡傍岸行。"]},{"t":"舟中和宗宪长五首 其四","f":"七言绝句","c":["谁为芙蓉减障屏，梦中云物认朱明。","铁桥十月梅花动，何得麻姑白鹿行。"]},{"t":"舟中和宗宪长五首 其五","f":"七言绝句","c":["淡疑云母隐金屏，远即乾坤判晦明。","便儗振衣千仞上，人间应有近天行。"]},{"t":"和絅庵遗笔四首 其一","f":"七言律诗","c":["闻于习静得观颐，弄野云姿思与迟。","濡沬早敷千变泽，览辉曾见九苞仪。","堂灯风雾孤凭几，墓木星霜几执规。","八极有神应驭气，不知何路逐安期。"]},{"t":"和絅庵遗笔四首 其二","f":"七言律诗","c":["藩省才名雅自堪，端如鹏翼快图南。","较量大策嗟时运，刊落陈言谢俗惭。","药裹先秋虚小草，家林旧味寄馀甘。","剑亭千里高贤去，传得残篇与笔谈。"]},{"t":"和絅庵遗笔四首 其三","f":"七言律诗","c":["午夜凄清吊鹤音，山桥江槛想经临。","芙蓉虽好看宁足，鶗鴂先鸣怨已深。","有客曾过虚白室，于君难见彼苍心。","东风不减元公趣，满地仍开紫玉簪。"]},{"t":"和絅庵遗笔四首 其四","f":"七言律诗","c":["小閤花枝渐碍冠，江乡高誉尚曹官。","书麟始断周删述，问鵩真灾汉治安。","月满梁间疑可见，精还箕尾恐芒端。","救滨万里澄清辔，莫恨台司副愿难。"]},{"t":"代和四首 其一","f":"七言律诗","c":["沃沃清髭渐拂颐，霄程宁卜遽衰迟。","闽山风动馀行马，汉署香残自令仪。","作赋有人悲正则，登楼而我怅元规。","平生几点交游泪，洒向新阡愧后期。"]},{"t":"代和四首 其二","f":"七言律诗","c":["手把遗文思岂堪，新愁聊与吊江南。","身为僧后疑真幻，名在卢前信不惭。","千里未终才自逸，万金难售剂宁甘。","夜台可作人心在，谈到平湖便喜谈。"]},{"t":"代和四首 其三","f":"七言律诗","c":["天问他年嗣楚音，巫咸不语夜将临。","玉盘何意频圆缺，瑶海无凭谩浅深。","入省独摇惊吏笔，盖棺安死济时心。","一经堂上多良冶，肯负金缕尺只簪。"]},{"t":"代和四首 其四","f":"七言律诗","c":["清班不见切云冠，地下修文定有官。","鸣雁独飞犹海曲，残潮还到自临安。","烦忧似草萦暌绪，往事如泉饮恨端。","万里大川风正紧，一舟谁共济艰难。"]},{"t":"分得长安此去欲何依七韵送俞子宜 其一","f":"五言律诗","c":["郭门临祖道，晓旭动花光。","似君去时面，眉间佳气黄。","兼程发湘水，计日见江乡。","拜庆高堂上，春风萱草长。"]},{"t":"分得长安此去欲何依七韵送俞子宜 其二","f":"五言律诗","c":["携手东江侧，情如浊水澜。","但挹别离色，不觉樽俎欢。","曲江金镜录，而子触邪冠。","努力当于迈，能令黎庶安。"]},{"t":"分得长安此去欲何依七韵送俞子宜 其三","f":"五言律诗","c":["挂管荒落馀，佳处差可纪。","月满梅花天，不说千金市。","图书山近郊，兰桡拢江涘。","三年持宪心，清寒得如此。"]},{"t":"分得长安此去欲何依七韵送俞子宜 其四","f":"五言律诗","c":["飞走各有营，久客念岁序。","不见官道槐，兔目忽满树。","入门当何时，幸借食前箸。","送君漓水长，予亦从此去。"]},{"t":"分得长安此去欲何依七韵送俞子宜 其五","f":"五言律诗","c":["春晏雨脚滋，桃花泣红玉。","津吏把传符，徒御立宵烛。","天上贵仙宅，台榭青云覆。","但见鞲上鹰，不闻龙有欲。"]},{"t":"分得长安此去欲何依七韵送俞子宜 其六","f":"五言律诗","c":["昔年骢马路，绣斧铁为柯。","四座噤不语，骈耳骇悬河。","属来气犹健，长风撼洪波。","手中二三策，讵为谒常何。"]},{"t":"分得长安此去欲何依七韵送俞子宜 其七","f":"五言律诗","c":["树柏古台上，苍苍晨带晖。","柏以况君操，晖光良不微。","京城香雾尘，长傍马首飞。","素袍未改色，谁能怀所依。"]},{"t":"苦雨和缓斋","f":"七言律诗","c":["钟鼓声微不报晴，坐知江涨夜还生。","看云都是因风起，占毕应嫌背月行。","厌胜玄庭闻水咒，忍嘉牟陇切农惊。","城阴欲捣虞山庙，可是词衡怯柳争。"]},{"t":"挽巡察谢侍御","f":"七言律诗","c":["阳和风力动兼权，直向秋潭看静渊。","越绝江山筹策外，闽中桑梓泪花前。","游魂何处应宾日，报德无徵欲问天。","遗疏一函看不得，霜髯宁是受知年。"]},{"t":"闻鹃和合溪","f":"七言律诗","c":["初声犹是月中啼，稍送馀寒逼曙衣。","花歇渐催红雨乱，树芳应藉绿云依。","悬知沃野勤方作，偏动高楼怨未归。","莫儗天津桥上听，杜陵残泪不胜挥。"]},{"t":"移家不至葵轩戏以诗次韵答之","f":"七言律诗","c":["春浮沙际浩无涯，鸂鶒撩人近复赊。","香灺煖风催试葛，江光新潦约回槎。","南山亦有蘼芜草，此日徒怜百合花。","总是铁肝销不得，蛮烟未灭肯为家。"]},{"t":"柳江夜泛","f":"七言律诗","c":["炎歊郁郁遍炎方，病骨贪程趁夜凉。","鸥聚暗惊铜角响，入家微近玉绳光。","望穷喧濑叉鱼火，思杀轻纨弄月堂。","独扣溪舷歌鞅掌，未应文字损韶芳。"]},{"t":"拟赠","f":"七言律诗","c":["节旄光动峤南軿，司马奇踪照杀青。","衮钺忆曾窥志郡，风骚誇为觅书屏。","江山是处高卿月，宇宙无穷一使星。","越绝故深摇落恨，未随衣屦过山亭。"]},{"t":"苍梧雨中和定斋二首 其一","f":"七言律诗","c":["南山欲雨渐云蒸，斋阁清愁病与仍。","独鹤背人行且啄，两凫骄我睡相凭。","风炉煮蟹聊供具，寒水罾蛟敢赞能。","文字可娱贫亦得，烛花何夕对陈登。"]},{"t":"苍梧雨中和定斋二首 其二","f":"七言律诗","c":["日晏东邻无饭蒸，西家绮席候云仍。","山杯自爱当花举，江槛那堪趁雨凭。","秋兴定知衰易减，世情争与懒相能。","词场偶对陈平垒，得似刘邦困白登。"]},{"t":"追挽张都阃","f":"七言律诗","c":["虎头信有通侯骨，马革何曾壮士悲。","邕管山河挥羽日，交州风雨死绥时。","报恩宁顾万金宠，仗节惟馀孤剑知。","疑冢椒浆今入土，祇应冥莫鉴孙慈。"]},{"t":"送杨内斋佥司谢政归越","f":"七言律诗","c":["马首看花旧丙辰，黄埃端愧隔清尘。","生涯老去凫鸥在，初服归来杜若新。","呼吸午窗依姹女，歌游晴谷答幽人。","镜湖一曲春深浅，思杀风流贺季真。"]},{"t":"送戴醉菊都司谢政归燕","f":"七言律诗","c":["来时建节鬻琴归，谁悟将军远世机。","百粤边声清梦隔，三湘秋水故人稀。","樽前狎鸟新情致，服上蟠螭旧等威。","黄菊落英如可拾，颓龄相济莫相违。"]},{"t":"丁丑中秋玩月和合溪","f":"七言律诗","c":["尘世清光重此时，夜晴那惜倚阑迟。","槎通银浦客何去，秋遍唐宫人未知。","轮转高山看桂满，席妨深树命樽移。","酣歌不作西岩望，神魄休疑我是谁。"]},{"t":"谢惠莲酒二首 其一","f":"七言绝句","c":["香带芙蓉露气多，暖光融媚上颜酡。","虚教日莫成遐想，携向银塘答艳歌。"]},{"t":"谢惠莲酒二首 其二","f":"七言绝句","c":["掌上琉璃绿雾轻，茂陵何处乞金茎。","情知不似莲花味，别是将军酝籍生。"]},{"t":"谢饮张合溪舟中","f":"七言律诗","c":["清秋哀角动千峰，蛮瘴迎飙淡不浓。","雄镇偶逢严仆射，扁舟谁况郭林宗。","笔间风雨啼山鬼，橘里乾坤御草龙。","野客岂堪追逸赏，江樊遥负木芙蓉。"]},{"t":"过象棋滩和合溪","f":"七言律诗","c":["潦涨秋江失旧涯，石穿枯柽见浮槎。","林端禽语人烟寂，天上船来客路赊。","未许新霜催碧杜，渐看明月映苍葭。","烧痕晓遍青峰脚，报道山猺种晚畬。"]},{"t":"九月水际拒霜","f":"七言律诗","c":["气肃天高花数枝，迎船映竹亦离离。","寒崖浅涧各自媚，蜀槿戎葵又一时。","霜腻尚馀藏蝶粉，烟须犹见缀蜂丝。","老予敢续猗兰调，惆怅曾看粤水湄。"]},{"t":"遣闷和合溪次拒霜韵","f":"七言律诗","c":["黯黯江天唱竹枝，娟娟秋水正愁离。","烛花小馆长吟夜，雁阵高云薄暮时。","石蕨香霏收玉屑，溪鱼竿重挽风丝。","身惭紫绂西藩后，兴在黄湾青岸湄。"]},{"t":"鳌峰寺饯饮谢骆任之","f":"七言律诗","c":["持檄经秋催鹢舫，疏筵几日借僧轩。","风云岐路犹南北，灯火比邻已子孙。","竹叶杯深山上局，蓼花潮到寺前村。","要知楚泽青兰月，只有怀君不可言。"]},{"t":"舟中和张天益二首 其一","f":"七言律诗","c":["风前箫鼓落滩声，云际孤帆逐鸟轻。","秋满残林初送雨，夜严荒徼渐传更。","无心更著江湖记，庞俗曾闻山海经。","惟谢同行张博望，一尊遥为寄高情。"]},{"t":"舟中和张天益二首 其二","f":"七言律诗","c":["江空滩急榜歌声，西上奚囊一叶轻。","云影自从秋里薄，山姿岂必雨前更。","愁心附雁知何去，逸迹凭诗记所经。","蔀屋晨烟犹未业，缓箫鼍鼓不胜情。"]},{"t":"东山宅题沈卿小景四首 其一","f":"五言绝句","c":["茶烟深院青，东野媚晴晓。","嘤嘤林端声，听似秦吉了。"]},{"t":"东山宅题沈卿小景四首 其二","f":"五言绝句","c":["凉树转佳阴，游丝静无力。","翔集各有营，朱门自迟日。"]},{"t":"东山宅题沈卿小景四首 其三","f":"五言绝句","c":["去住悲胡燕，低飞趁泽鷮。","江南秋色早，幽意满风苕。"]},{"t":"东山宅题沈卿小景四首 其四","f":"五言绝句","c":["白露蒹葭晓，寒塘静故幽。","羽珍终自惜，不上古楂头。"]},{"t":"清洛营次韵四首 其一","f":"五言律诗","c":["日表迎亭午，辕门稍面坤。","合围疑月满，飞逻破山昏。","蛮垒巢帘燕，军行饮涧猿。","莫欺铅椠老，盾上旧能言。"]},{"t":"清洛营次韵四首 其二","f":"五言律诗","c":["支倦聊飞檄，何才望奠坤。","国怀纡白羽，乡思赴黄昏。","仗策驱哮虎，舒缨缚跳猿。","于襄吾肯赋，六月契前言。"]},{"t":"清洛营次韵四首 其三","f":"五言律诗","c":["荐岁从征地，南陲亦厚坤。","瘴来山疠重，月出野燐昏。","草伏随穿虺，林号想纵猿。","论兵古所忌，予乃禁无言。"]},{"t":"清洛营次韵四首 其四","f":"五言律诗","c":["谩多赢日月，长负小乾坤。","蒸雨纤蕉润，挑灯细字昏。","租荒南涧芷，兴老北山猿。","敢辱高庸疏，凭谁咏薄言。"]},{"t":"龙门驿","f":"七言律诗","c":["西去江程此暂淹，篁间落落见穷檐。","千山暑雨方行役，六月烽烟未解严。","荣路畏途谁自解，风晨花日几能兼。","家园望里吾将老，信有灵龟不可占。"]},{"t":"钓者","f":"七言律诗","c":["烟雨凄凄着一蓑，此乡安得有詹何。","丝纶自系浮沉重，罗网终关得失多。","古石芦中空岁月，扁舟湖里足风波。","夜归沙市村醪白，背卧晴天独放歌。"]},{"t":"睢宁三异歌","f":"七言古诗","c":["睢宁县前净如水，睢侯釜中惟俸米。","侯持堂印几春秋，直视翳桑无馁鬼。","社亭渐渐两岐风，陶河一雨驱蝗虫。","水勿忧虞旱毋苦，我侯双手悬天工。","古史班班书杜母，孱陵先生身姓鲁。","谁郡号咷嫠媪啼，避官却委南山虎。"]},{"t":"七星岩","f":"五言古诗","c":["势引诸天近，名嘉列宿称。","鬼工开混沌，神气伏歊蒸。","□曲坤囊括，援高艮辅层。","冥搜顿束燎，迷惧欲循绳。","□□香龛侧，岩唇药臼凭。","石寒垂碧乳，厓古络苍藤。","题认前朝氏，缘栖后果僧。","鸟吟堪谷媚，人语即山应。","霞飏仙裾彩，飙回客袂绫。","民恫萦吏责，临眺暂时曾。"]},{"t":"傅本学兵宪四西卷","f":"七言律诗","c":["二十年馀棘下名，况闻三道倚澄清。","踪如太史仍乘传，权似中书即掌兵。","晋鄙天浮秦树色，楚乡船趁粤滩声。","桑弧我亦平生思，何得霜髭满镜生。"]},{"t":"灌阳立春","f":"七言律诗","c":["东郊笳鼓献芳晨，陌上晴风市上人。","彩仗环牛方祝稔，筠盘呈韭已逢新。","泉声动壑寒应减，土脉迎花暖未匀。","不是执规行岁令，遐方那解更知春。"]},{"t":"除夕和陈峰湖","f":"七言律诗","c":["尘世都交等大傩，微名应未怨蹉跎。","灯花夜色寻常动，榆荚春光积渐多。","霜里乌啼天已白，眼前民瘼鬒先皤。","丁宁莫作罗浮梦，惭愧山中看奕柯。"]},{"t":"腊日闻雷和何西桥","f":"七言律诗","c":["层阴饶冻闭清平，雷动龙渊蛰已惊。","桂岭传车稀暖梦，蒲溪僧饭有寒盟。","风花思致谋咨客，笔砚经纶赋洗兵。","春事不遥闲记省，青丝红腻各关情。"]},{"t":"人日和宗宪长朝用","f":"七言律诗","c":["□□清愁与散霾，草堂先为寄诗开。","坐知穗石□□檄，闻道蓬壶儗泛杯。","烛影满天催晓旭，车音何处候春雷。","郑公剑履还前殿，千古无劳叹楚才。"]},{"t":"松涧歌寿郑封君","f":"七言古诗","c":["翁家种德如种松，庆源直与流泉通。","青鞋头白不入市，未闻謦欬闻高风。","落落千章大厦材，清冷澹澹天河来。","贞姿未许论星纪，气争瀑布排风雷。","天阴巨壑苍蛟立，万年黄澒垂秋色。","偓佺奔马世不逢，麻姑双黛临寒碧。","小阅人间数十秋，悬灯写易细蝇头。","餐松饮涧好颜色，坐见青牛出信州。"]},{"t":"诸葛亭和西桥方伯","f":"七言律诗","c":["祠亭背郭饶松桂，野蔌居人荐豆登。","西蜀关河依虎据，南阳风雨快龙升。","梁间月色灵光动，蛮徼天威沴气澄。","十倍霸才谁赋得，泚毫先愧杜陵曾。"]},{"t":"游清湘书院有怀顾东桥","f":"七言律诗","c":["翠微幽路细盘回，亭馆全依巀嶪开。","弦诵收功初此地，江山如画岂无才。","鸣鸠隐柳春将雨，邃谷嘘风昼欲雷。","最忆凯之期不得，新阴空赏野棠来。"]},{"t":"湘山寺","f":"七言律诗","c":["山色才分霁后天，郭西幽胜楚南禅。","吏情只谩寻方外，侠骨无劳认劫前。","鸟际直浮衡岳树，林端恰下灌江船。","繁花休讶妨僧径，我本无心彼亦然。"]},{"t":"兴安分司闻冯汝舟贰守讣","f":"七言律诗","c":["分司忽报零陵信，函面题孤讶始开。","淮海雪花他夜别，月山茶味隔春来。","辰回岁舍谁称寿，禄尽星屏世恨才。","旅旐欲东曾未发，江乡吟吊不胜哀。"]},{"t":"全州行台忧旱得雨兼闻灌阳贼遁志喜和屠巡察","f":"七言律诗","c":["棠墟无复咏来旬，柏府雩龙檄若神。","候雨谩传辰次甲，有秋堪记岁当辛。","天眠白板红巾靖，花满青筒绮句新。","借策定从更化日，巡功何地不宜民。"]},{"t":"和屠大巡话别","f":"七言律诗","c":["吹角城头语未阑，惊看小队驻江干。","湘山雨洗炎荒瘴，衡岳云连水路寒。","殊渥久知仍副望，清颜垂别亦难欢。","劳歌莫唱骊驹调，豸史曾闻铁作肝。"]},{"t":"次韵张合溪赠梅轩入广","f":"七言律诗","c":["江上清风铁笛来，旧游闻吊古龙堆。","不妨桂楫随潮放，定拟莲樽为月开。","邃致惯听谈物外，孤标真合况花魁。","罗浮若到飞云顶，却看南溟似泛杯。"]},{"t":"再赠梅轩","f":"七言律诗","c":["素衣澹澹漓江晓，海鹤形神秋更闲。","太史南观曾禹穴，弥明西下自衡山。","藜灯今雨更生馆，道气多时老子关。","古庾梅花看不足，须君新赋远游还。"]},{"t":"湘山寺登函秀亭和屠大巡","f":"七言绝句","c":["鹫岭谁开罨画函，玉虹飞沫落云岩。","偶来不是缘僧味，惯听黄鹂弄远杉。"]},{"t":"期西轩少保游东岩寺承以诗见酬次韵奉答四首 其一","f":"五言律诗","c":["年华饶野适，秋兴付郊行。","定梵闻蝉语，晴山度雁声。","酣馀催转令，豪至听谈兵。","小立斜晖久，岩姿晚更清。"]},{"t":"期西轩少保游东岩寺承以诗见酬次韵奉答四首 其二","f":"五言律诗","c":["出郭仍高会，烦襟散早凉。","白沙迷近溆，红树报新霜。","道合耆英雅，声流汗竹香。","从前閒适日，随地足恩光。"]},{"t":"期西轩少保游东岩寺承以诗见酬次韵奉答四首 其三","f":"五言律诗","c":["共嗟山相逸，却讶地仙行。","密座惭联璧，投诗乏报琼。","忘机林鸟过，照眼水云生。","谁道江湖远，悠悠世上情。"]},{"t":"期西轩少保游东岩寺承以诗见酬次韵奉答四首 其四","f":"五言律诗","c":["招提宛近郊，樊径候方袍。","花映闲衣履，风生旧节旄。","道心时闭阁，明目夜挥毫。","何必华山上，林堂即养高。"]},{"t":"入偏桥","f":"七言律诗","c":["东来秋兴满肩舆，仰首看山俯看书。","总有轻身随过鸟，祇应衰鬓感焚鱼。","柴门人语牂牁近，竹寨泉声楚甸馀。","谁遣燃香擐甲待，穷乡何限未宁居。"]},{"t":"阅武","f":"七言律诗","c":["东郭高牙峙将庭，楚山迢递送边青。","银鍪夺日元戎队，铁骑连云列校营。","岂有神功驱水石，当闻号令肃风霆。","天心无战皇威远，已报笛村放犊耕。"]},{"t":"怀坡山数家庄","f":"七言律诗","c":["东郊东上数家庄，路入沙河水竹乡。","借马花期曾独往，打鱼芦畔得徜徉。","老谙世味牙边蜡，闲忆山盟木杪霜。","诗酒未应嫌白发，尺书先遣雁南翔。"]},{"t":"辰州病中见慎轩辞报","f":"七言律诗","c":["故人新上乞休书，邸报遥传伏枕初。","戎马已成芒部捷，勋阶仍就贵阳除。","幽期定忆江心寺，小构容连水尾居。","只恐岩廊虚左日，未应贤达向樵渔。"]},{"t":"澧州田间谕穫者","f":"七言律诗","c":["腰镰荷担散西畴，尘甑今承小稔秋。","报社宁辞明日蜡，计佣还羡几分收。","官租有约输宜早，私讼无情忍即休。","横索年来遍城府，巡轺端为到荒州。"]},{"t":"清明郢中承高吾院长见寄次韵奉答二首 其一","f":"七言律诗","c":["阳春台上弄芳晴，几片杨花过晓城。","小燕稍誇风日好，古松那记岁华更。","黄湾旧兴悠悠着，南浦朝云浩浩生。","谁遣疏慵兼早病，江湖何事不关情。"]},{"t":"清明郢中承高吾院长见寄次韵奉答二首 其二","f":"七言律诗","c":["佳辰方爱出郊晴，况报诗邮到石城。","帽底柳枝催变鬒，眼前人事类传更。","洪都美政归新府，故纸常谈笑老生。","小计别来今五载，祇应春水付深情。"]},{"t":"益阳纪事","f":"五言古诗","c":["潭州楚南郡，犷黠俗易敝。","伊昔炎宋时，控禦恒置帅。","惟我神圣朝，绥靖亦数世。","可惜财赋区，章组杂冗赘。","去年五百峒，椎牛立赤帜。","居氓弃业走，行旅昼心悸。","予时移镇来，集议询根蒂。","山川聚米观，列阵掎角势。","团夫县点壮，甲长家举义。","号令风电驱，狼兕各歼殪。","似闻益阳箐，倡乱渠首二。","敢叛假息恩，遂揭怒车臂。","岂缘侵歉馀，我有赈恤惠。","岂缘科率烦，厥咎乃长吏。","鸷猛安足雄，明法匪虚器。","湘乡覆辙多，何不为戒事。","吾皇文武资，衰予备驱使。","安良在除暴，予也报恩地。","慎尔血气躯，毋使城市弃。"]},{"t":"黄菊","f":"五言律诗","c":["绕砌开应遍，相看思故遐。","迎飔香更古，裛露色偏华。","懒命尊前侣，仍怀海上家。","强将金比况，端觉世情差。"]},{"t":"橘","f":"五言律诗","c":["两度看佳实，香匀觉未殊。","迂怀愁变枳，俗眼讶垂珠。","地肃霜姿早，林稠土脉腴。","摘来浑不御，容易岁华徂。"]},{"t":"归雁","f":"五言律诗","c":["沙塞何时别，哀音闻月中。","暗添鸣杵恨，急趁过江风。","安止怜寒浦，斜行学晚虹。","迸泉挥老泪，流转有民恫。"]},{"t":"菊枕","f":"五言律诗","c":["稍异游仙制，言扶目力衰。","清幽专筦簟，灵异上须眉。","梦浅南柯遇，枝从九日辞。","素屏攲侧着，彷佛见东篱。"]},{"t":"高吾院长寄惠仪礼","f":"五言律诗","c":["制作仍匡辅，隆平业故尊。","遗编窥品节，流涕忆精魂。","灵鸟墟周甸，游麟吊鲁门。","太丘吾所畏，此道雅应存。"]},{"t":"汉口","f":"五言律诗","c":["扬帆风力正，数里过晴川。","客饭鸡鸣午，王程雁影边。","喧声闻閧渡，快意羡回船。","问俗今何去，荒凉已目前。"]},{"t":"楚邸高远堂试灯","f":"五言古诗","c":["楚苑长春胜，宗贤雅道遐。","清尊馀醴酒，芳树始梅花。","兴卜欢娱夜，文追典丽家。","歌钟催景色，星月避灯华。","火技呈新制，金铺缀落霞。","共怀安物泰，不但乐宾嘉。"]},{"t":"双寿为莱阳王侍御赋","f":"七言古诗","c":["扶桑曈曈转迟日，莱阳先见长生国。","神禾垂颖动千年，颗粒还堪驻颜色。","三槐几叶高堂在，最是清门盛车盖。","蓬山遥挹数烟青，瑶海环看净如带。","寿翁白胡照地光，阿毋齐年鬓未苍。","晴华芳苑鹿车过，风前玉树诸孙行。","湖南绣斧识凤毛，千里不见豺狼嗥。","眼中风力汉水立，老予何幸当孤标。","便道承欢欢未极，海屋之筹十才一。","我歌不独双寿歌，请继于家纪阴德。"]},{"t":"郢中和坡山元日之赠","f":"七言律诗","c":["玑衡昨夜纪星回，椒颂今朝掌上杯。","立马江峰无雁过，寄梅山驿有人来。","谩占蜡炬闻佳语，欲倩春风拂素埃。","衰鬓剧知孤节钺，郢中犹遣一帆开。"]},{"t":"送江侍御","f":"七言律诗","c":["未厌西南作远行，游龙春峤傍花明。","碧鸡关外先秋约，黄鹤楼前今雨情。","两省官评还藻鉴，三司事会尽戎兵。","礼庭喜气年来别，雁塔增题一代名。"]},{"t":"遣疏","f":"七言律诗","c":["囊琴谁遣别沧洲，何限缁尘阅素秋。","药裹不灵嫌遁尾，道书无诀了藏头。","山情或幸天心鉴，樗散宁希国论收。","钓石黄湾明月里，未烦重买五湖舟。"]},{"t":"院北池亭次韵留咏诸公","f":"七言律诗","c":["月槛风扉夏不扃，台端谁信有闲亭。","一泓止水涵天净，无数繁花得雨醒。","江汉迢遥通凤沼，乾坤浩渺失鸥汀。","坐看三楚还形胜，知是神州几翰屏。"]},{"t":"院后池亭纳凉","f":"七言律诗","c":["□著□□咏自公，书床恰在柳塘东。","鸣蝉直避葵心日，芳药端宜水面风。","笑眼乌儿争楮子，闲情鱼队入芦丛。","江南何地无烦热，愿奉韶薰万国同。"]},{"t":"喜雨","f":"七言律诗","c":["玄冥灵旆过江乡，青遍平畴五月秧。","疏簟轻凉欺短发，决渠新水漫闲塘。","一瓢便拟誇神贶，十雨曾闻验世康。","试问老予何所喜，踏冰先减杜陵狂。"]},{"t":"行部宜城访长渠故迹无复知者","f":"五言古诗","c":["宜城古楚都，风土故秀媚。","康狼与荆山，屹屹并西峙。","山中有夷水，滔滔日东注。","秦当祸楚时，藉之以得志。","后人引长渠，祸也乃其利。","沃壤三千顷，食者长渠惠。","国社已屡更，地力岂不废。","卓哉孙曼叔，无乃举职吏。","源流悉讨寻，堙翳就疏治。","功慱民匪劳，井邑多委积。","迩来四百年，天人两茫昧。","停轺访遗老，顾指迷乱次。","初疑陵谷迁，蓬莱向为地。","又疑虎豹区，藜蕨恐捐弃。","复疑强力民，播弄并吞势。","方食辍箸想，人事有隳坠。","追惟癸未旱，全楚绝遗穗。","今年旱更甚，所赖惟少备。","吏政无恒规，泽民当上最。","兹渠废与兴，一一关国计。","长恸曼叔魂，安得汝共事。"]},{"t":"次韵燕泉司空和陶五首 其一 真想","f":"五言古诗","c":["淑灵孕秀彦，蚤岁冠乡书。","雾豹焕文彩，诸良叹不如。","渐鸿抱孤志，冥冥历天衢。","游息必时乂，焉能齿空疏。","李贺客京邑，高轩辔常纡。","贾生策利害，于治亦绪馀。","孝皇肆贤网，喜得奇货居。","摅心在军国，妙契水与鱼。","行志三十年，文墨安足拘。","眷言惬真想，归卧南山庐。"]},{"t":"次韵燕泉司空和陶五首 其二 遥情","f":"五言古诗","c":["淩晨溉嘉木，坐冀晚阴休。","物势讵能尔，所期敏佳游。","出门亡择侣，凫鹜皆品流。","冲怀写未极，延盻导湍鸥。","遵野有幽侧，鸣琴在中丘。","调高响易绝，皇皇悲寡俦。","生平鲜昵合，安得恩可酬。","大道匪榛翳，伊人曾到不。","昨日忽已暝，来日恐烦忧。","遥情复何寄，三益行当求。"]},{"t":"次韵燕泉司空和陶五首 其三 宿好","f":"五言古诗","c":["读易欣晚得，怀玄意何冥。","绯组岂不贵，可副中岁情。","广野春已媚，伊谁共班荆。","白云悠然起，聊以况我生。","壶觞答嘉叙，良觏邀淳明。","儿孙递长育，昕夕希世平。","卜居幸在此，贤轺辍长征。","老微秉耒力，闭门还笔耕。","挺植荣木性，宁为蔓草萦。","宿好苟未负，聊谢竹帛名。"]},{"t":"次韵燕泉司空和陶五首 其四 馀闲","f":"五言古诗","c":["郴有何公岭，遥望富春山。","山中读书客，归欤曾待年。","狂飙少静宇，惊濑非渟渊。","嬉猱本樛木，鸣鹤仍青田。","齿发涉知命，稍悟天人间。","物役恒在后，物理定于前。","眇眇泛泽士，茶灶留孤烟。","如何清圣轨，芜没首阳巅。","百年爱长夏，晷刻皆馀闲。","敢薄渗园傲，尔生同介然。"]},{"t":"次韵燕泉司空和陶五首 其五 还读堂","f":"五言古诗","c":["衡山扶舆气，终古未尝疏。","一派最清淑，盘薄郴阳庐。","庐中复何有，异畜三世书。","司空更奇逸，指南载轻车。","筑堂破万轴，俨艺良圃蔬。","春苗与冬实，一息根裔俱。","上保金玉德，次恢帝王图。","修辞具三立，匪道将焉如。"]},{"t":"潜江阻风二首 其一","f":"五言律诗","c":["指旆樊城北，收帆策口东。","风能驱水立，予亦叹江空。","败屋还三户，枯杨只数丛。","烦愁欺酒兴，潋滟负杯中。"]},{"t":"潜江阻风二首 其二","f":"五言律诗","c":["地歉人多瘠，江寒雁不来。","二仪纷变态，一客独兴哀。","涝退秋痕定，租宽制限催。","阳春终不远，随意报蒿莱。"]},{"t":"荆州至日","f":"五言律诗","c":["问俗频乘传，荆南小至临。","日躔回斗次，雪候暗江浔。","才薄希归早，时徂恋旧深。","病予妨拜舞，北望愧裾簪。"]},{"t":"新恩为沂乐廷卿赋二首 其一 晓阙颁书","f":"五言古诗","c":["载籍翻中秘，丹青饬化神。","人文窥万古，名物丽三辰。","琰琬传先美，芬芳播至仁。","泰居心乃广，敬止德何纯。","光彩尧章焕，渊源圣学新。","玄辞惟理数，大道总彝伦。","侈赐开芸閤，珍藏累锦茵。","江阴他夜望，宝气烛高旻。"]},{"t":"新恩为沂乐廷卿赋二首 其二 春殿读卷","f":"五言古诗","c":["月淡鸡人晓，风融象魏暄。","贤才纷入彀，明主正临轩。","蕴藉谁三策，包罗若万言。","贞怀嘉剀切，浩养录雄浑。","绮靡铺张彻，玙璠品第存。","题元天翰丽，得俊圣颜温。","席密孤卿右，恩联八座尊。","儒荣非一事，特此重时论。"]},{"t":"院后桂花","f":"七言古诗","c":["烦襟自感零露秋，金粟蕊蕊佳香浮。","鄂台峻肃称高品，树者无乃多前修。","北斗城隅月色浅，转觉晓气尤清幽。","岂惟蜂蝶带痴性，苍髯绕树恒三周。","我家扶胥古渡口，一种便足光林丘。","素娥首肯乞仙本，行见紫薇封南州。"]},{"t":"贺坡山子冠","f":"七言律诗","c":["皎皎风前玉一枝，三加真见盛威仪。","宾阶谁更当先辈，梓里吾惭托旧知。","有子正符将大日，称翁仍是未衰时。","从今只数欢华地，好挽南溟入寿卮。"]},{"t":"邓侍御文瑞以诗见投次韵奉答","f":"七言律诗","c":["端如沃暑挽寒泉，手把清篇揖惠连。","身际六龙催转日，气逾孤隼快横天。","狼潜野寨无宵警，吏戢山家有晏眠。","一自楚台相语后，矩洲谁数读书年。"]},{"t":"悯雨次巡院韵二首 其一","f":"七言律诗","c":["尘缨未许濯帘泉，敢把民忧付十连。","信有密云难作雨，愧无凉德可回天。","揽衣每为中宵起，拂枕谁能正昼眠。","三楚萧条非一日，未应愁瘁过当年。"]},{"t":"悯雨次巡院韵二首 其二","f":"七言律诗","c":["深涧灵湫总涸泉，炎风吹野郢襄连。","回栏徙倚频瞻毕，静院焚香自吁天。","旱魃岂堪长作祟，雨师何得更高眠。","鞭龙早逐滂沱去，社鼓村村报有年。"]},{"t":"喜雨用韵二首 其一","f":"七言律诗","c":["山瓶无复注灵泉，沔水云蒸汉水连。","风马奔腾疑捲泽，雷车澒洞欲掀天。","操豚市户晨方集，蓄堰溪农夜不眠。","细检承平储预籍，止留诗案到今年。"]},{"t":"喜雨用韵二首 其二","f":"七言律诗","c":["入夜檐声瀑玉泉，三农行见米珠连。","衰迟似我那关世，精白何人不愧天。","浊酒家家拚鳖饮，玄潭处处恣龙眠。","閒人谩有江湖纪，休记随车过楚年。"]},{"t":"读南坦寄示辞疏二首 其一","f":"七言律诗","c":["早从时序托成功，仙骨梅癯兴自雄。","山水幽期还坦上，风云英望且隆中。","油幢笑卷三关碧，玉粒亲遗万庾红。","散发扁舟归未得，清尘遥羡浙西东。"]},{"t":"读南坦寄示辞疏二首 其二","f":"七言律诗","c":["出入三朝未二毛，南归琴剑一轻舠。","鸿私暂乞台臣假，温旨长徵国士遭。","开社肯劳招六逸，结亭先拟近三高。","悬知芳思东篱外，何日江邮寄和陶。"]},{"t":"乙酉冬宴客黄鹤楼用崔韵","f":"七言律诗","c":["鄂城自昔登临地，崔咏何年擅此楼。","总有才华多役役，祇应江水付悠悠。","天开诗客阴晴景，木落渔家远近洲。","形胜不殊风物异，谩堪笳鼓散清愁。"]},{"t":"丙戌秋与二镇同集用韵","f":"七言律诗","c":["豁然一目数千里，不信齐云别有楼。","雁旅东来吴会近，鹢风西上蜀江悠。","仙踪石角孤龛月，井税金沙万顷洲。","却望严城开府地，可胜民瘼浩新愁。"]},{"t":"重阳后太府北楼赏菊观罩鱼","f":"七言律诗","c":["江城初霁重阳雨，暇日同登节镇楼。","黄菊有情还照眼，茱萸无分最惊秋。","渔人竞下横池网，客子真怀钓湘舟。","优剧不妨供小坐，世情方汝更悠悠。"]},{"t":"出郊","f":"五言古诗","c":["命车东出郊，淑景惬远眺。","桃李虽未华，青麦芒尽耀。","春泥腻不滑，冻石引泉窍。","多雨人未虞，一饱行已兆。","悠悠武穆魂，寂寂黄童庙。","枯朽随流埃，名且白日照。","楚才后焉乏，旌纛亦相绍。","匪无英与贤，芜没谁自料。","真卿不识面，风云起屠钓。","君子重行道，岂必尽枢要。","百年逝水澜，两曜竞丸跳。","来者吾惧衰，孤怀冀同调。"]},{"t":"经羊侯庙","f":"五言律诗","c":["开府多英佐，分符此上游。","雄图恢晋宇，遗德照襄流。","雪后登临少，碑前感慨休。","独馀苍岘庙，犹为赛春秋。"]},{"t":"风逆","f":"五言律诗","c":["襄阳距鄂渚，七日下江程。","北客乘风便，南船与浪争。","孤蓬寒火淡，百丈古堤横。","迟疾终相倚，吾方达此生。"]},{"t":"舟中夜坐","f":"五言律诗","c":["群动已向息，劳劳念倘休。","寒厨供瀹茗，小仆问添裘。","且理还家梦，都忘拍岸舟。","江空月皎皎，端欲恣神游。"]},{"t":"夜泛","f":"五言律诗","c":["日高风正猛，江晚浪初平。","倚棹星辰动，开窗□□□。","回洲冲雁起，到岸接鸡声。","暂伴渔人宿，将齐吏隐名。"]},{"t":"梦","f":"五言律诗","c":["愕愕萦虚枕，真从百幻奇。","未谙周是蝶，稍似兽维狸。","异感吾何有，符占世亦疑。","鬼神多戏谑，未把吉凶思。"]},{"t":"送石亭殿讲","f":"五言古诗","c":["十载惊为别，孤标忽暂攀。","恩华射赤壁，风槩被青山。","语旧频沾臆，聆新几解颜。","翰摇奎宿动，舟倚法星还。","江转龙飞甸，春明虎踞关。","仙葩仍月窟，伸骏必天闲。","谩纪经过地，高联侍从班。","私心长儗□，公服近栖鹇。","文藻惭吾老，繁芜待子删。","后期殊未定，浩兴满黄湾。"]},{"t":"送刘执斋刑侍","f":"五言古诗","c":["道气看弥重，高怀幸再宣。","曲江馀契阔，闽海旧周旋。","抚事追先美，登楼问昔年。","仙乡滩十八，魏阙路三千。","出入台端望，平反宪贰权。","节旄春色净，鹢势汉波沿。","山水分题在，箕裘统类传。","才堪君位正，地愧我居偏。","岁月髭双改，风云梦独悬。","最难垂老别，徒有酒如泉。"]},{"t":"龙头竹杖歌","f":"古风","c":["龙头之竹托根深，太和福地苍崖阴。","五风十雨足喷薄，妙乃百节全坚心。","南岩大仙雅秘惜，一赠便觉无□□。","□云金箓记尺度，晦冥出入群邪辟。","怖邪迂癖□□□，时参几格如嘉傧。","私怀每计示崇奖，镂铭愿□□工韵。","君不见太乙真人夜下世，青藜柱到传经地。","又不见涪翁筇竹枝，驱虎穷山独行路，眼底赤虬须鬣具。","嗟乎，变化吾不知其处。"]},{"t":"纪闻","f":"七言律诗","c":["岐阳风日足栖梧，翙翙何因到海隅。","鹪鹖胡为混灵綵，麒麟偏得并祯符。","声中律吕谁相和，影落关河恐亦孤。","知子不缘循吏出，祇应明圣比唐虞。"]},{"t":"得报子章弟落第抵家","f":"七言律诗","c":["高秋犹报束书归，千里何时试骏蹄。","未必红瑜终抱璞，祇缘文锦各成机。","青霄旧路还鸿渐，云厦谁家却燕飞。","潜德未涯吾已老，清门须尔有光辉。"]},{"t":"发赈","f":"七言律诗","c":["南湖北堰漫风埃，野落山樊燕不回。","何处画图当御献，已无邻粟泛舟来。","忧勤每问青州策，宴暇真忘浙水杯。","独奉一函宽恤诏，千仓亲许百城开。"]},{"t":"答程以道侍御","f":"七言律诗","c":["往时南楚触邪冠，义气秋旻讵得干。","白雪几篇皆隽□，严霜六月更高寒。","杜陵老自甘闲逸，正叔才堪化治安。","湖海十年思会面，荆门初把一书看。"]},{"t":"石桥驿","f":"七言律诗","c":["莽苍千里澹无姿，冻閤层阴雪欲垂。","荒驿鸡晨催仆发，长途药日许医随。","逢山特约肩舆缓，束燎应防据馆迟。","颇怪北风欺病骨，䫿飕终日马前吹。"]},{"t":"草店","f":"七言律诗","c":["迢遥周道净轻尘，此去荒州始号均。","几户衡茅犹带雪，两行官柳欲回春。","儿童惯识朝山客，租赋全轻化国人。","颇觉楚封真不迩，南雍乡土即西秦。"]},{"t":"太和山","f":"七言律诗","c":["万壑珠宫照下方，百年经始戴文皇。","横林谁认前朝碣，绝嵿时飘异国香。","功行几尘符道契，精神何地挹灵光。","圣恩许放宫祠例，愿乞南岩一草堂。"]},{"t":"访黄宪墓","f":"七言律诗","c":["道气终窥千顷陂，贤流得拟子渊宜。","人间师表今安仰，梦里形神倘见之。","姓氏吾惭江国远，王纲公际汉风移。","修灵恐逐堂封尽，未奠蘋花空所思。"]},{"t":"观物 其一","f":"七言绝句","c":["杏花漠漠随寒雨，桃藿欣欣照早霞。","无限芳华看不足，只缘多在野人家。"]},{"t":"观物 其二","f":"七言绝句","c":["□□结蚓惊雷出，野浍轻蛙得水鸣。","端策何劳问詹尹，细看蠕动即人生。"]},{"t":"观物 其三","f":"七言绝句","c":["争巢灌木鹰何鸷，认主深庭燕不离。","旧社未逢题燕客，五陵思杀射鹰儿。"]},{"t":"观物 其四","f":"七言绝句","c":["蒲芽戢戢方披冻，柳眼盈盈忽满林。","谁采松花南涧曲，莫教黄腻过春深。"]},{"t":"楚邸致新茶","f":"七言绝句","c":["开籯淡淡楚山馨，入眼纤纤谷雨青。","便试朝宗江汉水，不烦遥涉为中泠。"]},{"t":"平贼拜赐银币志感","f":"七言律诗","c":["綵豸夺将云锦丽，内金镂是贡时文。","虚庸忝窃成功赐，老大多惭学道闻。","小效敢论裨尺寸，鸿私何有答铢分。","愿销赤子潢池甲，万国弦歌奉圣君。"]},{"t":"丙戌除岁","f":"七言律诗","c":["鄂渚俄惊岁再除，江天雪霁日光舒。","吏封台印裁红楮，童理官资振素书。","忆弟自从逢雁后，分年应在听鸡初。","然松烧纸曾同俗，谁道迂人世事疏。"]},{"t":"元日用韵","f":"七言律诗","c":["葱葱晓气满庭除，蕙颖兰芽渐向舒。","短发可堪金胜集，新诗聊纵綵毫书。","市声不动重城外，人事惟占上日初。","苍柏两行春雪后，高台清丽转扶疏。"]},{"t":"寄赵叔鸣西河耘业二首 其一","f":"七言律诗","c":["西河得拟杜陵居，丘壑从来道晏如。","风格有人传白下，诗声此日变黄初。","峰岩惯作晨参客，潮落时闻晚唱渔。","清鬓照花君自许，肯抛康济为劬书。"]},{"t":"寄赵叔鸣西河耘业二首 其二","f":"七言律诗","c":["愿赋斯干颂始营，辋川图画浪先名。","楼前山自希文借，趣里园同靖节成。","东野输青留奕史，春风垂绛引经生。","微才更阻江湖际，未得桐华洞口行。"]},{"t":"题徐侍御昭德录","f":"七言律诗","c":["赤霞黄石想丰神，贲典仍华谢俗身。","八十莺花馀戏剧，三千礼乐自陶甄。","人间桑梓蜀威远，梦里江湖楚寿春。","骢马风声满南国，堂封回首重嶙峋。"]},{"t":"江上对月","f":"七言律诗","c":["多时江岘雪花迷，初月今宵转汉西。","洲渚尽看分野色，仆夫犹怯踏霜泥。","望穷北极青衫湿，思入南乡白首低。","银烛数残衾亦冷，远林兼送一乌啼。"]},{"t":"放船","f":"七言律诗","c":["楼船箫鼓动江湄，荻火初炎早具迟。","不独鼋鼍潜静浪，尽教凫鹜弄晴澌。","清吟未为醑翁旷，孤笑谁堪墨客悲。","别墅从来西涧曲，梅花几树怅归期。"]},{"t":"水禽","f":"五言律诗","c":["入眼还微眇，柔翰隐淡文。","能飞终贴水，欲去恐离群。","雪重江沱冷，秋深露草蕡。","平畴好莫近，罗网正纷纷。"]},{"t":"冬笋","f":"五言律诗","c":["久客谙攻苦，时荒罢茹新。","谁翻湘渚雪，稍送洞庭春。","雨露香仍淡，山林味却真。","勿教频采斸，待看拂云身。"]},{"t":"灵寿杖","f":"五言律诗","c":["大岳先霜古，须弥后劫登。","鸠形镂绿玉，龙挂引红藤。","习懒吾成性，扶危尔效能。","罗浮门户浅，携得上崚嶒。"]},{"t":"雨","f":"五言律诗","c":["已从人日雨，漠漠浃旬连。","漫绿春头草，仍迷夏口船。","雷声喧浦近，农事悯时先。","预恐为灾沴，悁悁夜炬前。"]},{"t":"晴","f":"五言律诗","c":["晴日午犹淡，闲园足媚春。","鸳誇娇影净，蛛放喜丝频。","晒药嗔童懒，拈杯任我真。","东门杨柳色，恐怨未归人。"]},{"t":"燕坐","f":"五言律诗","c":["静院还迟日，仍堪簿领馀。","帘垂鸲鹆语，砌暖海棠舒。","江汉悲形役，诗书悔性疏。","苦怀蒲涧曲，无路问何如。"]},{"t":"丙戌腊八阻风策口","f":"七言律诗","c":["江路邅回还策口，簿书傍午且华颠。","光阴流转此何日，郡邑嗷嗷非有年。","隔舸香糜晨馔玉，挟风残雪昼飘绵。","土阶蓂草孤根老，望断青阳楚岸边。"]},{"t":"雪晴和程侍御","f":"七言律诗","c":["萧萧平野散荒烟，微旭将升雪后天。","下食饥鹰飏草际，呼晴灵鹊掠车前。","迢遥诗画江山贶，倏忽寒暄造化权。","已分驰驱从所适，未堪长路况衰年。"]},{"t":"与竹塘院长拟登太岳诸峰予以病不果","f":"七言律诗","c":["积雪经旬喜却晴，平舆冲晓踏澌行。","洞天自拥青莲胜，尘土空教白眼横。","丹穴徒闻虚九室，樃花曾道阅三生。","郧台仗钺长邻此，游兴还堪趁早莺。"]},{"t":"邓侍御洞庭金鲤图歌","f":"古风","c":["洞庭之潴八百里，摇星簸日无时已。","蛟妖蜃怪族各殊，琐碎讵敢窥神鲤。","曲陵屃屃巨背高，大帜炜炜朱鬐骚。","金鳞六六足百劫，珍目两两横波涛。","负舟一听轩辕乐，再驾湘妃返南国。","还从汨水葬灵均，自是悠然无底壑。","此物神奇亦相世，得符麟凤称嘉瑞。","楼船绣斧撼天来，瞥见乃在春湖澨。","丹青鱍鱍光芒动，画工那许知神用。","满堂宾客但咄嗟，衰予感旧堪长恸。","伊昔毅皇岁丁卯，秋旦拿舟发江表。","正书玄龙矫矫飞，壮观自诧平生少。","光阴流转如振埃，谛视赤鲤□龙材。","龙材龙材，慎尔变化谁能猜，江南无处无风雷。"]},{"t":"检南原旧翰哭之","f":"五言律诗","c":["零落湘筠箧，清词照眼明。","百年几长恨，一字数吞声。","白日蛟螭舞，玄山宝玉横。","所嗟游息日，随地足寒盟。"]},{"t":"挽淩溪子","f":"五言律诗","c":["别子洪都日，盘胸藻绣明。","时花争艳曲，春水送蜚声。","问讯惊容减，追谈感岁更。","怕经淮海曲，恐值众芳生。"]},{"t":"雪中经王粲楼","f":"五言律诗","c":["城上崇楼晚，荆南积雪天。","苍生阻饥后，白野泬漻边。","世路遭时短，才华与赋宣。","胡鹰九霄思，矫翼臂鞲前。"]},{"t":"寄东湖二首 其一","f":"五言律诗","c":["东湖若个畔，屴崱火山高。","花净苍梧雨，松翻碧落涛。","百年几鹤氅，八座一鸿毛。","豸骨缘何瘦，曾均出入劳。"]},{"t":"寄东湖二首 其二","f":"五言律诗","c":["轻帻时迎客，青鞋称谢居。","窥林惊倦鸟，钓濑得嘉鱼。","懒问平泉业，劬抄验药书。","家山看不远，随意命安车。"]},{"t":"老至三首 其一","f":"五言律诗","c":["老至岂今日，烦忧祇自繁。","修名纡紫极，短发任黄昏。","读易嗟何得，知非可复论。","最嫌春梦浅，不到郭西村。"]},{"t":"老至三首 其二","f":"五言律诗","c":["三月明朝是，新青万木齐。","团兵时近举，荒政半轻赍。","建节终为客，冲樊且放麑。","庄荀日当席，端不费招携。"]},{"t":"老至三首 其三","f":"五言律诗","c":["今年江汉上，寒食倍寒衣。","岂尽风光别，都缘筋力微。","短篇閒事记，新火谩恩辉。","千里旗冈路，松楸岁已违。"]},{"t":"诏使二首 其一","f":"五言律诗","c":["驿骑真天下，颁时亦早春。","大纲罗宇宙，万目灿星辰。","字字沾枯槁，看看到隐沦。","愚臣亦何幸，三度播皇仁。"]},{"t":"诏使二首 其二","f":"五言律诗","c":["仁爱天心在，灾眚治与俱。","周王能励行，汉令祇蠲租。","愿扫贪狼窟，还呈瑞凤图。","报恩无对述，愧杀下帷儒。"]},{"t":"卧病荆州行台检曲江公龙山诸篇二首 其一","f":"五言律诗","c":["讵识神龙性，空窥海鹤姿。","秋毫捐相印，老兴逐江麾。","未惜孤标远，终嗟八柱危。","匣中三尺水，恨不斩胡儿。"]},{"t":"卧病荆州行台检曲江公龙山诸篇二首 其二","f":"五言律诗","c":["郡閤日无事，文章地有馀。","龙山空禊饮，鸟道自宸居。","貌觉忧时老，心孤许国初。","岂知乡后愧，伏枕对残书。"]},{"t":"新莺","f":"五言律诗","c":["融风吹楚泽，节物递相惊。","朱鸟来何暮，黄鹂晓已鸣。","历枝声韵巧，照眼羽仪轻。","休怨风霜早，长林太廓清。"]},{"t":"食樱桃","f":"五言律诗","c":["南中曾载御，楚泽近相看。","爽口宁虞热，残春尚带酸。","兴深青箬笠，恩远赤瑛盘。","两树西林雨，垂垂实向丹。"]},{"t":"黄精","f":"五言律诗","c":["楚山春雪里，山户斸黄精。","法制仙经录，王羞下土情。","药魂招不返，病骨若为轻。","腾化何多术，吾嗟草木生。"]},{"t":"观打毬十二韵","f":"五言古诗","c":["暖透元戎邸，公馀小队过。","沙场朋稍集，綵棒力先和。","势疾星驰阪，规分月印波。","遥工催上画，近捷巧收窝。","俯击华裾委，傍挥运道颇。","大娘休舞剑，壮士罢横戈。","瞬笑千夫失，能争百步多。","未观超距戏，且等弄丸科。","乘兴频移帜，迎欢促按歌。","凡情才敢露，绝艺目空睋。","底用方尤物，真堪敌睡魔。","定知张仆射，老去奈狂何。"]},{"t":"洞庭湖用杜韵","f":"五言古诗","c":["两年荆楚路，此日洞庭湖。","水净云连席，风调客转舻。","野情纡岛屿，民命但菰蒲。","日御随浮没，坤倪定有无。","春莎迷雁碛，夏潦退龟涂。","远适忧还尔，奇探兴未孤。","观鱼忘大泽，聆乐倚燋梧。","不识芙蓉国，空临渤澥图。","角糈虚吊屈，泪竹倘怀虞。","拟弄横江笛，将携煮石炉。","靓游逢汉女，异觏舞天吴。","莫比沧波渚，能栖朝暮乌。"]},{"t":"江行 其一","f":"七言绝句","c":["寒凫两两掠江湾，諠岸陈词对岸山。","捲幔看山还听讼，真成忙里得偷閒。"]},{"t":"江行 其二","f":"七言绝句","c":["一片邮旗百丈前，野歌相和引楼船。","垂杨摇落风霜后，棠茇何人汉水边。"]},{"t":"江行 其三","f":"七言绝句","c":["夫首飞蓬妇亦然，一枝横桨棹渔船。","饥寒相对何惭色，愁是鲥鳇鱼鲊钱。"]},{"t":"江行 其四","f":"七言绝句","c":["景沔人家古岸隈，新堤百里屹崔嵬。","眼前保障知何用，只道今无汉水灾。"]},{"t":"江行 其五","f":"七言绝句","c":["日落寒江四面红，画船犹趁晚来风。","乾滩才过闻箫鼓，不道横流正此中。"]},{"t":"江行 其六","f":"七言绝句","c":["侧岸繁霜白草根，溪翁晨汲掩柴门。","百城安得皆良牧，任尔安居长子孙。"]},{"t":"江行 其七","f":"七言绝句","c":["纱窗日色晓曚曚，如此江天夜欲风。","未省风时还顺逆，只今吾意欲从东。"]},{"t":"江行 其八","f":"七言绝句","c":["立鹭眠鸥尽可怜，我行三日且江边。","黄芦翠苇民生在，茅屋数家无早烟。"]},{"t":"江行 其九","f":"七言绝句","c":["江干薄莫小村孤，借爨家家却仆夫。","天意不教闲懊恼，好风吹过野猪湖。"]},{"t":"江行 其十","f":"七言绝句","c":["邮卒铃声破晓来，几州文字一时开。","老予经略无多事，不为生财为节财。"]},{"t":"秋夜应城馆听雨三首 其一","f":"七言绝句","c":["山城不断晚鸦飞，月送残窗淡淡辉。","午夜雨声如捲海，汉阴恐有赤龙归。"]},{"t":"秋夜应城馆听雨三首 其二","f":"七言绝句","c":["我家扶胥古渡边，惯听鸣雨散空川。","枕屏淅沥虚相聒，不似西林翠筱前。"]},{"t":"秋夜应城馆听雨三首 其三","f":"七言绝句","c":["溪声一夜学回潮，檐溜家家瀑布飘。","行李莫愁明日路，从来骤雨不终朝。"]},{"t":"次韵高吾院长拟游君山且至风阻","f":"五言古诗","c":["君山渺何许，□□□□睇。","宛其几席傍，浩隔云水际。","萧森万木丛，坐恐古道翳。","高怀掠鹭纵，迅楫决蛟眦。","巽二胡凭陵，玄云散拖曳。","回桡岂足惮，胜赏怅未济。","可赏世讵无，所怅负宿契。","帝乐杳不闻，孰觏竹上涕。","杜陵渼陂上，亦恐风雨戾。","鲸波会当平，迟君泛春霁。"]},{"t":"赠林小泉中丞开府畿内","f":"七言律诗","c":["才名雄自敬皇时，甸服真堪托保釐。","七泽风雷随鼓角，三关云鸟动旌旗。","莱公锁钥君何重，范老江湖我独衰。","二十年前文酒地，塞鸿汀芷各天涯。"]},{"t":"送刘伯儒总宪广东","f":"七言律诗","c":["湘汉真看意气多，别怀其奈杪秋何。","京华公望牂牁起，海曲春光滟滪过。","共喜邦人依斗岳，未嗟吾道付江河。","柏台栖凤知无日，自有淩霄玉树柯。"]},{"t":"至日同唐侍御仲宣楼小集","f":"七言律诗","c":["词客飞楼俯郡城，野烟宫火散高晴。","江光不动空中见，岁色无边至后生。","地迥鱼龙犹寂寞，沙融凫鹜谩纵横。","吴门蜀道今寰宇，何必昭丘重旅情。"]},{"t":"再和唐侍御","f":"七言律诗","c":["澄江百折带寒城，曾为英雄割一成。","地主有才终定霸，侯门何士旧收名。","黄埃傍马悠悠去，白草连天渺渺平。","莫倚丹梯临返照，杜陵愁思暮还生。"]},{"t":"次韵高吾闻报书怀","f":"七言律诗","c":["鹿溪深处草堂幽，无限烟霞着子由。","近说制荷成野服，即闻飞剡到前旒。","巾车拟谢桃花水，束帛先回菊露秋。","总为中兴览贤俊，乾坤今日是东周。"]},{"t":"子楚兰生韦庵坡山各以诗见贺残腊达荆次韵奉答二首 其一","f":"七言律诗","c":["十州名迹竟谁传，拟掷台章学醉眠。","汤饼一杯仍岁晚，诗邮千里却春先。","阴功且愧黄承事，衰鬓何如白乐天。","西墅东林多旧约，几时盘盏侍灯前。"]},{"t":"子楚兰生韦庵坡山各以诗见贺残腊达荆次韵奉答二首 其二","f":"七言律诗","c":["浮名虚羡络金牛，奕势还于末着收。","南国未须论召茇，西林端欲问菟裘。","看儿尽是怀亲日，作客空深感旧秋。","闻道长生开洛社，月溪蒲涧可同休。"]},{"t":"荆州除夕","f":"七言律诗","c":["城头鼓角夜乌惊，门外戈鋋列炬明。","为喜化工成四序，不辞衰鬓坐三更。","枭卢何处咸阳客，琴鹤来朝蜀道程。","爆竹一声还一笑，儿童那解鬼心情。"]},{"t":"元旦","f":"七言律诗","c":["鄂台两度庆兹辰，又见荆南物候新。","柏酒照儿初得岁，桃符随俗谩宜春。","九天阊阖中兴主，千里簪裾下土臣。","懒向青铜争齿发，三朝亲际太平身。"]},{"t":"院西新梨试花","f":"五言律诗","c":["即看春首发，曾是腊前移。","紫萼呈新綵，瑶华抱素姿。","酣歌何院落，淡月共台池。","力病仍临玩，玄功正在兹。"]},{"t":"发荆南","f":"五言古诗","c":["扬旌西出郊，雾重林薮湿。","橹指沙岸草，春芽向戢戢。","亭午殷其雷，尽启百虫蛰。","神龙尚深蟠，蛙蚓纷合沓。","吾何远行游，旦夕异丘陌。","长怀负蒸黎，况敢辞物役。","策短不资身，皓髯讵如戟。","开箧把旧书，自愧老无得。","黾勉追前纵，暗性忘险僻。","日斜立船头，滩高浪花白。"]},{"t":"夷陵","f":"七言律诗","c":["夷陵城外白沙湍，冲雾船头试水竿。","林麓有花堪吏隐，山前无句果儒酸。","愁心自折民恫尽，尘迹都交鹭影单。","偶向渔翁访风土，迩来人事更摧残。"]},{"t":"兵书峡","f":"七言律诗","c":["石门遥瞩仅容车，绝壁攲岩画不如。","峡道向知天险壮，江霾犹蔽日光初。","幽探怕有蛟龙宅，峻览曾无鹳雀居。","底用风雷长护守，人间那读古兵书。"]},{"t":"虎来","f":"五言古诗","c":["归州二月朔，虎来入其郛。","眈眈百步内，长风与之俱。","居人昼户闭，州吏敲钲盂。","自卫固疏脱，焉能护樵苏。","甘柔择羊豕，馀嚼抛饥乌。","终焉跳踯去，掌迹遗城隅。","忆在清洛营，营门夜惊呼。","千山月色淡，咆哮气何粗。","传箭召军吏，此物胡为乎。","师谶贵伏猛，安得姑舍□。","煌煌列百炬，持满攒骍弧。","炳文失故穴，不格如穷鼯。","油幢小宴犒，剑舞偕笙竽。","细脔遍士卒，茵籍存毛肤。","归城数百室，岂必皆非夫。","苛烦殆有甚，为尔长嗟吁。"]},{"t":"三闾乡","f":"五言古诗","c":["大雅婴多忌，怀王亦懿亲。","国均虚匹士，泽畔即孤臣。","有作思公子，何心媚妇人。","脩门山鬼语，初服芰荷纫。","故宅随芜没，遗篇与世珍。","香溪春尚浅，未得荐芳蘋。"]},{"t":"舟中","f":"五言古诗","c":["晴丽欣时令，衰迟忝使星。","近谙夔子国，昔上吕仙亭。","业静依三昧，情深吊独醒。","红云纡北极，绿墅滞西坰。","渔网侵晨举，樵歌逼晚听。","疏才虚点缀，殊俗费叮咛。","侧岸棠梨白，漫坡宿麦青。","禽言随地异，茶味破春馨。","孤思淩题竹，馀生附采苓。","景幽憎蹇步，眼涩谢残经。","荫树得倾盖，沿湍骇建瓴。","舷傍渔父醉，祠下女郎灵。","水照山鸡影，岩留木魅形。","暂教便历阅，未暇怨飘零。","难索乌麻饭，将逢紫实萍。","暝林啼狒狒，蛮服染猩猩。","卉木日争媚，衡茅昼返扃。","不妨冲舴艋，为爱舞鵁鶄。","鸟道催诗课，山邮致药瓶。","从来张长史，老去曲江汀。"]},{"t":"巫峰二首 其一","f":"五言律诗","c":["两两迎船出，相看慰远游。","摇簪浮楚峡，列戟入夔州。","思带融春丽，姿凝宿雾幽。","王程殊未暇，曾为数回头。"]},{"t":"巫峰二首 其二","f":"五言律诗","c":["旧爱江郎石，层阴照眼明。","天教闲玩览，山岂惮将迎。","不改古今色，宁含云雨情。","从来岑寂意，未可少猿声。"]},{"t":"简木","f":"七言绝句","c":["□蜀山中只数章，楼云笼雾近千霜。","明堂高栋真何忝，未免人间寸尺量。"]},{"t":"古楠","f":"七言古诗","c":["山人报我得古木，芳脂滴血楩楠香。","万牛直驱万仞表，青铜古石盘穹苍。","风雷有时战斤斧，氤氲融液成文章。","千年魑魅递呵守，精灵上应青龙光。","孤根正尔中隆栋，况有岐干堪修梁。","冲涛逆浪献大内，天颜一笑嗟贞良。","左绳右引足艺巧，涂金抹綵仍煇煌。","清丝妙竹被落宴，子孙千亿歌斯干。","谛思物理煞有数，短篇未竟还悽伤。","磻溪不遇老渔死，楠乎幸免同枯杨。","愿言勿挠保终吉，不然群木徒圆方。"]},{"t":"八阵石","f":"七言律诗","c":["曾烦三顾委经纶，功盖当时尽瘁身。","鱼水向知真遇主，英雄宁道尽欺人。","椒浆可答关山恨，云鸟仍驱水石神。","今日太平词赋客，画船箫鼓蜀江滨。"]},{"t":"白帝城","f":"七言律诗","c":["还从三峡控三巴，万丈丹梯袅袅斜。","初日岗峦开警跸，他年风雨隐悲笳。","锦江水到鱼龙迥，赤甲春深草木华。","可惜不稽天下士，暮砧犹自野人家。"]},{"t":"滟滪","f":"七言律诗","c":["瞿塘峡口两崖间，巨石遥当陆海关。","粤客谩疑真砥柱，夔人誇道小金山。","险防如象行忘戒，神避然犀有遁奸。","谁谓西游无好兴，也凭奔峭看潺湲。"]},{"t":"鸬鹚","f":"五言律诗","c":["散立晚何适，低飞性自便。","趁鱼浮峡静，逐鹭戏涡旋。","去住溪翁物，征科水户钱。","闲怀因汝动，欲上曲江船。"]},{"t":"百舌","f":"五言律诗","c":["百舌亦时鸟，逢春逐燕归。","发声兼委曲，命侣故骞飞。","厌聒迟明枕，愁喧薄暮帏。","炎风吹广野，历耳自应稀。"]},{"t":"晦","f":"五言律诗","c":["东风殊不竞，寒气苦相侵。","自是云为态，真成陆易沉。","褰帷愁细字，照户失清岑。","愿促羲和辔，能舒独客心。"]},{"t":"雨","f":"五言律诗","c":["蜡炬夜犹淡，晨晖未可希。","润馀山色重，沾足橹声微。","巴峡泠泠急，巫云段段归。","溪翁亦何幸，正昼掩荆扉。"]},{"t":"山居","f":"五言律诗","c":["望中三五户，青麦绕山居。","自理鸡豚栅，谁程子姓书。","生涯依蜡树，吏政剥棕榈。","未羡高车客，能令骨肉疏。"]},{"t":"瀼西怀杜","f":"七言律诗","c":["向来文赋赞专能，李白才名偶并称。","孤贱不遗房太尉，艰危时荷柏中丞。","馀生几亩东屯穫，旷思千回赤甲登。","吕葛未期空白首，独携妻子下江陵。"]},{"t":"晴","f":"七言绝句","c":["晴日巴阳千嶂开，布帆轻捷爱沿洄。","老予自了江山债，候吏无烦鼓角催。"]},{"t":"万县","f":"五言古诗","c":["川东十数州，此地事征榷。","醝贩浮大航，蛮賨日交错。","絮饵靡铢遗，焉能漏金艧。","敢深良价藏，刺颖及囊橐。","市算鸡豚馀，琐细尽薇藿。","追惟作法谁，意岂佐公约。","往虞值蓝鄢，多垒亘郊陌。","征人疲后爨，关吏谢不获。","监司鄙冗杂，主者必倅幕。","虽无数橐驼，亦已鲜琴鹤。","显王御上世，赋税且云薄。","末造计舟车，谅匪明哲则。","逆取苟毫芒，渔怨常十百。","仄闻清静理，固不在资墨。","刀锥将尽争，何以禦民忒。","厉禁如可堕，商旅返安宅。"]},{"t":"舟中望山寺","f":"五言古诗","c":["蜀江历邅回，晨帆逐光景。","峥嵘山谷间，有敞青莲境。","丹碧沦浩劫，势面犹深整。","禅板无灵音，风铎暂一领。","世尊不可曕，讵辨祇树瘿。","老衲缺施金，敝履汲荒井。","忆逢太虚师，缁流颇修颖。","为我谈法华，覼缕良夜永。","无生非我学，弃置不遑省。","转盻三十秋，此地亦芜梗。","□宗老涪翁，诗派沿五岭。","或持弟子法，荤饮时复屏。","遗篇落我手，小句贝文警。","乃知盛名下，精驳尽兼并。","伤哉留滞怀，毵毵素垂颈。","疲薾谢书帷，归弄黄湾艇。"]},{"t":"忠南悼舅氏也舅氏萧公曩为忠守去且四十年忠人追祀之衷既展拜祠下退而赋忠南","f":"五言古诗","c":["忠南在三川，风俗自朴美。","挂席朝雨歇，薄暮舣江涘。","金马有遗老，耋岁尚发齿。","入丹每再拜，咄咄谈刺史。","忠劳首敬舆，名德复居易。","贤迹殊后先，屈指刘与李。","圣朝置守来，畴可萧公比。","自公移合来，蒲鞭且不使。","谕民必真淳，谕士必廉耻。","谕赋赋期集，谕暴暴立已。","去忠四十年，慈惠日在耳。","俎豆跻四贤，微公义安起。","语竟继以□，冥漠一逝水。","谁为后来者，椎骨恒及髓。","慨惟我舅氏，异政山东纪。","兴薄南野青，绶解治中紫。","家食止素业，□资缺妻子。","悽其盖棺日，破屋见新主。","汩汩荡蘼流，转觉寒约鄙。","向无词苑碑，人心几不死。"]},{"t":"雨叹","f":"五言古诗","c":["巴江六计程，零雨日三四。","初犹挟旸辉，倏忽万山翳。","吾踪逐凫鹜，心疚匪一事。","况闻徒御諠，日昃无爨处。","无爨汝苦饥，心疚我苦瘁。","公私各有役，讵得论贱贵。","老渔指前峰，此候势霶霈。","未暇虞舟航，即恐沉厚地。","何当断云根，掣碎雨师旆。","居然见廓清，一使行者快。"]},{"t":"棹歌","f":"五言古诗","c":["击鼓相棹歌，歌促鼓亦促。","官程远何之，丁丁咏伐木。","请伐旷野林，勿伐幽人谷。","衡茅苟无庇，何以佐子育。","渐渐麦穗齐，我饭行当足。","愿大天子居，万国同载覆。"]},{"t":"别夏舜俞","f":"七言律诗","c":["江流争似故情长，小棹今朝为我将。","萱草一帘空有恨，桐花三月谩如霜。","卜居好近青山郭，问俗聊过锦水乡。","西徼南湖休记省，白头书剑足新狂。"]},{"t":"新月","f":"七言律诗","c":["木洞江头新月明，疏星点点急滩声。","星随南斗临三峡，月近东岩闻二更。","吠犬尚多群盗警，吟猿端为独游情。","可怜千里无空谷，未了年来户口征。"]},{"t":"朝天驿","f":"七言律诗","c":["春风处处倚江楼，挟雨微寒亦未收。","天上舟航疑远域，眼中山水信名州。","列邮飞羽劳师日，独夜题诗短鬓秋。","隔浦松篁更深净，可无高蹈侣轻鸥。"]},{"t":"过刘维新冰石堂话旧","f":"七言律诗","c":["鸣鸟嘤嘤春可怜，渝州晚郭竹林烟。","龙台径侧青峰寂，冰石堂高绛烛然。","辉览向从千仞表，剧谈不啻五年前。","袖中封事还匡济，好附长风到九天。"]},{"t":"鱼洞驿别维新","f":"七言律诗","c":["四载孤踪万里同，便如名玉照葭丛。","薇花共忆迟迟日，鸿翼分飞款款风。","恋旧情知尘世外，著书心到古人中。","最嫌鱼洞沙头月，掩映肩舆榉柳东。"]},{"t":"清明舟中","f":"七言律诗","c":["杜陵寒食舟中饮，独客兹晨浪自同。","霏雨满天分野火，低云随眼暗江枫。","青郊旧约啼莺里，紫陌生涯小燕东。","春去夏来何所事，可堪推引各成翁。"]},{"t":"江津谒见素祠二首 其一","f":"五言律诗","c":["四野耰锄子，乘时亦长雄。","黑祲连剑外，黄纸下莆中。","仗钺星辰动，推衣将卒同。","西征遗咏在，未尽纪戎功。"]},{"t":"江津谒见素祠二首 其二","f":"五言律诗","c":["俎豆贤祠远，精灵故老伤。","武侯忠不替，清献道难忘。","江汉真长逝，乾坤自耿光。","经过春草后，泪尽百蛮乡。"]},{"t":"僧夫","f":"五言律诗","c":["削发仍烦障，缘随太俗忙。","未知依宪节，得似引慈航。","白辍斋时磬，谁拈佛日香。","何当息徒御，归尔旧清凉。"]},{"t":"偶述四首 其一","f":"五言律诗","c":["战戟森森在，浓云浩浩奔。","鬓星随日上，花雾□江浑。","近野纡樵道，荒城惨燹痕。","如闻新鬼哭，寒食尚游魂。"]},{"t":"偶述四首 其二","f":"五言律诗","c":["路积分屯转，郊居避难逃。","长亭无马渡，深栈且猿号。","飞将旌旄壮，参军羽檄劳。","肯交耕牧子，裘带谓吾曹。"]},{"t":"偶述四首 其三","f":"五言律诗","c":["黄麦渐可刈，红蕖何未华。","幸逢江上客，一问郭西家。","饷韭聊晨馔，然松已暮笳。","荒畬有春事，愁杀动军牙。"]},{"t":"偶述四首 其四","f":"五言律诗","c":["濯锦清溪水，投书急舸风。","溪含岷雪冷，舸向峡江东。","休唱无家别，能令暗泪红。","谁知闲几格，恰近旧醑翁。"]},{"t":"薄暮","f":"五言律诗","c":["薄暮拢沙浒，鸣桡鸂鶒飞。","兴依明月宇，迹扫白云扉。","绿荔戎州近，青兰楚泽违。","穷源张博望，汉上几时归。"]},{"t":"角","f":"五言律诗","c":["哀角因风听，天东月晕生。","遥闻鬼方寇，近合水西兵。","缟练征人妇，青灯独夜情。","此中多苦调，休弄早秋声。"]},{"t":"莴苣","f":"五言律诗","c":["传人将野苣，雨色尚萋萋。","旧圃名春菜，繁根削夏畦。","村盆寒逼瓦，豪箸刺妨犀。","子美他时兴，狂歌付瀼西。"]},{"t":"南溪","f":"五言律诗","c":["岷峨何日雨，新涨下南溪。","自作楼船客，长留江槛题。","蹲鸱春未老，谢豹夜还啼。","意气从衰飒，那堪听鼓鼙。"]},{"t":"与晁汝吉陈汝忠二参相翠屏山院宴集","f":"七言律诗","c":["小堂幽色翠屏分，列巘真看万马群。","树杪白虹还远涧，眼前苍狗足浮云。","孤踪暂引江山兴，二妙能张翰墨军。","笑咏却兼怀古思，沉碑谁吊石潭文。"]},{"t":"三月晦汶川北谒诸葛武侯涪翁太史祠与晁陈二参相山亭宴别","f":"七言律诗","c":["丛祠遥在北江隈，晴丽山川历历开。","一代风骚文节老，三分天地武侯才。","崖阴石径才容履，溪曲春流旧泛杯。","何幸来游同我友，清谈未了别筵催。"]},{"t":"医僧","f":"五言古诗","c":["桂岭气恒燠，平陆湿以卑。","我行三阅岁，瘴疠夺清姿。","不虞子春忧，一蹶几如痿。","华扁骨已朽，奇疾世罕知。","出滇复入楚，药物随土宜。","迩来渐有瘳，终觉筋力衰。","头簪便拟掷，家山长梦思。","趋立天苟限，安用登临为。","今年西走蜀，逢僧乃良医。","方制岂泥古，针砭宁谩施。","药性本草外，潜神得黄岐。","为煮金匕剂，如濯炎乡腄。","长风扫宿翳，老叶辞新枝。","病根自此拔，奔马行可追。","我欲竟其术，诀秘难赘词。","白粲固微饷，道色终相訑。","医家百蹊径，一一堕樊篱。","济人不责报，此义良可推。","袈裟日挂壁，静业还精持。","岂常屡折臂，改服沦于缁。","十旬闭我户，有涕双涟洏。","疮痍日满眼，垂老惭剃髭。"]},{"t":"次韵答维新鱼洞别后见怀","f":"七言律诗","c":["春流聊爱泛连漪，莫浪风声拟四其。","乘传物华貂袖短，入山家累鹿车迟。","灯花对我参横夜，玉树依君岁晚时。","巴峡荆门天共远，独应江汉附深期。"]},{"t":"四月八日涪陵舟中读东坡食荔枝诗戏和一首","f":"七言古诗","c":["我生不及曹溪卢，一定与岁终荣枯。","西游两月数千里，耳目总被江山驱。","家林忽忆荔枝节，洒若瑞露浇尘肤。","青堤翠浦少隙地，绣幔不屑围名姝。","筠笼首荐四月八，光价未便倾坤隅。","天浆异种熟壮夏，水晶火齐难精粗。","涪翁误赏廖家䋏，恰似江芡誇蠙珠。","福州胜画亦足味，敢与进奉争芳腴。","东坡日啖三百颗，齿颊肯挂松江鲈。","荔仙亭上赋归去，炎云烂熳沧洲图。"]},{"t":"出峡","f":"七言律诗","c":["白帝城边晨出关，昭君村下午移湾。","江流谩诧鸳鸯漩，天府仍深虎豹闲。","素卷有时长照眼，浊醪无分一开颜。","何如植杖西林晚，目送浮云海燕还。"]},{"t":"次韵答高吾见赠","f":"七言律诗","c":["东山隐逸还清望，南楚疮痍旧拊搔。","落笔惯看飞鸟劲，出林时讶箨龙高。","将依五柳延三益，懒发孤樽侍二豪。","著述最关经济事，牙签万轴座周遭。"]},{"t":"次韵高吾园亭杂咏四首 其一","f":"七言绝句","c":["青野缁尘暂隔开，春潭真爱绿如苔。","雨过林杪神鸦噪，花动离根鬼蝶来。"]},{"t":"次韵高吾园亭杂咏四首 其二","f":"七言绝句","c":["远心亭子鹿溪偏，点破晴沙白鹭眠。","压倒鹅黄美春酒，将谁同上木兰船。"]},{"t":"次韵高吾园亭杂咏四首 其三","f":"七言绝句","c":["千年玄鹤首如瓜，一到桃川古水涯。","已籍白云裁白苧，怪传黄帕走黄麻。"]},{"t":"次韵高吾园亭杂咏四首 其四","f":"七言绝句","c":["郡山矗矗绕山居，野色仍多水竹馀。","布袜青鞋乘小驷，更修何服是吾初。"]},{"t":"高吾得孙有作识喜次韵奉贺","f":"七言律诗","c":["佳色经时弥近郭，异声前夜彻高邻。","喜浮綵笔诗能细，春逗瑶觞酒欲频。","芸馆会增风宪额，珠庭殊逼凤毛真。","老予不比寻常贺，添一年家世讲亲。"]},{"t":"贺闻山杨太卿得子用高吾得孙韵","f":"七言律诗","c":["何处威弧张晓日，龙山灵淑诞时邻。","不妨日角惊人晚，已叶兰芽入梦频。","定识三鳣堂上旧，竟传千卷业中真。","高吾宅相年来足，须信王符有外亲。"]},{"t":"寿菊所姊丈七十一","f":"七言律诗","c":["芙蕖胜锦照芳辰，山海横图寿意新。","闻道酡颜红似玉，正堪风鬓白于银。","西池有分逢青鸟，南国于今见大椿。","看到云仍馀庆泽，祇应偕老对如宾。"]},{"t":"晓发界亭","f":"七言律诗","c":["小邮吹唤鸡号急，束燎荧荧石路弯。","残月到岩犹带树，遥空如水欲浮山。","銮声已走边声马，林影仍栖露影鹇。","本为仆夫谢烦暑，远怀无限晓行间。"]},{"t":"次韵答潘希召","f":"七言律诗","c":["散发行追□所凉，映花偏似锦溪堂。","缁冠遂乞青霞境，綵笔曾登紫殿廊。","石室几年收野史，诗坛何地着清狂。","欲知浩兴还多少，试与辰江约短长。"]},{"t":"悯雨","f":"七言律诗","c":["岂谓阴阳虚辟阖，何堪山泽闭氤氲。","田家自击雩神鼓，城府谁为遣社文。","螮蝀有光空映涧，蛟龙何意谩屯云。","行人渴死不知数，为报南征早策勋。"]},{"t":"蝇","f":"五言律诗","c":["棕拂挥仍集，微躯亦羽翰。","点将书格涴，吸得砚池乾。","落耳声何杂，穿帷首复丹。","祛除云有术，未若上高寒。"]},{"t":"蚊","f":"五言律诗","c":["化草形偏绿，污池族转盈。","燃鲡吾未暇，摇羽仆还更。","此地诗人况，他时烈女情。","和神何处国，蛇虺不曾生。"]},{"t":"候雨","f":"五言律诗","c":["□□□山色，浓云一黯如。","需凉先拂簟，迎溜欲疏渠。","不□神巫术，宁无御史车。","愿言终利济，切莫散空虚。"]},{"t":"观雨","f":"五言律诗","c":["膏泽亦多少，檐沟已沛如。","清斋还作客，灵贶岂因渠。","迅扫炎风驭，翻沦畏日车。","幸沾三楚足，毋使万仓虚。"]},{"t":"夏夜叹","f":"五言古诗","c":["夏夜□云促，永怀殊未然。","南薰杳莫致，延盻清秋天。","鸺鹠笑静木，蝙蝠巡高檐。","掠拾尽蚤蚋，微智各自宣。","马卿肺渴久，杜子头风偏。","斯人北邙土，文字珠斗悬。","我观茂陵作，载咏蜀道篇。","方其在世时，资身良足怜。","东海有青凤，不食甘与鲜。","天寒竹实死，忍饥向三年。","腹枵翮无力，暂上扶桑颠。","神游幸一见，为之抱悁悁。"]},{"t":"辰江晓渡","f":"五言古诗","c":["鸡鸣渡辰江，星月在江水。","星摇月亦动，予楫敢不理。","残梦未可续，木末绪风起。","悠然入我怀，曼肤罢挥泚。","升车陟云岑，夺眼明霞紫。","何当炼以飧，永此劬瘁齿。"]},{"t":"罗旧道中小雨","f":"五言古诗","c":["云姿当我意，雨脚漏山光。","润物功斯在，沾鞋湿未妨。","寒泉哀玉转，秋稻蕊珠香。","缕细风还断，声微夜却凉。","更馀清道力，讵重过时伤。","莫洒牂牁去，层峦峻以长。"]},{"t":"方池","f":"五言律诗","c":["方池方丈许，泉脉亦沄沄。","竹影风烟入，蛙声日夜闻。","波澜终不起，泥滓倘相分。","妒杀浮萍绿，应妨看縠文。"]},{"t":"辰溪晚发二首 其一","f":"五言律诗","c":["暂遣车徒逸，婆娑独树原。","晨麾辞露磴，晚柁指风门。","旱电幽岩白，游燐远溆昏。","极知新月好，惜未上山樊。"]},{"t":"辰溪晚发二首 其二","f":"五言律诗","c":["息鸟争枝定，孤舟避暑行。","客忘竽瑟好，石弄鼓钟声。","雷斧惭虚假，星枢望独明。","浮生鲜扃钥，魑魅哂摅倾。"]},{"t":"辰阳七夕江中纳凉","f":"五言律诗","c":["微风披石壁，馀爽度棕林。","搔首生秋兴，移舟泊水心。","炎蒸将出伏，岑寂欲横参。","若个红楼喜，天孙得幸临。"]},{"t":"中夕骤雨","f":"五言律诗","c":["山月纤纤下，江星落落收。","鹊回河鼓静，神到楚台幽。","破块滩声壮，萦丝树色浮。","蛮溪秋潦发，吾亦任轻舟。"]},{"t":"鱼梁","f":"五言律诗","c":["截浦情兹费，悬虹势渐攲。","滥觞疑网罟，结构想樊篱。","鱍剌鳞难纵，骧腾首讵垂。","詹何堪共老，直钓旧曾施。"]},{"t":"舟中望桃源洞","f":"七言古诗","c":["鸣桡昼下白马渡，仆夫指我桃花源。","洞门八里步窈窕，不与尘世通朝昏。","乔松方竹递根裔，野鼠窃返神丹魂。","念昔之官蹈滇海，吊古一再停驺轩。","石桥药鼎足恍惚，黄冠俗态难为言。","只今星纪动七阅，碌碌已四经丘樊。","云林未便太幽秘，避地尽道神仙村。","漏疏稍辩汉图籍，局促真觉秦乾坤。","先王固有不治地，遗顽无亦商忠惇。","提封圣代迈千古，薄海内外车书尊。","紫芝逸老服陇亩，红桃不放桑麻原。","閒人岂复问津到，破屋屡见逃租奔。","轮蹄终岁峻坂滑，予亦晚傍风亭餐。","寄怀何必尽真迹，画舸欲缆江凫翻。"]},{"t":"寄寿顾封君","f":"七言律诗","c":["未羡璜溪草六韬，新秋云渚大星高。","金陵许并清强骨，宝录全收利济劳。","海上蓬壶留画史，眼前钟鼎侍仙曹。","年家我愧称觞晚，一隔潇湘已二毛。"]},{"t":"落齿和坡山四首 其一","f":"五言律诗","c":["我髭白无算，君齿落云六。","久知老见侵，岂有丹可服。","秋英吐鹅毛，秋粳曝虾肉。","岁晏得养生，细啖茯苓粥。"]},{"t":"落齿和坡山四首 其二","f":"五言律诗","c":["齿落岂遽衰，便如月望六。","圆影或暂亏，清光尚九服。","蔬厨茹紫甲，岂必花猪肉。","愿母废笑歌，世事釜中粥。"]},{"t":"落齿和坡山四首 其三","f":"五言律诗","c":["我读落齿诗，颖尾老欧九。","漱泉吟不妨，崩山势何有。","熊车载二馀，尚足荡群丑。","而况豪俊贤，且歌将进酒。"]},{"t":"落齿和坡山四首 其四","f":"五言律诗","c":["蚤岁辍晚飧，讵望九十九。","皓齿舍我去，更生理恒有。","龈腭足完洁，缺一未必丑。","旷放怀昔人，适处不在酒。"]},{"t":"答彭给舍","f":"五言古诗","c":["西川富名迹，士也多卓谊。","夕郎矫矫姿，振履足馀地。","声吹玉垒云，思掩金闺吏。","拟之古铜镜，持以照妖魅。","严程下巫峡，观者日鳞比。","伏枕一见之，使我发潜愧。","肆口论疮痍，恻恻念枯瘁。","遗我刀圭方，琼玫不足譬。","感兹眷切怀，冻席失沉痹。","细玩蕲水章，衰颜动春睟。"]},{"t":"题光泽卷三首 其一 博文堂","f":"五言律诗","c":["奂构贤王邸，高颜孝庙书。","董帷深閤夜，郑草细阶除。","挥洒雄篇富，周旋约礼馀。","国人钦令德，堂下少长裾。"]},{"t":"题光泽卷三首 其二 红梅图","f":"五言律诗","c":["梁园无此种，上苑几年移。","独抱冰霜骨，休誇粉腻姿。","春风吹蕊蒂，绛雪缀繁枝。","写向王孙赠，能深玉叶思。"]},{"t":"题光泽卷三首 其三 止庵","f":"五言律诗","c":["不倚分茅重，居然儒素风。","常师老氏外，取善孔门中。","树静盘根古，波澄鉴物空。","美哉斋榜义，带砺与天同。"]},{"t":"射逃河","f":"七言古诗","c":["炎曦正转池亭午，逃河集我青莎渚。","苍翎慱吭寂无声，在梁气势粗如许。","小鱼深遁萍底踪，大鱼鬐鬣何曾鼓。","观鱼微意在群动，敢厌腥臊吾怪汝。","呼奴捲臂引繁弱，一发遂饮玄鸦羽。","寻常濡咮那复得，快意厨人请烹煮。","官庖岂必须汝肉，磔之用戒伤廉取。"]},{"t":"题高吾院长特恩堂","f":"七言律诗","c":["桃花流水绕斯干，曾上元龙旧肯堂。","日月共悬天上语，风云重殿楚东方。","自堪国士酬知遇，定与邦人作典章。","家庆不妨繁复纪，凤毛千仞会飞翔。"]},{"t":"审录口占寄和沂乐廷卿","f":"七言律诗","c":["剑履群仙出禁来，恢恢汤网一时开。","圆扉宿草看先沃，丹笔南山挽却回。","宽大共祇天子诏，平反端羡月卿才。","炎歊近走幽沉檄，再拜瑶篇到楚台。"]},{"t":"夏夜","f":"七言律诗","c":["闲庭暑气夜方微，苍佳萧森蝙蝠飞。","已对银蟾升皎皎，不妨萤火弄辉辉。","侦宵鸣柝分城度，拢岸高帆截浦归。","到枕自多云水梦，可知心与世情违。"]},{"t":"乡思","f":"七言律诗","c":["回雁峰前引望时，侬家应在海天涯。","别来不但星霜感，老至何堪骨肉悲。","山户长甘邻乳虎，溪翁无分饱蹲鸱。","疏慵谩有明农思，一亩茅茨安所之。"]},{"t":"梅岭谒曲江公祠","f":"七言律诗","c":["科名伊吕恰相当，何许燕公托后行。","海上衣冠今尔尔，山中风度复堂堂。","尘埃不见渔阳恨，絮酒徒闻蜀道长。","可信柳州还墨客，未窥经济论文章。"]},{"t":"归次石门望白云山","f":"七言律诗","c":["惊心鬓影临春水，落耳乡音卖晚花。","断屿白沙孤艇小，远林红荔一溪斜。","早农有喜将登谷，归客无期偶及瓜。","满径槐风披药草，白云山下即吾家。"]},{"t":"韩祠","f":"七言律诗","c":["青史鸿名泰岳高，品题不但称诗豪。","平津道远三书罢，古赋词华二鸟遭。","自有神明扶信义，不烦泷吏诉波涛。","陇西门下诚何意，滴酒丛祠感鬓毛。"]},{"t":"赠小江黄宪副入闽便道省母","f":"七言律诗","c":["琴书千里一轻舠，岭海澄清仰豸袍。","苍柏影摇南国远，绛榴花丽北堂高。","履逢圯下机方秘，诗到涪中句转豪。","榜上宗盟予负我，谩随耆旧拜旌旄。"]},{"t":"庄上和陈坡山四首 其一","f":"七言绝句","c":["绝粒明朝儗饭松，城中便道偓佺翁。","葛巾葵扇潮头坐，不信凫鸥有异同。"]},{"t":"庄上和陈坡山四首 其二","f":"七言绝句","c":["种树莫种杨白花，飞风沾雨满人家。","苍楸百尺垂崖石，可是闲堂少物华。"]},{"t":"庄上和陈坡山四首 其三","f":"七言绝句","c":["小凿春园浴鹭塘，鹭飞吾意亦俱忘。","东庄只是东城土，不道城东别有乡。"]},{"t":"庄上和陈坡山四首 其四","f":"七言绝句","c":["世上徒闻四海宽，白头浪里叹漫漫。","何如一曲东涌水，不负陶潜早去官。"]},{"t":"屏居","f":"七言律诗","c":["两年湖上偶垂幨，浪得儿童讶皓髯。","西省薇花天自管，南溪茅屋岁将淹。","馀生春到分龙眼，病骨晨兴问虎潜。","静扫幽除看洗竹，薰风时动月纤纤。"]},{"t":"赠菊潭师","f":"七言绝句","c":["花落青林早闭关，禅心不独静时闲。","虎溪去后无奇迹，一叶芦风左里还。"]},{"t":"韶阳诸山和唐士絅","f":"五言古诗","c":["端居有素赏，适远无可欲。","忽见韶阳山，徙倚负初旭。","临胜辄改容，缓带不遑束。","乃知石丈奇，遐心委幽独。","楚人誇九疑，越客谈天目。","胡为混尘埃，吾方怨亭毒。","宛尔鸾鹄翔，瞥若熊豹伏。","又如矢心人，附耳相申告。","谁能荫芳茅，勿使风雨触。","何必桃花源，胡麻此中熟。"]},{"t":"赠栎坡少参兄赴江西省","f":"五言古诗","c":["炎宋愁胡日，中州王气消。","贤人多隐避，华胄每迁侨。","梅岭传新火，鸿洲叙旧佋。","偶来观阀阅，谁敢托柯条。","弱岁专英誉，清朝服大寮。","葭心尝附玉，凤翼恰披鹩。","听句银灯夜，鸣珂紫陌朝。","风流疏鄙吝，简易识高标。","冢宰亲题品，名公久见招。","九迁真不忝，一面独当饶。","帝念忧遗老，黎元待沃焦。","乃知衔敕意，何止算缗愮。","范老江湖切，王乔履迹遥。","春容和客帐，夏首倚兰桡。","促席虽光彩，分程恐寂寥。","滕王高阁月，杨子大江潮。","明日袍犹恋，深秋榻正枵。","题诗谢缱绻，江雨直相撩。"]},{"t":"鲸海波平","f":"五言古诗","c":["远舶乘南岛，方夷犯国程。","天王正神圣，廉使且忠贞。","走檄馀艎集，挥戈落日明。","射波鱼眼暗，冲雾蜃楼倾。","肯以黄犀贵，仍知白雉轻。","无劳揭铜柱，所庆答苍生。"]},{"t":"胥江","f":"五言绝句","c":["颊夺银镮白，花饶绢袖红。","听歌江上客，愁杀荡舟风。"]},{"t":"读坡山诗集","f":"七言古诗","c":["太丘今古洽六腑，中夜皛瑩腾方床。","我观逸思副奇表，头骨峭崿昆崙冈。","追风琢月二十载，嚼花咽玉凝芬芳。","齐侯铜篆漫柏寝，石鼓颢气争堂堂。","宁知剞劂夺情状，混沌百窍纷开张。","孽虬赭卯尽稿殈，十日雨粟愁穹苍。","天孙断纬泣倚杼，鬼物掩耳投空荒。","帝忧五气落煅炼，坐恐侵蚀干三光。","鞭龙掣电纵大索，雷斧劈石疑深藏。","冲垣决栋遍城邑，不道大锦蒙宫商。","斜封密付有所以，欲使萤火窥初阳。","西窗病骨战寒热，初吟泚额翻清凉。","移床向月再把咏，老桧倒影洪钟鸣。","三回彻卷立叹息，瘦马局蹐号蛩僵。","人工天巧稍抉摘，畏复冰炭交回肠。","易城毕竟归赵垒，愿致私语能毋忘。","吾闻良价贵秘蓄，勿为花竹矜毫芒。"]},{"t":"和唐士絅","f":"七言律诗","c":["夕郎白皙仍青春，黄扉落笔傍无人。","当年但爱心骨老，今日犹窥诗兴新。","女儿意气衰避好，蚊翰亦笑南山小。","秋堂隐几覆玄经，不道时人终不晓。"]},{"t":"承坡山东郊之约借马日昃不至","f":"七言律诗","c":["东郊雨后更芳华，出郭无过二里赊。","石径尘收凡界远，绳枢星散野桥斜。","闲情未少青林寺，并辔何曾白鼻騧。","日夕有怀空徙倚，寂寥无奈瀼西家。"]},{"t":"次韵答朱升之","f":"七言律诗","c":["曼倩归来岁月穷，因君兴叹倚西风。","全家不满中人产，孤剑谁论上客功。","梦落桃花流水曲，心期桂树小山丛。","凭诗慰我愁生处，未信曹刘并七雄。"]},{"t":"挽钟紫村","f":"七言律诗","c":["意气平生盖万夫，伤心千古恰须臾。","郎官虽贵才终负，文字堪传道未孤。","堂上自怜慈母老，眼前吾恨友人无。","岩霜九月空荒草，谁送刍灵返瞑途。"]},{"t":"清远阻雨闻警","f":"七言律诗","c":["江驿萧条江水明，卷旌聊此辍王程。","千山送雨风霆壮，四野传烽寇盗横。","骑吏羽书乘传去，丁夫宵柝傍船鸣。","家人莫怪还坚卧，利害年来渐饱更。"]},{"t":"峡涨","f":"七言律诗","c":["鹤怨猿号几百盘，双崖峭崿贯飞湍。","船从骤骥隙中过，天向醯鸡瓮里看。","古寺遥钟催暮色，灌林微雨挟朝寒。","渔翁笑指稽程客，信有人间行路难。"]},{"t":"遣怀和丫山二首 其一","f":"五言律诗","c":["慵至时抛卷，兀然还返观。","将腾踏雪杖，先挂切云冠。","鹤径嗟何渺，鸥波讶许宽。","野人浑野性，无处动悲欢。"]},{"t":"遣怀和丫山二首 其二","f":"五言律诗","c":["曾泛黄湾艇，东南亦巨观。","谁还工鼓瑟，那复庆弹冠。","兴薄孤烟迥，谈狂六合宽。","自来幽适地，鱼鸟尽交欢。"]},{"t":"雨夕二首 其一","f":"五言律诗","c":["积雨昏秋暮，新寒薄曙衣。","雁还随候至，客亦倦时归。","力淡堪垂橐，追前合佩韦。","最怜羊仲坞，相对掩荆扉。"]},{"t":"雨夕二首 其二","f":"五言律诗","c":["风缓纤纤整，更寒浙浙长。","色生金橘润，愁淡木犀芳。","遐瞩嫌衰谢，孤怀信渺茫。","娟娟公子兴，摇落复山乡。"]},{"t":"热","f":"七言律诗","c":["烁石流金后土乾，离宫还自厌轻纨。","骇牛畏日吼奔涧，饥鹘窥阴倦矫翰。","七尺正便花簟薄，一心懒倚冰山寒。","岸巾摇扇无休地，谩道南曹是冷官。"]},{"t":"拟古贫将咏","f":"七言律诗","c":["家在平陵素业空，东门无意傍瓜丛。","誓捐宝玉三秦利，耻与侯王五道功。","冠敝可能胜怒发，肩臞犹有讶重瞳。","夜观太白孤城上，击筑酣歌入沛中。"]},{"t":"怀坡山","f":"七言律诗","c":["忆上元龙刻烛坛，大床曾借卧袁安。","东郊试艺鸦翎箭，西寺寻芳豹革鞍。","亭槛来薰晴鸟媚，柁楼衔月曙鸡寒。","拊髀当慰思才叹，怅望非因惜阻欢。"]},{"t":"濛里渡口候林伯乔舟不至","f":"七言律诗","c":["倚楫联樯上下滩，棹歌声入小长干。","回看独泛仙踪渺，谁念同游客思阑。","远水人归空野渡，古祠龙去有荒坛。","雨馀更向孤蓬望，几点渔灯逼暮寒。"]},{"t":"挽淩江萧处士","f":"七言律诗","c":["白猿峒下感秋人，梦断塘蒲掩葛巾。","文藻旧齐梁太子，家声遥系汉宗臣。","鱼肠蜿蜿铜花冷，马鬣累累石笋春。","莫恨无人昌世绪，青袍今是席中珍。"]}]};